pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residue classes mod 10
    let class = post_residual % 10;

    // Dead-space classes (unusable for typical small items) get penalized
    if class == 1 || class == 2 {
        score += 12.0;
    } else if class == 3 {
        score += 6.0;
    } else if class == 0 {
        // Perfect fill classes are strongly rewarded
        score -= 15.0;
    }

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small leftovers that can host next item are rewarded
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // leftover cannot host next item: penalize by the gap
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Integer-division threshold on post_residual: halves / quarters of capacity
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual > half {
        score -= 10.0; // still roomy bin, good to fill
    } else if post_residual < quarter && post_residual > 0 {
        score += 8.0; // fragmenting a nearly-full bin is wasteful
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if mean_residual < item_size as f64 {
            score -= 25.0;
        } else {
            // discourage opening new bins when reasonable fits exist
            score += 30.0 * (1.0 - pressure);
        }
    }

    // Stream progression: early on, be slightly more willing to spread (open bins);
    // late, prefer packing tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0;
    score += progress * 3.0;

    // Mild tie-break toward bins already below mean residual (balance avoidance)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual matches next item size exactly or closely.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 800.0; // perfect 2-chain: fill this bin with next item too
        } else if post_residual >= next_item_size {
            score -= 300.0 - gap * 1.5; // next item still fits here
        } else {
            score += gap * 2.0; // dead space that next item cannot use
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is below mean
    // (filling tighter-than-average bins first).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate handling: empty bin gets a penalty so we only open
    // a new bin when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 400.0;
        // But if item is huge relative to capacity, opening fresh is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 350.0;
    }

    // Penalize leaving small unusable slivers (1..10) that nothing can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Late in stream: be more conservative, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 30.0;

    // Many open bins: prefer consolidating into existing ones.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing (min size 1..100 unknown,
    // but typical items >= 10) can use are wasted. Penalize small gaps hard.
    if post_residual > 0 {
        // A residual is "usable" if it could hold a reasonable chunk of future load.
        // Treat gaps < 15 as near-dead, ramping penalty quadratically.
        if post_residual < 15 {
            score += (15.0 - post_residual as f64) * (15.0 - post_residual as f64) * 0.8;
        } else if post_residual == 0 {
            score -= 30.0; // perfect fit bonus
        }
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    }

    // Tight-fit gradient: reward filling most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new one (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit, or when the item would leave a large dead gap anyway.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by lookahead usefulness.
        score = bin_capacity as f64 * 0.9;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // the new bin can also host the next item
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If only the new bin fits, it must be chosen: make it competitive.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    }
    // Penalize leaving a gap the next item barely misses (dead space coupling).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.3;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (it's a "leftover" bin), prefer consolidating into it.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of fit: fraction of residual consumed by this item
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };

    // Reward tight fits strongly (subtract more for larger fit_ratio)
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving small unusable dead space (dead zone below min item size 1..=10)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward preserving that space
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
    }
    // If next item would NOT fit here anyway, mild penalty for wasting space
    else if next_item_size > post_residual && post_residual > 0 {
        score += 2.0;
    }

    // Global state coupling: if mean residual is high, prefer consolidating into existing bins
    let mean_res_gap = mean_residual - post_residual as f64;
    if mean_res_gap > 0.0 {
        score -= 0.05 * mean_res_gap;
    } else {
        score += 0.05 * (-mean_res_gap);
    }

    // Many open bins -> encourage closing them out (favor bins with small residual)
    if open_bins_count > 4 {
        score += 0.3 * (post_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln();
    }

    // Early stream: be conservative, prefer new bins over fragmenting; late stream: pack tightly
    if progress < 0.2 {
        score += 3.0 * (1.0 - progress / 0.2) * (post_residual as f64 / bin_capacity as f64);
    } else {
        score -= 3.0 * progress * fit_ratio;
    }

    // New-bin candidate handling: empty bin gets baseline score; open a new bin only when
    // fits elsewhere are poor (large post_residual relative to capacity) or few open bins
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins already open or early stream
        let mut new_bin_cost = 18.0;
        new_bin_cost -= 2.0 * (open_bins_count as f64).min(10.0);
        new_bin_cost -= 5.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is natural
        new_bin_cost -= 0.1 * item_size as f64;
        score = new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any gap smaller than the minimum item size is wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable dead space
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: fully consume the bin
    }

    // Reward tight fits (small post_residual relative to capacity).
    score += 0.6 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64 - item_size as f64);

    // Penalize bins whose residual is far above the item (loose fit) mildly; tightness already favored.
    if (bin_residual as f64) > mean_residual {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bin pressure: discourage scattering across many bins unless the fit is excellent.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 + progress);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin fits well
    // (i.e., when this call is the empty-bin call) and current bins have large scattered residuals.
    if bin_residual == bin_capacity {
        let waste_pressure = (mean_residual - item_size as f64).max(0.0);
        // Base cost of a fresh bin; cheaper late in the stream when residual fragmentation is high.
        score = 45.0 + waste_pressure * 0.4 - 10.0 * progress;
        if post_residual < 10 {
            score += 40.0; // fresh bin post_residual == capacity, never triggers, kept for safety
        }
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0; // fresh bin can also serve the next item
        }
    } else {
        // Lookahead coupling: prefer bins whose post_residual can still host the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 6.0;
            } else if post_residual > 0 {
                score += 0.3 * (next_item_size as f64 - post_residual as f64);
            }
        }
    }

    score
}

