}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the leftover space exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Leftover can host the next item: mild reward proportional to tightness.
            score -= 50.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize wasted capacity.
            score += 40.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize small unusable fragments (dead space below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bin late in the stream when many bins are open and fits are scarce.
        if fitting_bins_count > 1 {
            score += 60.0;
        }
    }

    // Relative to mean residual: prefer bins that become tighter than average.
    score -= 20.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Mild penalty for spreading across many open bins.
    score += 2.0 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: linear + quadratic in post residual
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer tight fills (penalize residual more); later, be more lenient.
    let tightness = 0.5 + 1.5 * (1.0 - progress) * (1.0 - progress);
    score *= tightness;

    // Cubic interaction: residual^3 scaled by progress to smooth late-stream behavior
    score += 8.0 * norm_pr.powi(3) * cap * (0.5 + progress);

    // Lookahead: reward leaving room for the next item (subtract if next item fits in post_residual)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            // smooth reward: perfect-lookahead fit gets strongest discount
            score -= 15.0 * (gap / cap) * (1.0 - (gap / cap - 0.5).abs().min(1.0));
        } else {
            // penalize near-miss: next item almost fits
            let miss = (-gap) / cap;
            score += 10.0 * (1.0 - miss.min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // Mean residual coupling: if this bin's residual is below the mean, it's a tighter fit -> reward
    let dev = (pr - mean_residual) / cap;
    score -= 6.0 * dev * (1.0 - dev * dev.abs().min(1.0));

    // Slight penalty for many open bins to encourage consolidation
    score += (open_bins_count as f64).sqrt() * 0.8;

    // New-bin candidate: penalize mildly unless residuals are all large
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / cap;
        score = cap * (0.9 - 0.4 * avg_pressure) + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "useful"
    // residue class (multiples of 10, and small leftovers) are favored.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 10 == 0 {
        -12.0
    } else if pr < 10 {
        15.0 // dead space below min item size
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: leftovers divisible by
    // common item sizes are more likely reusable.
    if pr > 0 && pr % 20 == 0 {
        score -= 6.0;
    } else if pr > 0 && pr % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly
    // or nearly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // harmonic class of the slack after the next placement
            score -= if slack % 10 == 0 { 10.0 } else if slack < 10 { 2.0 } else { 5.0 };
        } else {
            score += 8.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or this bin's post placement would be wasteful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score -= 18.0 * congestion + 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Prefer tighter bins overall: penalize bins far above the mean residual
    // (they waste space) mildly, reward below-mean (tight) bins.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Small tie-breaker toward fuller bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Best-fit core: smaller leftover after placement wins by default.
    let mut score = post;

    if post == 0.0 {
        // Perfect closure: this item seals the bin exactly.
        score -= cap * 0.5;
    } else if nxt > 0.0 {
        if post == nxt {
            // Aggressive 2-step match: leftover exactly absorbs the next item,
            // closing this bin with two items. Dominant reward.
            score -= 2.0 * cap;
        } else if post > nxt {
            // Next item also fits into the leftover; reward tightness of the
            // second-step leftover (two-step best-fit).
            let second_left = post - nxt;
            score -= 0.5 * (cap - second_left);
        } else {
            // Dead space: leftover cannot host the lookahead item. Penalize
            // proportionally to the mismatch, harder late in the stream when
            // few items remain that could ever fill the hole.
            let urgency = 1.2 + 0.6 * progress;
            score += urgency * (nxt - post);
        }
    }

    // Mean-residual coupling: favor bins tighter than the open-fleet average
    // (drives nearly-full bins to closure). Amplified when many bins are open
    // (fragmentation pressure).
    if !is_new_bin {
        let dev = (mean_residual - post) / cap;
        let crowd = 0.5 + (open_bins_count.min(20) as f64) / 40.0; // 0.5..=1.0
        score -= cap * 0.06 * crowd * dev;
    }

    // Last-chance bonus: if this is the only open bin that fits, using it
    // avoids opening a new bin — unless the fit is truly awful.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= cap * 0.25;
    }

    // Inertia against opening a fresh bin. Small items poked into an empty
    // bin create large useless holes, so the penalty is higher for them.
    if is_new_bin {
        score += cap * (0.02 + 0.06 * (1.0 - item / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let slack = post - next;
            if slack == 0.0 {
                score -= 45.0; // perfect two-item packing
            } else if slack <= 5.0 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - slack / 100.0);
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted lookahead.
            score += 8.0 * (next - post) / 10.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residuals below mean (tighter bins first).
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (post_f - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating dead space that no item (10..80 range) could use.
    if post_f > 0.0 && post_f < 10.0 {
        score += 15.0 * (10.0 - post_f);
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: make empty bins mildly attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; lookahead can discount it.
        let mut new_bin_score = 55.0;
        if next_item_size > 0 {
            let rem = bin_capacity as f64 - next_item_size as f64;
            if rem >= item_size as f64 {
                new_bin_score -= 15.0;
            }
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // must open a new bin
        }
        score = new_bin_score.min(score);
    }

    score
}

