    score -= tight_bonus;

    // Lookahead: reward leaving space for the next item, smoothly coupled with progress
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fit_next = if pr >= ni { 1.0 } else { 0.0 };
        score -= fit_next * ni * (0.3 + 0.4 * (1.0 - progress));
        // penalize residual that is close to but smaller than next item (dead space)
        if pr < ni {
            score += (ni - pr) * (0.5 + poly);
        }
    }

    // Last-chance bin: strongly favor using it, scaled by scarcity of fitting bins
    if fitting_bins_count == 1 {
        score -= cap * (0.6 + 0.4 * progress);
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Mean residual coupling: prefer bins deviating below mean residual early, above later
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * cap * (0.5 - 0.5 * progress) * 0.5;

    // New-bin candidate: penalize opening a new bin smoothly, more so late in the stream
    if bin_residual == bin_capacity {
        score += cap * (0.5 + 0.5 * progress) + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: classify dead space into buckets ---
    // Residual classes: 0 (perfect), tiny (1..=5), small (6..=15), medium (16..=35), large (36..=60), huge (>60)
    let class = if post_residual == 0 { 0u32 }
        else if post_residual <= 5 { 1 }
        else if post_residual <= 15 { 2 }
        else if post_residual <= 35 { 3 }
        else if post_residual <= 60 { 4 }
        else { 5 };

    // Reward low classes nonlinearly; penalize mid classes that produce unusable slivers
    let class_bonus: f64 = match class {
        0 => -60.0,                       // perfect fit: massive reward
        1 => -25.0,                       // near-perfect
        2 => 10.0,                        // small sliver: mildly bad
        3 => 25.0,                        // medium dead zone: bad
        4 => -5.0,                        // large residual still reusable
        _ => -15.0,                       // huge residual: bin stays flexible
    };
    score += class_bonus;

    // --- Integer-division harmonic: how many items of the current size could still fit ---
    let repeats = post_residual / item_size.max(1);
    score -= 8.0 * (repeats.min(4) as f64);

    // --- Modulo coupling between post_residual and common capacity fractions ---
    // Harmonic residuals that align with capacity quarters/halves are reusable by typical items
    for frac in [25u32, 50u32, 75u32] {
        if post_residual >= frac {
            let r = post_residual % frac;
            if r == 0 { score -= 12.0; }
            else if r <= 5 { score -= 6.0; }
        }
    }

    // --- Lookahead: does the next item fit exactly / well into the post residual? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // chain a perfect fit next
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 { score -= 30.0 * (1.0 - gap as f64 / 10.0); }
            else { score += 6.0 * (gap as f64 / post_residual.max(1) as f64); }
        } else {
            // next item does not fit here: residual becomes true dead space
            let overflow = next_item_size - post_residual;
            score += 0.35 * overflow.min(40) as f64;
            // modulo harmony: residual + item size matching capacity harmonics is fine
            if (post_residual + item_size) % 50 == 0 { score -= 10.0; }
        }
    } else {
        // last item: strongly prefer exact closure
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0; // avoid forcing a new bin when this is the only fit
    } else if fitting_bins_count > 1 {
        // with many options, prefer tightest fits: post_residual already dominates
        score += 1.5 * (fitting_bins_count.min(10) as f64);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is good when open bins are fragmented and item is small
        let fragmentation = mean_residual / (bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_bonus = (open_bins_count as f64).ln_1p();
        // new bin score: base + adjustment; attractive if existing residuals are small/fragmented
        score = 100.0
            - 30.0 * fragmentation
            + 20.0 * open_bonus
            - 25.0 * progress
            - if next_item_size > 0 && next_item_size <= item_size { 10.0 } else { 0.0 };
        // don't open new bins if a perfect or near-perfect fit exists elsewhere
        if post_residual == 0 && bin_residual != bin_capacity { score += 1000.0; }
    }

    // --- Mild progress scaling: early on, keep bins flexible ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Minimum plausible future item size: use lookahead if available, else a
    // conservative small-item floor. Gaps below this are likely dead space.
    let min_future = if next_item_size > 0 { next_item_size.min(80).max(10) } else { 10 };

    // STRICT DEAD SPACE PENALTY:
    // A residual in (0, min_future) is almost certainly unusable -> quadruple cost.
    if post_residual > 0 && (post_residual as f64) < min_future as f64 {
        score += 3.0 * (min_future as f64 - post_residual as f64);
    }

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Residual that can still host the next item: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.25 * (post_residual as f64 - next_item_size as f64);
    }

    // Tight fit bonus: reward filling a large fraction of the bin's current space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, using it avoids
    // opening a new bin -> strong reward, growing with how many bins are open.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 2.0 * open_bins_count as f64;
    }

    // Open-bin pressure: mildly penalize spreading across many bins, stronger
    // later in the stream when consolidation matters.
    score += 0.5 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: only attractive when the item would leave a clean,
    // large residual and existing bins are badly fragmented (high mean residual
    // relative to item size) or no bin fits well.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (item_size.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 25.0; // forced: no existing bin can host the item
        } else if fragmentation > 1.5 {
            score -= 8.0; // existing bins are wasteful; fresh bin competitive
        } else {
            score += 30.0; // existing bins fit fine; discourage opening new
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-exact fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this bin becomes perfect after two placements.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let leftover2 = post_residual - next_item_size;
            if leftover2 <= 10 {
                score -= 150.0;
            } else {
                score -= 40.0 * (1.0 - leftover2 as f64 / bin_capacity as f64);
            }
        } else {
            // Next item does NOT fit here: penalize leaving a gap that
            // wastes capacity relative to the stream's typical sizes.
            let gap = post_residual as f64;
            let nxt = next_item_size as f64;
            // gap smaller than next item is a dead zone for the lookahead
            score += 60.0 * (1.0 - gap / nxt.max(1.0));
            // tiny unusable slivers are the worst
            if gap < 10.0 {
                score += 120.0;
            }
        }
    } else {
        // Last item: just minimize waste.
        score -= 50.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates
    // favorably from the mean residual (tighter than average is good).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the
    // item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let tight_fit_elsewhere = fitting_bins_count > 0 && post_residual <= 15;
        if tight_fit_elsewhere {
            score += 250.0; // discourage new bin when a tight fit exists
        } else {
            score += 50.0 + 0.5 * (open_bins_count as f64);
            if item_size >= 70 {
                score -= 100.0; // large items pair well with fresh bins
            }
        }
    }

    // Late in the stream: consolidate harder, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 150.0 * progress;
    } else {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating tiny unusable dead space (< smallest plausible item).
    if post_residual > 0 && post_residual < 8 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual still fits the next item,
    // penalize bins that become useless for the upcoming item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Extra reward if next item then leaves a snug fit too.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 4.0 * next_fit;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 10.0 + 0.05 * (item_size as f64);
    }

    // Prefer bins with low residual among many open bins (consolidation pressure).
    if open_bins_count > 1 {
        let scarcity = 1.0 / (bin_residual as f64).max(1.0);
        score -= 5.0 * scarcity;
        // Mild pressure to fill bins when many are open.
        score -= 0.02 * (open_bins_count as f64 - 1.0) * (item_size as f64 / bin_capacity as f64);
    }

    // Global state: if mean residual is high, be picky (penalize loose fits);
    // if mean residual is low, accept placements more readily.
    let residual_gap = (mean_residual - bin_residual as f64).abs();
    score += 0.03 * residual_gap;

    // Time horizon: early in the stream, keep bins flexible (penalize near-full
    // usage); late in the stream, pack tightly without regard to flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let flexibility_penalty = (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score += 4.0 * flexibility_penalty;

    // New-bin candidate: make empty bins moderately attractive only when no
    // open bin fits well (high post_residual for empty bin = 100 - item_size).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many items remain.
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        score += 8.0;
        if remaining > 20.0 { score -= 2.0; }
        // If the item is huge relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 5.0;
        }
        // If many bins are open with slack, discourage yet another bin.
        if mean_residual > 25.0 && open_bins_count > 3 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer low post_residual (tight fits); later, tolerate
    // slack slightly to avoid opening bins, via a progress-scaled reward.
    let tightness = norm_pr * norm_pr; // quadratic penalty for dead space
    score += 30.0 * tightness * (1.0 - progress);

    // Cubic interaction: large post_residual becomes increasingly costly
    // as the stream progresses (less chance to fill it).
    score += 8.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward bins whose post_residual matches the lookahead item exactly
    // (smooth Gaussian-like kernel instead of piecewise thresholds).
    if nxt > 0.0 {
        let d = (pr - nxt) / cap;
        score -= 25.0 * (-200.0 * d * d).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, penalize
    // alternatives smoothly by subtracting a progress-modulated term.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for scattering across many open bins vs mean residual.
    score += 0.5 * (open_bins_count as f64).ln() * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make it mildly unattractive unless residuals
    // are all poor (smooth comparison via mean residual).
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
        score -= 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score = pr * (1.0 + (pr / cap).powi(2));

    // Harmonic class of post_residual: dead space classes.
    // Class 0: post_residual in {0} -> perfect fit, huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Small unusable residues are penalized more if they fall in awkward classes.
    let cls = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        // dead space below min item size is wasted forever
        score += (10 - post_residual) as f64 * 2.0;
    } else {
        // residues that are multiples of 10 are more reusable
        match cls {
            0 => score -= 8.0,
            1 | 3 | 7 | 9 => score += 3.0,
            _ => {}
        }
    }

    // Integer-division thresholds: can next item fit here?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportionally, stronger for tight chain fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / cap);
        } else {
            // lookahead cannot follow: penalize if this bin becomes near-dead
            if post_residual < 10 {
                score += 20.0;
            } else {
                score += 5.0 * (1.0 - post_residual as f64 / cap);
            }
        }
    } else {
        // last item: just minimize post_residual
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin for a poor reason.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish score anchored to capacity; open a new bin
    // only when no existing bin offers a decent fit (post_residual small enough).
    if bin_residual == bin_capacity {
        // fresh bin score: leaves 100 - item_size; encourage when existing fits are bad
        score = (bin_capacity - item_size) as f64 + 12.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0; // fresh bin can also host the next item
        }
        if fitting_bins_count > 0 {
            score += 10.0; // discourage abandoning usable bins unless they're bad
        }
    }

    // Global pressure: when many open bins exist, consolidate (favor filling
    // below-mean-residual bins); early on, spread slightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (mean_residual - pr).abs() < 1.0 {
        score -= 2.0;
    }
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Harmonic modulo coupling: reward when post_residual shares a class
    // with next_item_size (both multiples of 5/10 align for future packing).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual % 5 == 0 && next_item_size % 5 == 0 {
            score -= 4.0;
        }
        if post_residual % 10 == next_item_size % 10 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are "dead" — penalize them quadratically.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        // awkward mid-range gap: mild penalty that grows as gap shrinks
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction
    // of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: when many bins are open, discourage opening new
    // bins (the new-bin candidate has bin_residual == bin_capacity, so its
    // large post_residual already scores high; reinforce with count).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 + 0.5 * progress);

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a fresh bin for this item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item can use the post_residual, reward
    // leaving exactly that much space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the
    // mean downward when the mean is high (consolidate space), and prefer
    // filling below-mean bins when mean is low.
    if mean_residual > 0.0 {
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly matches post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can still fit here: mild reward proportional to tightness
            score -= 60.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // dead space for the next item: penalize small unusable gaps
            let gap = post_residual as f64;
            if gap > 0.0 && gap < 10.0 {
                score += 40.0 * (10.0 - gap);
            }
        }
    } else {
        // last item: strongly prefer minimal leftover
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize new-bin candidate (empty bin) unless residuals of open bins are all poor
    if bin_residual == bin_capacity {
        score += 150.0;
        // if mean residual is large, opening a new bin is more acceptable
        score -= mean_residual * 0.5;
    }

    // Prefer tighter bins relative to mean residual
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Progress-based conservatism: early on, allow more bin spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: mild penalty so we don't always dump into the same bin.
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(6.0);
    }

    // Lookahead coupling: if the next item can use this bin's post-residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize proportionally to waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Global state: prefer filling bins when mean residual is high (many fragmented bins).
    let mean_res_gap = (mean_residual - post_residual as f64).abs();
    score += 0.05 * mean_res_gap;

    // Encourage using fragmented bins when many bins are open.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be conservative (favor new bins for big items);
    // late in the stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bias = (1.0 - progress) * 20.0;
    if bin_residual == bin_capacity {
        score += new_bin_bias - 5.0; // new-bin candidate: cheap early, expensive late
    }

    // Prefer bins whose residual is close to item (best-fit flavor) with non-linear sharpening.
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.08 * fit_gap * fit_gap / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let poly = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits, more strongly as the stream progresses.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 15.0 * (diff / bin_capacity as f64).powi(2);
        } else {
            score += 10.0 * (-diff / bin_capacity as f64).powi(2);
        }
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - prn);
    }

    // Penalize scattering across many open bins.
    score += 2.0 * open_bins_count as f64 * prn;

    // New-bin candidate: baseline cost plus smooth progress-dependent pressure.
    if bin_residual == bin_capacity {
        score += 60.0 - 40.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: small classes (<=10) are "dead" residues
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 40.0; // creates unusable sliver
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Fractional capacity coupling: reward filling beyond 80% of the bin
    let fill_frac = 1.0 - (post_residual as f64) / cap;
    if fill_frac >= 0.8 {
        score -= 25.0 * (fill_frac - 0.8) * 5.0;
    }

    // Integer-division thresholds on post_residual: bins whose residual falls into
    // [1..20] classes are less useful than [20..50] which can host small items.
    let class = post_residual / 20; // 0,1,2,3,4
    score -= match class {
        0 => 0.0,                       // 0..19 residual: nearly dead
        1 => 6.0,                       // 20..39
        2 => 10.0,                      // 40..59
        3 => 8.0,                       // 60..79
        _ => 0.0,                       // 80..100 (near-empty bin)
    };

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // harmonic pair: reward if combined fill is near capacity
            let combined = (item_size + next_item_size) as f64 / cap;
            if combined >= 0.95 {
                score -= 35.0;
            } else {
                score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
            }
        } else {
            // next item won't fit here: mild penalty proportional to mismatch
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // would be left with a bad residue and the new bin offers long-term flexibility.
    if bin_residual == bin_capacity {
        // empty bin baseline: slightly worse than a decent fit, better than a dead fit
        score = 45.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item benefits from a fresh bin
        }
    }

    // Stream progression: late in the stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / cap);

    // Mean residual context: if open bins are already fragmented, be pickier
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1..10)
    // are unusable dead space -> heavy penalty proportional to wasted capacity.
    if post_residual < 10 {
        score += 40.0 + 2.0 * (10 - post_residual) as f64;
    } else if post_residual < 20 {
        // Small gaps that only fit tiny items: moderate penalty scaled by gap size.
        score += 8.0 + 0.5 * (20 - post_residual) as f64;
    } else {
        // Usable residual: reward keeping gaps that can absorb future items.
        score -= 4.0;
    }

    // Reward tight fits (item fills most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless the fit is great.
    score += 1.5 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize if next item would leave another tiny dead gap.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: allow opening a fresh bin only when no open bin offers a good fit
    // (i.e., this call is the fresh bin and all fits are poor), otherwise penalize it.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Fresh bin is attractive if the item is large relative to capacity (better packing alone).
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (-tight * 14.0).exp();

    // Reward exact fills completely.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin,
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual as f64 > mean_residual {
            score += 10.0; // poor fit in the only fitting bin
        }
    }

    // Lookahead: penalize bins whose post_residual can't host the next item
    // but a slightly larger residual could; reward bins that chain nicely.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // chain placement possible
        } else if (bin_residual >= next_item_size) && post_residual > 0 {
            score += 6.0; // wastes residual that could host next item
        }
        // Reward leaving exactly a usable residual for the next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: make empty bins mildly unattractive so we
    // prefer filling open bins, but attractive when fits are bad or stream
    // is early/mid with many expected future items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if fitting_bins_count >= 1 { 1.0 } else { 0.0 };
        score += 20.0;                       // baseline cost of opening a bin
        score -= 15.0 * (1.0 - progress);    // early stream: openness is fine
        score += 18.0 * progress;            // late stream: prefer consolidating
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 10.0;                   // big items fit well in fresh bins
        }
        let _ = poor_fit;
    }

    // Global fragmentation pressure: if mean residual is small (bins nearly
    // full), penalize leaving dead space even more.
    score += (post_residual as f64) * (mean_residual / (bin_capacity as f64)) * 0.5;

    // Slight preference for bins with residuals close to the item (best-fit core).
    score += ((bin_residual - item_size) as f64).abs() * 0.05;

    // Mild diversity penalty when many bins are open: discourage spreading.
    score += (open_bins_count as f64).ln().max(0.0) * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    let coupling = pr_norm * (1.0 + progress * progress) + 3.0 * poly * (0.5 + progress);

    let mut score = 100.0 + 4.0 * coupling;

    // Penalize large dead space, more so later in the stream.
    let dead = if next_item_size > 0 {
        if next_item_size as f64 > pr { pr - (next_item_size as f64).min(pr) } else { 0.0 }
    } else { 0.0 };
    score += 0.6 * dead * (0.5 + progress);

    // Reward tight fits.
    score -= (item_size as f64 / cap) * 30.0;

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight penalty when bin residual diverges from mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: make it attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score = 100.0 + 4.0 * coupling + 10.0 * (1.0 - progress) - 12.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quarter classes of capacity.
    let quarter = bin_capacity as f64 / 4.0;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always reward
    } else if (post_residual as f64) < quarter * 0.25 {
        score -= 40.0; // tiny dead space is fine
    } else if (post_residual as f64) < quarter {
        score += 10.0; // awkward small residual
    } else if (post_residual as f64) < quarter * 2.0 {
        score -= 5.0; // half-class residual still useful
    } else if (post_residual as f64) < quarter * 3.0 {
        score -= 15.0; // large residual keeps bin flexible
    }

    // Modulo-10 harmonic class: residuals divisible by 10 pair well with
    // integer item sizes drawn from 1..=100.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if it cannot fit, penalize only mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item shares residue class with post residual
            if post_residual % 10 == next_item_size % 10 {
                score -= 12.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.2 * post_residual as f64;
    }

    // Penalize opening a new bin when many open bins have plenty of space
    // (compare against mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        let waste = (mean_residual - item_size as f64).max(0.0);
        score += 30.0 + openness * 4.0 + waste * 0.5 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // future is big, a fresh bin is more tolerable
        }
    }

    // Small tie-breaker favoring tighter fits overall.
    score += (bin_residual - item_size) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 6.0;
    }
    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual before placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }
    // Many fitting bins: mild penalty so best-fit quality dominates selection.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Open-bin pressure: when many bins are open, avoid spreading; when few, opening is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += pressure * 4.0;

    // New-bin candidate handling: only attractive if this bin's fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 20.0;
        // Attractive when the item would leave a dead gap in any existing bin
        // or when existing residuals are large and fragmented.
        if post_residual == 0 {
            score -= 30.0;
        }
        if mean_residual < item_size as f64 * 1.2 {
            score -= 25.0;
        }
        if open_bins_count > 12 {
            score += 15.0 * ((open_bins_count as f64 - 12.0) / 10.0).min(3.0);
        }
        // Lookahead: if next item is small, a fresh bin's large residual is useful.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
    } else {
        // Existing bin whose residual can still host the next item is valuable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // Existing bin whose post-residual kills the next item's fit is penalized.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Mild preference for bins below mean residual (consolidating space).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the residual after placement -> lookahead reward scaled by slack.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // Next item would NOT fit after placement: penalize small dead space that blocks lookahead.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0;
    }

    // Penalize unusable dead space below the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Tight fit reward: small post_residual relative to mean residual is good.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or the current bin fits poorly (large post_residual waste).
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        let poor_fit = if next_item_size > 0 && next_item_size > waste { 20.0 } else { 0.0 };
        score += 45.0 - waste * 0.4 + poor_fit
            - (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Mild preference for keeping fewer open bins when residuals are large.
    if open_bins_count > 1 && post_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills a large fraction
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to ever be useful (below min item size ~1..100 unknown,
    // use a conservative small-slice penalty)
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.10 {
            score += 25.0 * (1.0 - dead / 0.10); // unusable sliver penalty
        } else {
            score += 2.0 * dead; // mild general waste penalty
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item (chain packing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * next_fit;
        } else {
            score += 6.0; // breaks the chain
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be conservative (favor spreading), late, be greedy
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill_ratio;

    // Global state coupling: many open bins with high mean residual -> discourage opening new bins,
    // encourage consolidating into bins with residual above the mean
    if bin_residual != bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score -= 8.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
        } else {
            score += 4.0;
        }
        if open_bins_count > 4 {
            score -= 3.0 * ((open_bins_count as f64 - 4.0).min(10.0));
        }
    }

    // New-bin candidate: only attractive when item is huge relative to typical residual or no good fit exists
    if bin_residual == bin_capacity {
        let openness = (item_size as f64 / bin_capacity as f64).powi(3);
        score += 45.0 * (1.0 - openness); // default penalty, shrinks for large items
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits, must open
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 12.0; // future items may need fresh space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post residual, with polynomial coupling on progress.
    // Early in the stream, keep bins flexible (favor moderate residuals);
    // late in the stream, tighten aggressively (minimize post residual).
    let mut score = post * (1.0 + 0.5 * t) - 12.0 * t * post / cap;

    // Non-linear reward for tight fits: post_residual^2 term scaled by progress.
    score -= 20.0 * t * (1.0 - post / cap) * (1.0 - post / cap);

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = ((nxt - post) / cap).max(0.0);
        score += 15.0 * unusable * (1.0 + t);
        // Reward when next item exactly fills the residual (smooth coupling).
        let match_frac = 1.0 - (nxt - post).abs() / cap;
        score -= 10.0 * match_frac.max(0.0) * (0.5 + 0.5 * t);
    } else {
        // Last item: strongly minimize post residual.
        score -= 25.0 * (1.0 - post / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (smooth penalty on post residual).
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - post / cap) * (1.0 - post / cap);
    } else if fitting_bins_count > 1 {
        // Mild penalty for using a bin when alternatives exist, scaled by crowding.
        score += 2.0 * (open_bins_count as f64).ln() * (post / cap);
    }

    // New-bin candidate: empty bin. Prefer it only when residuals across open bins
    // are large relative to the item (i.e., open bins fit poorly).
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item).max(0.0) / cap;
        score = cap - 20.0 * mean_fit_gap + 5.0 * t * post / cap;
        // If only this new bin fits, it's effectively forced: keep score moderate.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight preference to fill bins with larger residual deviations from mean
    // (reduce variance of residuals, smooth polynomial coupling).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 4.0 * dev * dev * (0.5 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // usable buckets via integer division thresholds (dead-space classes).
    let pr = post_residual;
    // Class 0: perfect or near-perfect fit (residual <= 5) -> strong reward
    if pr <= 5 {
        score -= 60.0;
    } else if pr <= 15 {
        // Class 1: small leftover, still likely fillable by tiny items (1..15)
        score -= 25.0;
    } else if pr <= 30 {
        // Class 2: medium leftover, fillable by common small items
        score -= 8.0;
    } else if pr <= 50 {
        // Class 3: large leftover, half-bin waste risk
        score += 5.0;
    } else {
        // Class 4: huge leftover means item was small relative to bin;
        // wasteful unless bin was nearly empty anyway.
        score += 15.0;
    }

    // Modulo-arithmetic harmonic bonus: residuals that are nice divisors
    // of common item sizes (multiples of 10) are more likely to be filled.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item can chain into this bin: reward proportional to tightness
            let chain_tightness = (next_item_size as f64) / (pr as f64);
            score -= 10.0 + 15.0 * chain_tightness;
        } else {
            // Next item cannot use this bin's leftover: mild penalty
            score += 4.0;
            // Extra penalty if leftover is in the awkward 16..=next-1 band
            if pr >= 10 && pr < next_item_size {
                score += 3.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if pr <= 10 {
            score -= 10.0; // tight fit in the last chance bin is excellent
        }
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (discourage hoarding bins).
        score += 40.0 + 2.0 * open_bins_count as f64;
        // But if the item is large, starting fresh is reasonable.
        score -= (item_size as f64) * 0.35;
        // Late in the stream, avoid opening bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        // If next item is large and current residual classes are all poor,
        // a fresh bin preserves flexibility: small discount.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate: prefer bins whose residual is below mean
    // (tighter bins get priority, keeps mean residual low).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f).min(30.0) * 0.3;
    } else {
        score += (res_f - mean_residual).min(30.0) * 0.15;
    }

    // Prefer using more-filled bins early; slight stream-aware scaling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that cannot fit the lookahead item but are still non-trivial.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 25.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward post-residuals that fit the next item (keeps bin useful).
    if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But allow opening a new bin when existing residuals are fragmented.
        if mean_residual < item_size as f64 * 0.6 {
            score -= 45.0;
        }
    }

    // Mild fullness bonus: tighter packing as stream progresses.
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Perfect 2-step fit: post_residual == next_item_size -> strong reward
        if diff < 1.0 {
            score -= 60.0;
        } else if nxt <= post {
            // next item fits exactly-ish: reward closeness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item does NOT fit in post-residual: penalize wasted potential
            score += 15.0 * (nxt - post) / bin_capacity as f64;
        }
        // Bonus if post-residual can hold next item plus a small margin
        if post >= nxt + 10.0 {
            score -= 8.0;
        }
    }

    // Reward tight fits now (small post_residual), relative to mean residual
    let tightness = 1.0 - post_residual as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Penalize bins far from mean residual (avoid fragmenting the pool)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 45.0;
        // allow new bin early in stream when many bins already open poorly
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Exact fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // small unusable slivers are bad
    }

    // Lookahead: if next item fits in post_residual, reward synergy.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 5.0; // next item won't fit here; mild penalty
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global state coupling: when many bins are open with large mean residual,
    // discourage spreading waste; prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) > mean_residual {
        score += 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Time horizon: early on, be more willing to open new bins (less penalty);
    // late in stream, conserve bins by favoring existing placements.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and many bins open.
        score += 15.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
        // But if item is huge and few bins fit it, opening new bin is attractive.
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Open-bins pressure: with many open bins, favor filling existing ones.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits via non-linearly shaped residual cost
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling of residual with stream progress:
    // tight fits matter more as the stream matures.
    let coupling = norm_pr * (1.0 - progress) + norm_pr.powi(3) * progress;
    score += 1.5 * coupling;

    // Lookahead: reward bins whose post-residual can still hold the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.8 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.3 * (1.0 - progress);
    }

    // Perfect fit bonus (smooth, not piecewise)
    let fit_quality = 1.0 - (pr / item_size.max(1) as f64).abs();
    score -= 0.5 * fit_quality.max(0.0) * (1.0 - norm_pr);

    // Penalize new-bin opening unless residual is large or few bins fit
    let is_new_bin = (bin_residual == bin_capacity) && item_size > 0;
    if is_new_bin {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 2.0 - 1.5 * scarcity - 0.5 * progress;
    }

    // Last-chance bin: strongly favor it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 1.2;
    }

    // Mild preference for bins tighter than average (smooth)
    score += 0.2 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size buckets (integer division)
    let item_class = item_size / 10;
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / 10 };

    // Base: prefer tight fit, but weight residual by how "usable" it is.
    // Residuals in the lowest harmonic band (<10) are dead space -> heavy penalty.
    let dead_zone = post_residual < 10;
    if dead_zone {
        score += 25.0;
    }

    // Harmonic pairing: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much would remain
            let after2 = post_residual - next_item_size;
            score -= 12.0 - (after2 as f64) * 0.2;
        } else {
            // next item cannot use this bin's remainder; penalize small leftovers
            score += (post_residual as f64) * 0.15;
        }
    }

    // Modulo-10 harmonic alignment: item + next forming near-decade sums is good
    if next_item_size > 0 {
        let s = item_size + next_item_size;
        let rem = s % 10;
        if rem == 0 {
            score -= 6.0;
        } else if rem >= 8 {
            score -= 3.0;
        }
    }

    // Class compatibility: bin residual class vs item class
    let resid_class = bin_residual / 10;
    if resid_class == item_class + 1 {
        // perfect envelope: residual one class above item -> near-perfect fit
        score -= 8.0;
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive early, cheap late
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = cap - (cap - post_residual as f64); // = cap, baseline
        // allow new bin only if item is large relative to capacity or stream is late
        let large_item = (item_size as f64 / cap) > 0.6;
        if large_item {
            score -= 10.0;
        }
        if progress > 0.7 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Existing bin: reward using bins below mean residual (consolidating)
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
        // Penalize spreading across many open bins
        score += (open_bins_count as f64) * 0.3;
        // Encourage filling bins whose residual class matches item class exactly
        if resid_class == item_class {
            score -= 5.0;
        }
    }

    // Small tie-break noise via deterministic function of state (no rng)
    score - ((item_size as f64).sqrt() * 0.05) + (post_residual % 7) as f64 * 0.01
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it's below the smallest plausible item (<= 10)
    // or too small for the lookahead item.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 40.0; // tiny wasted sliver
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit: highly rewarded
    } else if post_residual >= dead_threshold {
        // Usable gap: mild reward scaled by how well next item could use it
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // gap is reusable by lookahead item
        }
    }

    // Penalize leaving a gap that neither fits next item nor is large
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // gap unusable by lookahead: dead-space risk
    }

    // Reward tight fits: fraction of bin filled by this item
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless it's early or no open bin fits well
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 60.0; // forced new bin
        }
        // New bin residual = capacity - item; if item is large, new bin is efficient
        if item_size >= 70 {
            score -= 20.0;
        }
    } else {
        // Fitting an open bin reduces open-bin pressure
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residuals close to the item (best-fit flavor)
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * waste;

    // Slight preference for bins below mean residual (consolidate emptier space)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // bin becomes exactly filled by next item
        } else if post_residual > next_item_size {
            // next item still fits after this one: mild reward proportional to closeness
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving a gap next item can't use
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / 100.0).min(1.0);
        }
    }

    // Relative tightness vs mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0 && post_residual == next_item_size;
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && mean_residual < item_size as f64 * 0.5) {
            score -= 55.0; // prefer fresh bin when fits are poor
        } else if !good_fit_exists {
            score += 30.0; // discourage opening bins when decent fits exist
        } else {
            score += 15.0;
        }
    }

    // Late in the stream, consolidate into fewest bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (best-fit core with superlinear shaping)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: reward leaving exactly next_item_size of space (perfect chain),
    // penalize leaving a sliver that no future item can use
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 - gap / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // dead space below smallest plausible item (1..=3) is wasted
        if post_residual > 0 && post_residual < 4 {
            score += 15.0;
        }
    } else if post_residual > 0 {
        // last item: any residual is pure waste; prefer fullest bin
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let avg_frag = mean_residual / (bin_capacity as f64);
        // opening a bin is good when existing bins are fragmented and scarce
        score += 20.0 * (1.0 - scarcity) + 10.0 * avg_frag;
        if fitting_bins_count > 1 {
            score += 25.0; // plenty of alternatives; deprioritize opening
        }
        // early in stream, keeping bins consolidated matters less; late, avoid sprawl
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Prefer bins with residual below mean (compact nearly-full bins first)
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 3.0 * dev;
    }

    // Mild consolidation pressure with many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Tight-fit reward: strongly favor small post_residual, amplified by progress.
    let norm_post = post_residual as f64 / cap;
    score -= (1.0 - norm_post) * (1.0 + progress * 2.0) * item_size as f64;

    // Penalize dead space non-linearly (quartic coupling with progress).
    score += norm_post * norm_post * norm_post * norm_post * cap * (0.5 + progress);

    // New-bin candidate: penalize opening new bins, less so late in stream.
    if bin_residual == bin_capacity {
        score += cap * (1.5 - progress) + open_bins_count as f64 * 2.0;
        // Allow new bin if item is huge relative to capacity and no tight fit exists.
        let huge = (item_size as f64 / cap) > 0.8;
        if huge && fitting_bins_count == 1 {
            score -= cap * 1.2;
        }
        return score;
    }

    // Last-chance bonus: if this is the only fitting bin, use it.
    if fitting_bins_count == 1 {
        score -= cap * 1.5;
    }

    // Lookahead: reward leaving residual close to next item size (perfect chain).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= (1.0 - gap / cap) * 8.0;
        // Penalize leaving residual slightly too small for next item (wasted).
        if (post_residual as f64) < (next_item_size as f64) {
            score += 4.0 * progress;
        }
    }

    // Prefer bins whose residual is already below average (consolidation).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3 * (1.0 - progress);

    // Smooth fullness coupling: extra reward for near-full bins.
    let fullness = 1.0 - bin_residual as f64 / cap;
    score -= fullness * fullness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: which quarter of the capacity it falls in.
    let q = (post_residual * 4) / bin_capacity; // 0..3 integer class
    let class_penalty: f64 = match q {
        0 => 45.0, // dead space < 25% capacity: very bad
        1 => 12.0, // 25-50%: mediocre
        2 => -6.0, // 50-75%: decent
        _ => -14.0, // >75%: excellent leftover
    };
    score += class_penalty;

    // Exact / near-exact fits: reward heavily.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 55.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Harmonic residue of post_residual mod small moduli: granularity of the space.
    let m3 = (post_residual % 10) as f64;
    score -= (10.0 - m3) * 0.8; // residuals close to a multiple of 10 are more reusable

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let look = (post_residual - next_item_size) as f64;
            if look == 0.0 {
                score -= 70.0;
            } else if look <= 10.0 {
                score -= 35.0;
            } else {
                score -= 20.0 * (1.0 - look / cap);
            }
            // next item also classifies harmonically
            let nq = ((post_residual - next_item_size) * 4) / bin_capacity;
            if nq >= 2 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally to wasted lookahead
            score += (next_item_size as f64) * 0.25;
        }
    } else {
        // last item: only care about closing bins tightly
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // cheaper to open a new bin late in the stream? No: early stream amortizes, so
        // opening early is fine, opening late wastes capacity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // if many bins are open with large mean residual, prefer reusing them
        score += (mean_residual / cap).max(0.0) * 30.0;
        // if no open bin fits at all, opening is natural
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // if next item is huge, a fresh bin is valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // prefer filling existing bins more when they are already partly used
        let used = (bin_capacity - bin_residual) as f64 / cap;
        score -= 12.0 * used;
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that nothing (min size 1..100 unknown,
    // but typical items >= 10) can use are wasted. Penalize small gaps hard.
    if post_residual > 0 {
        // A residual is "usable" if it could hold a reasonable chunk of future load.
        // Treat gaps < 15 as near-dead, ramping penalty quadratically.
        if post_residual < 15 {
            score += (15.0 - post_residual as f64) * (15.0 - post_residual as f64) * 0.8;
        } else if post_residual == 0 {
            score -= 30.0; // perfect fit bonus
        }
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    }

    // Tight-fit gradient: reward filling most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new one (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit, or when the item would leave a large dead gap anyway.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by lookahead usefulness.
        score = bin_capacity as f64 * 0.9;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // the new bin can also host the next item
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If only the new bin fits, it must be chosen: make it competitive.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    }
    // Penalize leaving a gap the next item barely misses (dead space coupling).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.3;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (it's a "leftover" bin), prefer consolidating into it.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // exact match -> strong bonus
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item still fits: mild bonus scaled by closeness
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize wasted gap
            score += 8.0 + diff * 0.15;
        }
    } else {
        // last item: prefer tightest fill
        score -= 25.0;
    }

    // relative to mean residual: prefer bins that end below average residual (tighter)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // new-bin candidate: only attractive when no open bin fits or residual would be dead space
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            // opening a new bin is costly; discourage unless current placement is very wasteful
            score += 15.0 + post_residual as f64 * 0.3;
        }
    }

    // early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core tight-fit reward: strongly favor bins whose residual closely matches the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space nonlinearly (superlinear waste penalty).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste * waste;

    // Lookahead coupling: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * chain_fit;
    }
    // Penalize leaving a residual just barely too small for the next item (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // New-bin candidate handling: only attractive when the item is large relative
    // to capacity or all open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good when the item is big or open bins are congested.
        score -= 8.0 * big_item + 6.0 * pressure;
        // But late in the stream, closing out existing bins is preferable.
        score += 12.0 * progress;
        // If many bins fit, discourage spreading out.
        score += 2.0 * fitting_bins_count as f64;
    }

    // Mild bonus for using bins with below-average residual (consolidate emptier bins).
    if bin_residual != bin_capacity {
        let rel = bin_residual as f64 - mean_residual;
        score -= 0.05 * rel;
    }

    // Consolidation pressure: with many open bins, favor filling existing ones.
    score -= 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Tiny tie-break toward exact fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear growth in wasted space
    let mut score = pr + 25.0 * norm_pr * norm_pr;

    // Stream-progress coupling: later in the stream, penalize residuals more sharply
    let progress_weight = 0.5 + 2.0 * t * t;
    score += progress_weight * 30.0 * norm_pr * norm_pr;

    // Reward using existing bins vs opening new ones (new bin has pr == cap)
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    score += is_new_bin * (40.0 + 60.0 * t);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 30.0 * (1.0 - diff / cap).max(0.0);
    }

    // Mean-residual coupling: penalize bins deviating from fleet average
    score += 5.0 * (pr - mean_residual).abs() / cap;

    // Mild pressure against proliferating open bins early
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "reusable" classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit: best possible outcome
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr >= 10 && pr <= 25 {
        0.0
    } else {
        8.0 // awkward dead space in mid range
    };
    score += harmonic_bonus;

    // Integer-division threshold: tiny leftovers (< 10, unusable for min item)
    // are pure waste; penalize proportionally.
    if pr > 0 && pr < 10 {
        score += 15.0 + (10 - pr) as f64 * 1.5;
    }

    // Lookahead coupling: if the next item exactly fits the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr && pr - next_item_size < 10 {
            score -= 10.0;
        } else if next_item_size > pr {
            // next item won't fit here anyway; leftover value matters less
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 + 25.0 * progress;
    }

    // New-bin candidate handling: an empty bin has large post_residual by
    // construction, but if all existing residuals are fragmented (high mean
    // residual spread), opening fresh is competitive. Penalize new bins when
    // the item packs well into an existing one.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 30.0 * (1.0 - progress);
        if item_size >= 50 {
            score -= 15.0; // big items justify fresh bins early
        }
        // If mean residual across open bins can't host the item comfortably,
        // new bin looks better.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Mild preference to consolidate into bins with below-average residual
    // (keeps some bins "fat" for future large items).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Slight bonus for using bins when many are open (limit bin proliferation).
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= (open_bins_count as f64).min(10.0) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // tiny gap = dead space; penalty grows as gap shrinks
        score += (10 - pr) as f64 * 8.0;
    } else if pr >= 10 && pr < 25 {
        // medium gap: mildly wasteful unless next item fits it
        let waste = if next_item_size > 0 && next_item_size <= pr { 0.0 } else { (pr as f64) * 0.5 };
        score += waste;
    } else if pr == 0 {
        // perfect fit: strong reward
        score -= 40.0;
    } else if pr >= 25 {
        // large residual stays usable; mild reward for leaving room
        score -= (pr.min(60) as f64) * 0.2;
    }

    // Reward tight fits (item nearly fills bin)
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 6.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 25.0;
    }
    // If next item fits comfortably in post_residual, mild reward
    if next_item_size > 0 && next_item_size <= pr && pr >= 10 {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: discourage spreading across many bins when
    // residuals are already small (avoid fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    // New-bin candidate: only attractive if all open bins would leave dead space.
    if bin_residual == bin_capacity {
        // base cost of opening a bin; reduced when open bins are badly fragmented
        let mut new_bin_cost = 12.0;
        if fitting_bins_count == 0 {
            new_bin_cost = -5.0; // no alternative anyway
        } else if open_bins_count > 0 {
            let fragmentation = 1.0 - (mean_residual / bin_capacity as f64);
            new_bin_cost -= fragmentation * 6.0;
        }
        score += new_bin_cost;
        // small bonus for new bin if item is large (needs room)
        if item_size > 60 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let slack = post - next;
            if slack == 0.0 {
                score -= 45.0; // perfect two-item packing
            } else if slack <= 5.0 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - slack / 100.0);
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted lookahead.
            score += 8.0 * (next - post) / 10.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residuals below mean (tighter bins first).
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (post_f - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating dead space that no item (10..80 range) could use.
    if post_f > 0.0 && post_f < 10.0 {
        score += 15.0 * (10.0 - post_f);
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: make empty bins mildly attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; lookahead can discount it.
        let mut new_bin_score = 55.0;
        if next_item_size > 0 {
            let rem = bin_capacity as f64 - next_item_size as f64;
            if rem >= item_size as f64 {
                new_bin_score -= 15.0;
            }
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // must open a new bin
        }
        score = new_bin_score.min(score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space nonlinearly (wasted capacity beyond half a bin).
    if post_residual > bin_capacity / 2 {
        score += 0.8 * (post_residual - bin_capacity / 2) as f64;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count == 2 {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // Extra reward if post-residual matches the next item closely.
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a residual that is too small to be useful later.
            score += 6.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual of open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bins when open bins are crowded (low mean residual) or few bins fit.
        score = 55.0 + 0.5 * mean_residual - 20.0 * progress;
        if fitting_bins_count == 1 {
            score += 40.0; // don't abandon the last fitting bin
        }
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0; // fresh bin guarantees room for lookahead
        }
    }

    // Global pressure: many open bins with large mean residual -> prefer consolidating
    // into existing bins (penalize new-bin-like choices implicitly via mean residual).
    score += 0.15 * mean_residual * (open_bins_count as f64).ln().max(1.0);

    // Mild time-dependent tightness: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, waste tolerance is higher; late in the stream, residual space
    // becomes precious, so weight post_residual quadratically/cubically.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let poly = 1.0 + 2.0 * progress + 3.0 * progress * progress;
    score += poly * (pr_norm * pr_norm * cap) - 0.5 * pr_norm * cap;

    // Reward tight fits: item fills a large fraction of the bin.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;

    // Lookahead: bonus if the post-residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - pr / cap) * (nx / cap);
        } else {
            // residual too small for next item: penalize dead space
            score += 6.0 * (1.0 - pr / cap) * (nx / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: neutral baseline, slightly worse late in stream
    // (encourage closing out residual space when the stream nears its end),
    // but attractive early when many bins are already open.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64) / (1.0 + open_bins_count as f64);
        score = cap * (0.9 + 0.3 * progress) - 10.0 * openness * (1.0 - progress);
    }

    // Mild preference for bins whose residual is close to the mean
    // (keeps the pool of usable residuals balanced).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which residue class mod 10 it falls in.
    // Residuals near multiples of 10 are more reusable by typical item sizes.
    let post_class = post_residual % 10;
    let class_penalty: f64 = match post_class {
        0 => -6.0,           // perfectly reusable class
        1 | 2 | 3 => 4.0,    // awkward slivers
        4 | 5 | 6 => 1.0,
        7 | 8 | 9 => 3.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: post_residual bucketed into capacity tenths.
    let tenth = post_residual / 10;
    score -= (tenth as f64) * 0.7;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead coupling: reward if next item can exactly use the post residual,
    // penalize if post residual is a "trap" (smaller than next item but < 10).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual && post_residual - next_item_size <= 5 {
            score -= 10.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 8.0; // dead space trap
        }
        // Harmonic pairing: post_residual and next_item_size share a common divisor class
        let g = gcd(post_residual.max(1), next_item_size.max(1));
        if g > 1 {
            score -= (g as f64).min(10.0) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize opening bins when
    // existing bins have tight fits, reward when all open bins are crowded.
    if bin_residual == bin_capacity {
        score += 6.0;
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 14.0; // open bins nearly full -> new bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Prefer denser bins: deviation from mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Slight phase modulation: as stream progresses, be more conservative
    // about leaving mid-range residuals.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += (phase * std::f64::consts::PI * 2.0).sin() * 1.5;

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else if post_residual > 0 && post_residual < item_size {
        // gap smaller than current item: partially dead unless next item fits
        if next_item_size == 0 || next_item_size > post_residual {
            score += 25.0;
        }
    }

    // Reward tight fits (best-fit flavor with amplification).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 15.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: strongly favor bins whose residual can also host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer reusing existing bins over new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and remaining stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 6.0 * open_bins_count as f64 + 20.0 * (1.0 - progress);
        // Allow opening a new bin only if current item would leave a big dead gap elsewhere.
        if item_size >= 60 {
            score -= 25.0;
        }
    } else {
        // Mild bonus for using bins with low mean residual (consolidating emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals the next item's size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits comfortably after placement (residual >= next + margin).
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual as f64 - next_item_size as f64) * 0.3;
    }
    // Next item will NOT fit: leftover is dead space unless tiny.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Penalize small unusable scraps (< 10 cannot hold any item).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Compare against mean residual: bins already tighter than average are
    // good targets; bins looser than average should be deprioritized.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_open_exists = fitting_bins_count > 0 && mean_residual < (bin_capacity as f64) * 0.5;
        if good_open_exists {
            score += 25.0; // keep using open bins
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing can reuse (items >= 1).
    if post_residual < 10 {
        score -= 25.0; // tiny residual is actually perfect fill
    } else if post_residual <= 20 {
        score += 8.0; // awkward mid-range dead space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if next_item_size > post_residual as u32 && post_residual > 0 {
            score += 6.0; // next item won't fit here; deprioritize slightly
        }
    }

    // Time horizon: early in stream, prefer consolidating into open bins;
    // late in stream, allow new bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later.
        score += 35.0 * (1.0 - progress) - 5.0 * progress;
        if open_bins_count < 2 {
            score -= 20.0; // need bins to start
        }
    } else {
        // Favor bins with residual near mean (keep pool balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 5 {
        score -= 3.0 * (open_bins_count.min(20) as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with smooth non-linear penalty on wasted space
    let mut score = post;

    // Non-linear waste penalty: dead space that is too small to hold typical items is worse
    let dead = (post / cap).powi(2);
    score += 15.0 * dead * (1.0 + progress);

    // Reward tight fits: quadratic bonus shrinking with post_residual
    score -= 10.0 * (1.0 - post / cap).powi(3);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits the post-residual well, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 4.0 * (gap / cap).powi(2);
        }
    }

    // Stream-progress interaction: later in stream, tolerate slightly larger residuals
    // to avoid opening new bins (penalize new-bin candidate smoothly over time)
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score += 5.0 + 25.0 * (1.0 - progress).powi(2);
    }

    // Coupling with mean residual: avoid bins far from the fleet average when many bins open
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev.powi(2) * (open_bins_count.min(50) as f64 / 50.0);

    // Mild preference for fuller bins as stream progresses
    score -= 2.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by modulo arithmetic
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class A: near-perfect fit (post_residual tiny) -> strong reward
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Class B: residual is an "exact divisor class" — divisible by common item sizes
    if post_residual > 0 {
        let harmonics = [10u32, 20, 25, 50];
        let mut harm_bonus = 0.0;
        for h in harmonics {
            if post_residual % h == 0 {
                harm_bonus += 6.0;
            }
        }
        score -= harm_bonus;
    }

    // Class C: integer-division thresholds — residual usable by the NEXT item
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item also fits: reward proportionally to how snugly
        let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 + 15.0 * snug;
    } else if next_item_size > post_residual {
        // residual too small for lookahead: penalize dead space harder
        score += 8.0 * frac;
    }

    // Class D: last-chance bin (only fitting bin) — avoid opening new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Class E: new-bin candidate — only attractive when current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0; // default penalty; tight fits in existing bins beat it
        if post_residual <= 5 || fitting_bins_count == 0 {
            score -= 30.0; // but fine when nothing fits well anyway
        }
    }

    // Class F: modulo-10 harmonic alignment between item and residual
    if item_size % 10 == 0 && bin_residual % 10 == 0 {
        score -= 4.0;
    }

    // Progress coupling: prefer consolidating into open bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 5.0 * progress;
    }

    // Mean residual pressure: when open bins are generally roomy, filling them is good
    if !is_new_bin && mean_residual > frac * cap {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit gets a strong discount.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: dead space risk grows.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + progress);

    // Mean residual coupling: penalize bins far from the mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: keep it moderately attractive only when open bins are crowded
    // or the fit would be poor; otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        let poor_fit = item_size as f64 <= bin_capacity as f64 * 0.5;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        } else if poor_fit && open_bins_count > 3 {
            score -= 15.0;
        } else {
            score += 35.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item can fit in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
    }
    // Next item cannot use leftover space: penalize proportional dead space.
    if next_item_size > 0 && next_item_size > post_residual {
        let waste = post_residual as f64;
        score += waste * 0.5;
    }

    // Reward tight fits relative to the mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Early in the stream, be slightly greedy about consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.1 * (1.0 - progress);

    // New-bin candidate: keep it expensive unless leftovers are minimal.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (best-fit core).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward placements that leave room for the lookahead item (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact two-item completion
        } else if post_residual >= next_item_size {
            score -= 15.0; // lookahead still fits afterwards
        } else {
            // leftover too small for next item: penalize dead space more
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins normally; relax late in the stream or when
        // open-bin residuals are large (fragmented state).
        let mut new_bin_penalty = 55.0 - 25.0 * progress - 30.0 * (1.0 - avg_pressure);
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_penalty += 10.0; // big item follows; prefer fresh space
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild global coupling: prefer filling bins when many are open (contain sprawl).
    score += open_bins_count as f64 * 0.15;

    // Prefer bins below mean residual (keep a spread of large residuals? no:
    // favor bins with residual near/below mean to consolidate fragmentation).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, no piecewise constants)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-fit slack
    let slack = post_residual as f64 / cap;
    let slack_sq = slack * slack;

    // Non-linear polynomial coupling: slack^2 penalizes large leftover space,
    // while a mild linear term keeps tiny dead space mildly costly too.
    score += 12.0 * slack_sq * (0.5 + progress);

    // Reward tight fits: the closer the item fills the bin, the better.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill * fill;

    // Penalize residuals that cannot accommodate the lookahead item (dead space)
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else {
            // Reward leaving room exactly usable by the next item
            let snug = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap).abs();
            score -= 4.0 * snug.max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count <= 1 {
        score -= 15.0;
    }

    // Discard bins whose residual deviates badly from the fleet mean (imbalance)
    score += 0.5 * ((post_residual as f64 - mean_residual) / cap).abs();

    // Late in the stream, consolidate: slightly favor existing bins over new ones
    score += 5.0 * progress * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes mod 10 (capacity 100 -> 10 classes)
    let class = post_residual % 10;
    // Residuals that are "harmonic" (divisible-friendly, e.g. 0, 20, 25, 50) are more reusable
    let harmonic_bonus: f64 = match post_residual {
        0 => -40.0,                     // perfect fit: heavily reward
        10 | 20 | 25 | 30 | 40 | 50 => -12.0,
        _ => 0.0,
    };
    score += harmonic_bonus;

    // Penalize awkward dead space: residual in (0,10) is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // reward proportional to how tight the future fit is
            score -= 20.0 / (1.0 + slack as f64);
            // penalize if next item leaves another dead zone
            if slack > 0 && slack < 10 {
                score += 8.0;
            }
        } else {
            // next item won't fit here; leftover class matters
            score += (class as f64) * 0.5;
        }
    } else {
        // last item: only perfect closure matters
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Integer-division threshold: bins whose residual is < half of smallest plausible item
    // are low-utility; penalize proportionally
    let half_threshold = bin_capacity / 20; // = 5 for C=100
    if post_residual < half_threshold && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no good fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin
        score += 30.0;
        // discount the new bin when open bins are congested (high mean residual spread)
        if mean_residual > 0.0 && (post_residual as f64) > mean_residual * 2.0 {
            score -= 25.0;
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // if many bins already fit the item, opening new is wasteful
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    } else {
        // mild preference for filling fuller bins (small residual) first
        score += (bin_capacity - bin_residual) as f64 * 0.05;
        // many open bins -> encourage consolidation
        score -= (open_bins_count.min(20) as f64) * 0.3;
    }

    // Modulo arithmetic coupling: reward when item_size and post_residual share a common class
    let item_class = item_size % 10;
    if class != 0 && item_class != 0 && class % item_class.max(1) == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 5.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score += 8.0; // next item would leave another dead gap
            } else {
                score -= 10.0;
            }
        }
    }

    // Pressure on number of open bins: mild incentive to fill existing bins
    // rather than proliferate, scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.3 + 0.4 * progress);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Slight pull toward bins with residuals above the mean (keeps balance).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item exactly fills the residual (perfect 2-chain).
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: reward closeness to an exact fill.
            score -= 60.0 * (1.0 - diff / (bin_capacity as f64)) - 0.5 * diff;
        } else {
            // Next item would not fit here: mild penalty proportional to overshoot.
            score += 0.3 * diff;
        }
    }

    // Penalize tiny unusable residuals (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins whose residual is already below average (tight bins get tighter).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Late in the stream, prefer closing out bins (reduce fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: keep it neutral-ish but slightly penalized so only
    // genuinely poor fits among open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if no open bin fits well (large post_residual among open bins),
        // opening fresh is fine — handled by comparison against their scores.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item can fit into the post-residual, reward; otherwise penalize
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 20.0;
        } else if next_item_size <= bin_residual && post_residual > 0 {
            // we block the next item: penalize proportionally to how much we block
            score += 10.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
        }
        // next item exactly fills post-residual: excellent chaining
        if post_residual as u32 == next_item_size {
            score -= 35.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let avg_crowding = mean_residual / cap; // low mean residual => crowded bins
        let pressure = 1.0 - avg_crowding;
        // base penalty so new bins aren't opened frivolously
        score += 55.0;
        // relax penalty when open bins are nearly full or few fit
        score -= 70.0 * pressure * pressure;
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // early stream: keep bins consolidated
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * (1.0 - progress);
        // large item into fresh bin is fine (avoids fragmentation)
        score -= 0.3 * item_size as f64;
    }

    // Mild preference for fuller bins among open bins
    score += 0.15 * (bin_residual as f64 - mean_residual).abs().signum()
        * (bin_residual as f64 - mean_residual);

    // Deter bin proliferation when many bins are open with slack
    if !is_new_bin && open_bins_count > 4 && mean_residual > 0.4 * cap {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 0.8 * t - 1.6 * t * t + 0.8 * t * t * t;
    let mut score = pr * poly;

    // Smooth interaction: residual waste penalized more as stream progresses
    score += 12.0 * norm_pr * norm_pr * (1.0 + t) * cap * 0.1;

    // Reward tight fits smoothly via quadratic of normalized fill
    let fill = (bin_residual as f64 - pr) / cap;
    score -= 20.0 * fill * fill;

    // Last-chance bin bonus (smooth sigmoid-like on fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + t);
    }

    // Lookahead coupling: penalize blocking the next item smoothly
    let n = next_item_size as f64;
    if n > 0.0 {
        let gap = pr - n;
        if gap >= 0.0 {
            score -= 6.0 * (gap / cap) * (1.0 - t);
        } else {
            score += 4.0 * (-gap / cap) * (1.0 + t);
        }
    }

    // Mild pressure to reuse open bins when many are open
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * t);

    // Mean residual deviation term (smooth quadratic)
    score += 2.0 * (mean_residual - pr).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (<= 10) are near-perfectly packed -> reward.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Integer-division thresholds: class the residual into deciles of capacity.
    let decile = post_residual / 10; // 0..10
    let decile_bonus = match decile {
        0 => 40.0,               // waste <= 9: excellent
        1 => 25.0,
        2 => 15.0,
        3 => 8.0,
        4 => 3.0,
        5 => 0.0,
        6 => -2.0,
        7 => -4.0,
        8 => -6.0,
        9 => -8.0,
        _ => -10.0,              // nearly empty bin used for a small item
    };
    score -= decile_bonus;

    // Modulo arithmetic: residuals that are multiples of small sizes (5, 10, 20)
    // are more likely to be exactly filled by future items -> reward them.
    if post_residual % 5 == 0 { score -= 4.0; }
    if post_residual % 10 == 0 { score -= 4.0; }
    if post_residual % 20 == 0 { score -= 3.0; }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect pair -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let nxt_post = post_residual - next_item_size;
            // harmonic class of the double-fill leftover
            if nxt_post <= 10 { score -= 25.0; }
            else if nxt_post <= 25 { score -= 12.0; }
            else { score -= (nxt_post as f64) * 0.05; }
        } else {
            // next item cannot use this bin's leftover; penalize large leftovers
            score += (post_residual as f64 - cap * 0.5).max(0.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // unattractive unless no open bin fits decently (post_residual small).
    if bin_residual == bin_capacity {
        // Opening a new bin is worthwhile only if the best existing leftover
        // would be very poor. Approximate via mean residual of open bins.
        let mean_usable = if open_bins_count > 0 { mean_residual } else { cap };
        // If mean residual across open bins is small, open bins are nearly full:
        // a fresh bin is fine. Otherwise penalize the new bin.
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap - post + openness * cap * 0.9 + 5.0;
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Small global pressure: more open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.5;

    // Mild tie-break: prefer bins whose residual is close to the item (tight fit)
    score -= (bin_residual as f64 - item_size as f64).abs().max(1.0).recip() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the minimum item
    // (1..=3) are essentially unusable; penalize them nonlinearly.
    if post_residual > 0 && post_residual < 4 {
        score += 60.0 * (4.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 40.0;
    }

    // Reward when the remaining gap can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // gap wasted relative to lookahead
        }
        // Extra reward if post-residual exactly matches next item (chain fit).
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Open-bins pressure: penalize spreading across many bins slightly,
    // but reward using an existing bin when many bins are open.
    score += 0.35 * open_bins_count as f64;
    if fitting_bins_count > 1 {
        score -= 5.0; // flexibility exists, mild preference for good fits
    }
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // Last-chance bin: strongly favor using it before opening a new bin.
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists,
    // i.e., when this is the empty-bin call, keep it moderately costly.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But allow opening when the item is large and current fits are poor.
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 25.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // (below-mean residual bins are tighter, fill them first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight late-stream urgency to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fill the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the leftover space: strong reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize leftover space that is too small for anything useful (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving this bin below average wastes its capacity; above average is fine.
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Mild early-stream bonus for keeping bins tight (more bins open early).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to typical residuals and few bins fit it.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if big_item && fitting_bins_count <= 1 {
            score -= 10.0; // allow a fresh bin for oversized items
        } else {
            score += 30.0; // prefer existing bins otherwise
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pressure on tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize dead space below the minimum item size (unusable residue)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 14.0;
            // extra reward for near-perfect two-item packing
            let combined = item_size as f64 + next_item_size as f64;
            if (bin_capacity as f64 - combined).abs() <= 4.0 {
                score -= 20.0;
            }
        } else if post_residual > 0 && (post_residual as f64) < next_item_size as f64 * 0.5 {
            // creates a small hole the next item can't use
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: default competitive baseline; open a new bin only when
    // existing bins are crowded or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let avg_crowding = mean_residual / bin_capacity as f64;
        // penalize opening new bins early / when open bins are roomy
        score += 6.0 + 2.5 * crowd.sqrt() + 40.0 * avg_crowding;
        // but if the item barely fits anywhere and mean residual is small, new bin is attractive
        if fit_ratio > 0.85 {
            score -= 25.0;
        }
        // late in stream, prefer consolidating into existing bins
        score += 15.0 * progress;
    }

    // Mild preference for fuller bins relative to global mean residual
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight penalty proportional to remaining open capacity to spread load late
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: raw wasted space
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - 0.5 * norm_pr * progress;
    score += 60.0 * poly;

    // Perfect fit reward (smooth decay)
    let fit_frac = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_frac * fit_frac * fit_frac * fit_frac;

    // Lookahead: reward leaving room for next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx).max(0.0) / cap;
        let mismatch = (pr - nx) / cap;
        score += 15.0 * mismatch * mismatch * (1.0 - progress);
        score -= 10.0 * slack * (1.0 - slack);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize slightly more as stream progresses
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress;
    }

    // Mild pressure toward filling fuller bins among many open bins
    score += 0.5 * (open_bins_count as f64).ln() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: integer division into capacity-fraction bands.
    // Residuals in the "dead zone" (1..=9) are nearly unusable -> strong penalty.
    let dead_class = post_residual / 10; // 0 => dead space <= 9
    if post_residual > 0 {
        score += (dead_class as f64).recip() * 12.0; // smaller class = worse = higher score
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure reward
    }

    // Harmonic coupling: does the next item fit into the post residual?
    // (k=2 lookahead, harmonic classes via modulo arithmetic on capacity fractions)
    if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits: this bin remains useful -> reward.
        let fit_fraction = (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 + 10.0 * fit_fraction;
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Next item will NOT fit here; penalize more if post residual is in a
        // near-miss modulo band (residual % 20 < 10 => awkward sliver).
        if post_residual % 20 < 10 && post_residual > 0 {
            score += 4.0;
        }
    }

    // Last-chance bin: only fitting bin available -> strong reward to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: baseline score so it is chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Fresh bin: post_residual == capacity - item_size.
        let frac = item_size as f64 / cap;
        // Base cost of opening a bin, discounted early in the stream or when many items remain.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_score = 55.0 - 20.0 * progress;
        // Large items pair well in a fresh bin (less fragmentation risk).
        new_score -= 15.0 * frac;
        // If next item is large, a fresh bin with big item is attractive.
        if next_item_size >= 50 {
            new_score -= 6.0;
        }
        // If very few bins can fit the item, opening fresh is less costly.
        if fitting_bins_count == 0 {
            new_score -= 30.0;
        }
        score = new_score;
    } else {
        // Mild preference for tighter existing bins (best-fit bias already via post_residual).
        let tightness = 1.0 - (bin_residual as f64 / cap);
        score -= 5.0 * tightness;
    }

    // Slight global pressure: prefer using open bins when many are open (avoid bin sprawl).
    score += 0.15 * open_bins_count as f64 * (1.0 - (post_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap that can never fit even the smallest item (<=10) is pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small-but-usable gaps are still risky; moderate penalty.
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward this placement; if the post_residual is useless for the next item,
    // penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Open bins pressure: discourage scattering across many bins,
    // but a last-chance bin (only fitting bin) is strongly favored.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    score += 1.5 * open_bins_count as f64;

    // Mean residual coupling: placing into a bin far below the mean residual
    // (i.e., a relatively full bin) is good; prefer tight fits.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate logic: opening a new bin should only win when this
    // placement would leave a poor gap. Penalize the empty-bin candidate
    // unless the current fit creates dead space.
    if bin_residual == bin_capacity {
        if post_residual < 25 && post_residual > 0 {
            // Bad fit anyway; opening a fresh bin is acceptable.
            score -= 55.0;
        } else {
            // Prefer using an existing bin when the fit is decent.
            score += 45.0;
        }
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item size.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (1.0 - lookahead_gap / bin_capacity as f64).max(-1.0);
        // Perfect match bonus: next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // Chainable residual: still useful but penalize large leftover.
            score += 0.05 * (post_residual - next_item_size) as f64;
        }
    }

    // Compare post_residual against mean residual of open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Penalize tiny dead space (unusable fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer tight fits generally.
    score += 0.3 * (bin_residual - item_size) as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = fitting_bins_count as f64;
        // Penalize opening new bins when decent fitting bins exist.
        score += 15.0 + 3.0 * pressure.max(0.0) - 10.0 * progress;
        // If the item would leave a huge hole in any existing bin, new bin less penalized.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize very small dead space that is likely unusable (< ~half of typical item)
    if post_residual < 10 {
        score -= 15.0; // perfect fill is excellent
    } else if post_residual <= 20 {
        score -= 5.0;
    } else {
        // penalize residual sizes that few items can use
        score += 0.15 * (post_residual as f64);
    }

    // Lookahead: if the next item fits into this bin's post_residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would NOT fit here but would fit elsewhere, mild penalty
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, be conservative; late in stream, fill aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    // Global state: many open bins -> prefer filling existing ones
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // If this bin is far below mean residual, deprioritize (save it for larger items)
    let dev = (bin_residual as f64) - mean_residual;
    if dev > 0.0 {
        score += 0.05 * dev;
    } else {
        score -= 0.03 * (-dev);
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = fitting_bins_count == 0 || (post_residual as f64) > 0.6 * (bin_capacity as f64);
        if poor_fit {
            score -= 10.0;
        } else {
            score += 30.0; // discourage opening new bins when existing ones fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * 100.0;

    // Cubic coupling: deep-dead-space bins get extra penalty as stream advances.
    score += norm_pr.powi(3) * (50.0 + 150.0 * progress);

    // Reward tight fits: smooth sigmoid-like term on fill ratio.
    let fill = 1.0 - norm_pr;
    score -= (fill * fill * 6.0).tanh() * (20.0 + 30.0 * progress);

    // Interaction with mean residual: prefer bins whose residual deviates below mean
    // (consolidating small residuals), smoothly scaled.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 30.0 - dev * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 60.0 * progress;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement
    // smoothly; if it barely misses, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        let fit_next = (gap / cap).clamp(-1.0, 1.0);
        score -= (fit_next * 4.0).tanh() * (10.0 + 20.0 * progress);
    }

    // Mild penalty for bin proliferation, easing as stream progresses.
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // Small tie-break toward fuller bins.
    score -= fill * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes.
    let post = post_residual as u32;
    let class = match post {
        0 => 0.0,                 // perfect fill
        1..=5 => 1.0,             // near-perfect
        6..=15 => 2.0,
        16..=30 => 3.0,
        31..=50 => 4.0,
        _ => 5.0,                 // large unusable chunk
    };
    score += class * 12.0;

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / cap;
    score -= 40.0 * fill_frac * fill_frac;

    // Harmonic compatibility: does next item divide into post_residual?
    if next_item_size > 0 && next_item_size <= post {
        // next item fits exactly or nearly: strong reward
        let diff = post - next_item_size;
        let harmony = if diff == 0 {
            -60.0
        } else if diff <= 10 {
            -25.0
        } else {
            -10.0
        };
        score += harmony;
        // extra: next item's size class matches leftover class
        let next_class = (next_item_size / 10) as f64;
        let post_class = (post / 10) as f64;
        if next_class == post_class {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize large leftovers
        score += 8.0 * (post as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 55.0;
    }

    // Prefer bins whose residual is below the mean (consolidate fullness).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Modulo-10 harmonic threshold: leftover near multiples of 10 are reusable.
    let m = post % 10;
    if m >= 1 && m <= 3 {
        score += 6.0; // awkward sliver
    } else if m >= 8 {
        score -= 4.0; // nearly round residual
    }

    // Late in stream: tighten up, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    } else {
        // new-bin candidate: penalize more when many bins are open or late stream
        score += 15.0 + 10.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Exact-fill bonus
    if post == 0 {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size ~1, but
    // practically small gaps < 12) can ever use are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    }
    // Moderately awkward gaps (12..25) are risky too.
    if post_residual >= 12 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits strongly.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — reward it, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        if post_residual < 12 {
            score += 55.0; // but not if it creates dead space
        }
    }

    // Lookahead: if the next item fits into the post-residual, reward this
    // placement (creates a useful gap); otherwise penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 {
            score += 10.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate logic: an empty bin is attractive when no existing
    // bin gives a good fit. Penalize the empty bin when a decent fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with tight fits win.
        score += 25.0;
        // But if this item would leave a large awkward gap in every bin,
        // opening fresh is fine — reduce penalty when item is large.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If many bins are open already, discourage yet another one.
        score += 1.5 * open_bins_count as f64;
    }

    // Mild pull toward bins whose residual is near the item (best-fit core).
    score += 0.3 * ((bin_residual - item_size) as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: leaving no dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chain completion: two items perfectly fill the bin
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves more dead space: reward proportional to tightness.
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - two_step_waste / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder; penalize if the dead space
            // is small enough to be unusable anyway.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 50.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers of dead space.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Penalize opening a new bin when open bins can fit, unless lookahead justifies it.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so we only open when it beats all fits.
        score += 120.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // Fresh bin can host both current and next item tightly.
            let combo_waste = (bin_capacity - item_size - next_item_size) as f64;
            score -= 250.0 * (1.0 - combo_waste / bin_capacity as f64);
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        score -= 200.0;
    }

    // Early in the stream, allow slightly more bin openings (exploration of packing structure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used to modulate conservatism.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward: strongly favor bins that end up exactly full.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize leaving large but awkward residual slabs that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small dead space is fine (many items 1..10 fit)
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 4.0; // awkward gap: only small items fit
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        if tightness > 0.5 {
            score -= 20.0 * tightness;
        } else {
            score += 5.0 * (1.0 - tightness); // poor fit in sole bin: mild penalty
        }
    }

    // Lookahead: if the next item could exactly fill the post_residual of
    // this bin, reward it; if next item won't fit the leftover, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 6.0; // leftover becomes dead space for the next item
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Global state: when many bins are open with high mean residual,
    // encourage consolidation into existing bins rather than opening more.
    if bin_residual != bin_capacity {
        let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
        score -= consolidation * 3.0;
    } else {
        // New-bin candidate: penalize opening new bins unless stream is early
        // or open bins are nearly full on average (little room left).
        let room = mean_residual / bin_capacity as f64;
        let new_bin_penalty = 25.0 * (1.0 - progress) + 40.0 * (1.0 - room);
        score += new_bin_penalty;
        // If no open bin fits well (post_residual for new bin is huge anyway,
        // but if all fits would be very loose), allow opening: the base score
        // of 100 - item_size already reflects leftover size.
    }

    // Mild preference for filling bins that are already mostly full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * t) - norm_pr * (0.5 + t * t);
    score += 8.0 * poly;

    // Reward tight fits more aggressively as stream progresses
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= 6.0 * tightness * tightness * (0.5 + t);

    // Penalize waste relative to mean residual across open bins
    score += 0.15 * (pr - mean_residual) * (1.0 + t);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space usable by next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 4.0 * (ni / cap) * (1.0 + t);
        } else {
            score += 3.0 * (ni - pr) / cap * (1.0 - t);
        }
    }

    // Slight penalty for spreading across many bins late in stream
    score += 0.05 * (open_bins_count as f64) * t;

    // New-bin candidate: neutral baseline with mild progress-aware bias
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact fit (0), tiny (1-9), small (10-19), mid (20-49), large (50+)
    let class: f64 = match post_residual {
        0 => -40.0,               // perfect closure — huge reward
        1..=9 => -12.0,           // near-perfect, mostly dead space anyway
        10..=19 => 6.0,           // awkward sliver, only fits smallest items
        20..=49 => 18.0,          // classic dead zone
        _ => 0.0,                 // large residual stays reusable
    };
    score += class;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic bonus scaled by how "cleanly" the next item divides the new residual
        let next_post = post_residual - next_item_size;
        let harmony = match next_post {
            0 => 25.0,
            1..=9 => 10.0,
            _ => 4.0,
        };
        // Tighter chains matter more late in the stream when bins are scarce
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= harmony * (0.5 + 0.5 * progress);
    } else if next_item_size > post_residual {
        // Post residual cannot host the lookahead item: penalize proportionally to its uselessness
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should rarely win unless open bins fit badly
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened when many bins already open (amortization)
        score = 55.0 + (open_bins_count as f64).sqrt() * 2.0;
        // If the item is huge relative to capacity, opening fresh is more acceptable
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        // If mean residual of open bins is too small to matter, opening is fine
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin is the only option
        }
    }

    // Mild preference for filling bins that are already mostly full (tight packing)
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill * 8.0;

    // Mean-residual anchoring: avoid bins whose residual deviates wildly upward from the mean
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item are "dead space" -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size) {
        score += 60.0; // unusable gap
    }
    // Penalize small-but-nonzero gaps super-linearly (dead space pressure).
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it, else we open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so we prefer filling open bins,
    // but allow opening when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If the current item would leave a big gap in any open bin,
        // opening fresh is attractive: discount the new bin.
        if post_residual as f64 > mean_residual * 0.5 {
            score -= 30.0;
        }
        // Lookahead: if next item is small, a fresh bin can host pairs.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few bins, slightly encourage consolidation via mean residual.
    score += 0.05 * open_bins_count as f64;
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    // Lookahead synergy: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // leftover likely wasted
    }

    // Late in stream: prefer closing bins cleanly (zero-residual bias).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 500.0; // exact 2-step chain
        } else {
            // penalize post_residual that is slightly larger than next item (wasted sliver)
            if post_residual > next_item_size {
                score += (post_residual as f64 - next_item_size as f64) * 0.5;
            } else {
                score += (next_item_size as f64 - post_residual as f64) * 0.2;
            }
            score += diff * 0.1;
        }
    }

    // Compare against mean residual: prefer bins below mean residual (tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Penalize opening a new bin unless current residuals are all large.
    if bin_residual == bin_capacity {
        let avg = mean_residual;
        if avg > item_size as f64 * 1.5 {
            score += 200.0; // open bins still have room; discourage new bin
        } else {
            score -= 50.0; // residuals are tight; new bin is fine
        }
    }

    // Slight late-stream conservatism: keep bins tight as stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit bonus: residual after placement small relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Lookahead: if next item fits in the post residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (next_item_size as f64 / 100.0) * 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last chance: this is the only bin that fits — strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // Base penalty high; reduced when open bins have little room left
        score += 200.0 - crowding * 120.0 - progress * 30.0;
        // If the item is large relative to mean residual, opening new bin is attractive
        if item_size as f64 > mean_residual {
            score -= 60.0;
        }
        // Never open a new bin for a perfect fit elsewhere scenario: keep penalty dominant
        if post_residual == 0 {
            score += 500.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins)
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.05;
    }

    // Slight preference for using more open bins early (spread), less late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: tightness of the fit, normalized and non-linearly warped.
    let tight_norm = post / cap; // 0 = perfect fit, 1 = empty bin
    let mut score = 10.0 * (1.0 - (1.0 - tight_norm).powi(3)) * cap.powf(0.5);

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer preserving space (penalize low post_residual less),
    // later, pack tightly (penalize large post_residual strongly).
    let early = (1.0 - progress).powi(2);
    let late = progress.powi(2);
    score += post * (0.4 + 2.2 * late) - post * 0.8 * early;

    // Quadratic dead-space penalty: unusable slivers hurt more than linear.
    score += 0.05 * post * post / cap;

    // Reward filling a bin that matches the next item's needs (lookahead coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        // If the next item fits exactly in the leftover, strongly favor this bin.
        score -= 6.0 * (1.0 - gap / cap).powi(2);
        // Penalize leaving a residual that is *just barely* too small for the next item.
        if post < nxt {
            score += 4.0 * (1.0 - post / nxt.max(1.0)).powi(2) * (0.5 + late);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: opening a new bin should only win when no open
    // bin offers a decent fit. Penalize the empty-bin candidate proportionally
    // to how many bins are already open and how much slack exists on average.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64 + 0.3 * mean_residual;
        // Late in the stream, opening new bins is even less attractive.
        score += 10.0 * late;
    } else {
        // Reward using bins that are already partially filled (keep bin count low).
        let fill = 1.0 - bin_residual as f64 / cap;
        score -= 5.0 * fill.powi(2);
    }

    // Mild preference to keep residuals near the mean (balanced packing).
    score += 0.02 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual buckets by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division class: 0 = perfect/near-perfect, 1 = small, 2 = medium, 3 = large gap
    let class = post_residual / (bin_capacity / 4);
    match class {
        0 => score -= 30.0,                 // near-perfect fit: strongly reward
        1 => score -= 8.0,                  // small usable gap
        2 => score += 4.0,                  // medium gap: mild penalty
        _ => score += 15.0,                 // large dead space: penalize
    }

    // Modulo arithmetic on post_residual: multiples of common item sizes pack well later
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 5 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 4.0; }

    // Lookahead: if next item fits exactly into the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportionally, prefer leaving a harmonic class-0/1 residual after next item
            let post2 = post_residual - next_item_size;
            let class2 = post2 / (bin_capacity / 4);
            score -= 12.0 - (class2 as f64) * 4.0;
            if post2 % 10 == 0 { score -= 4.0; }
        } else {
            // next item won't fit here: penalize more if the gap is small (wasted)
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tighter bins generally: reward closeness of fit
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // New-bin candidate: make it attractive only when existing fits are bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // but if current bin would leave a large dead class, opening fresh is fine
        if class >= 2 {
            score -= 18.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if next item is large, a fresh bin keeps flexibility
        if next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean (tighter ones)
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;
    score -= (post_residual as f64 - mean_residual).max(0.0) * 0.05;

    // Many open bins: encourage consolidation (favor filling existing bins)
    if open_bins_count > 4 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item are "dead". Penalize them heavily, scaled by how
    // dead they are (smaller unusable gap = worse).
    if post_residual > 0 {
        // smallest item is 1 in the general interface; treat gaps < 10 as near-dead
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64) / 10.0;
        } else if post_residual < 20 {
            score += 12.0;
        } else if post_residual < 30 {
            score += 4.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if the leftover gap cannot fit the next item but a slightly
    // larger leftover could have; mild lookahead shaping.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // and encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when bins are numerous or late in stream.
        score += 15.0 + 8.0 * pressure + 10.0 * progress;
    } else {
        // Reward filling existing bins, more so with more open bins.
        score -= 2.0 * pressure;
    }

    // Prefer bins with below-average residual (tighter bins) to consolidate waste.
    let res = post_residual as f64;
    if res > mean_residual {
        score += 0.15 * (res - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - res);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff == 0.0 {
            score -= 40.0; // exact chain: both slots consumed
        } else if diff > 0.0 {
            // leftover still fits next item with some waste
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // leftover too small for next item: dead space risk
            score += 8.0 * (-diff / bin_capacity as f64);
        }

        // Bonus if after chaining, the doubly-post residual would be tiny
        if diff >= 0.0 {
            let post2 = diff;
            score -= 6.0 * (1.0 - post2 / bin_capacity as f64);
        }
    }

    // Tight fits are generally good
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Penalize bins far from mean residual (prefer typical bins, keep outliers flexible)
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Discourage opening new bins when decent fits exist, especially early/mid stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - 0.5 * progress);
        if fitting_bins_count > 0 && post_residual as f64 > next_item_size as f64 && next_item_size > 0 {
            score += 10.0; // an open bin could chain; new bin wasteful
        }
    }

    // Slight preference to fill already-open bins to reduce bin count
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness: reward small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * tightness * tightness;

    // Lookahead: if next item exactly fits the post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item can still fit here: mild reward proportional to how well it fills
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space, more if leftover is large
            score += 0.25 * (post_residual as f64).sqrt() * (next_item_size as f64 / bin_capacity as f64);
        }
    } else {
        // last item: any residual is waste; strongly prefer zero residual
        score += 40.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fits win
        score += 25.0;
        // the worse the best available fit (proxied by mean residual vs item), the more attractive a new bin
        if (item_size as f64) > mean_residual {
            score -= 20.0;
        }
        // early in stream, opening bins is cheaper (more future items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // many open bins: prefer reusing one of them
        score += 2.0 * open_bins_count as f64;
    } else {
        // reward bins whose residual is close to item size (classic best-fit sharpening)
        let slack = (bin_residual - item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        // prefer bins below mean residual (they are the tight ones)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let next = next_item_size as f64;

    let mut score = pr;

    // Non-linear coupling: squared/cubic residual terms modulated by stream progress
    score += 12.0 * norm_pr * norm_pr * cap * (0.5 + 0.5 * t);
    score -= 8.0 * norm_pr * norm_pr * norm_pr * cap * (1.0 - t);

    // Reward tight fits more strongly late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (0.4 + 0.6 * t);

    // Penalize scarce fitting options less if this bin is the only one
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 2.0 * (fit - 1.0);
    }

    // Lookahead: reward residual that can host the next item smoothly
    if next > 0.0 {
        let compat = (pr - next).abs();
        score += 0.15 * compat * (1.0 - t);
        score -= 0.10 * pr.min(next) / cap * cap;
    }

    // Mean residual context: prefer bins below mean residual (tighter bins) via smooth term
    let dev = (mean_residual - pr) / cap;
    score += 6.0 * dev * (1.0 - dev * dev).max(0.0);

    // Mild penalty for proliferating open bins early on
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);

    // New-bin candidate shaping: empty bin gets a neutral-to-slightly-high score unless residuals are bad
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.2 * t) - 10.0 * (1.0 - norm_pr);
        if next > 0.0 && next <= bin_capacity as u32 {
            score -= 5.0 * (1.0 - (next / cap).abs());
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let pr = post_residual as f64;
    let class = (pr / (cap / 8.0)).floor() as i64; // 0..=7 harmonic band

    // Reward placements whose post-residual matches a "harmonic" slot
    // that a plausible future item (10..80, multiples of 5-ish) could fill.
    let nxt = next_item_size as f64;
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly fills the leftover.
            let diff = (post_residual as i64 - next_item_size as i64) as f64;
            score -= 40.0 * (1.0 - diff / cap);
            // Modulo resonance: next item size divisible into residual cleanly
            if post_residual % next_item_size.max(1) == 0 {
                score -= 12.0;
            }
        } else {
            // Next item cannot use this residual: penalize dead space more
            // strongly in low harmonic classes (small leftovers are valuable).
            score += 6.0 * (8 - class as i64).max(0) as f64;
        }
    } else {
        // Last item: prefer tightest fit, strongly.
        score -= 30.0;
    }

    // Integer-division thresholds on post_residual: residuals below 10 are
    // dead space (min item size 1..100 but tiny slots rarely reused).
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill, excellent
    } else if post_residual < 25 {
        score -= 8.0;
    } else if post_residual > 70 {
        // Large residual left behind: bad packing, penalize.
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins
    // are crowded (mean residual low) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap - 5.0 + 20.0 * (1.0 - progress) + mean_residual * 0.5;
        // discourage hoarding many open bins when mean residual is healthy
        if mean_residual > 30.0 {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // new bin useful if next item is bigger
        }
    }

    // Slight preference for fuller bins overall (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size (1..=100, min 1)
    // are unusable dead space; penalize them super-linearly.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Nonlinear dead-space penalty: small residuals are wasted capacity.
    if post_residual > 0 && post_residual < item_size {
        score += (item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0;
    }

    // Open bins pressure: penalize spreading across many bins slightly,
    // encouraging consolidation into existing bins.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Penalize creating a residual that is too small for the lookahead item
    // when the lookahead item would otherwise fit nowhere well.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins), gently steering toward compact packing.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Progress coupling: later in the stream, be more conservative about
    // opening new bins; slight reward for reusing bins as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // New-bin candidate handling: an empty bin has full residual; make it
    // moderately attractive only when no existing bin fits well.
    if bin_residual == bin_capacity {
        score += 12.0; // base cost of opening a new bin
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative, new bin is necessary
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size is ideal.
    let next = next_item_size as f64;
    if next > 0.0 {
        let diff = (post_residual as f64 - next).abs();
        // Strong reward proportional to closeness of post_residual to next item.
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)).powi(6);
        // Exact match: huge reward.
        if diff == 0.0 {
            score -= 25.0;
        }
        // Small but nonzero post_residual (< next item) is dead space unless tiny.
        if post_residual > 0 && (post_residual as f64) < next {
            score += 12.0 * (1.0 - post_residual as f64 / next);
        }
    }

    // Coupling with mean residual: bins far from mean residual are penalized slightly.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize creating very small unusable residuals (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: prefer keeping it closed unless current bin is nearly full
    // and no good lookahead match exists.
    if bin_residual == bin_capacity {
        let tight = (post_residual as f64 / bin_capacity as f64) < 0.2;
        if tight {
            score += 60.0; // discourage new bin when item packs tightly somewhere
        } else {
            score -= 5.0; // mildly encourage new bin for awkward fits
        }
    }

    // Early in stream: slightly favor consolidation into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but penalize near-zero
    // dead space differently depending on whether the next item can use it.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post-residual, strongly
    // reward this placement (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // next item fits but leaves further waste; mild reward scaled by fit quality
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot use leftover space: penalize dead space creation
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0) / 3.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep bins flexible); late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive late.
        let openness = (1.0 - progress) * 40.0;
        score = score * 0.5 + 35.0 - openness;
    } else {
        score += progress * 8.0 * (1.0 - fill_ratio);
    }

    // Relative to mean residual: placing into a bin far below mean residual
    // spreads items out; mildly discourage unless it is a very tight fit.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 5.0 * dev;

    // Small jitter-free tiebreak: prefer bins with more remaining usable space
    // for future large items, scaled down late in the stream.
    score += 0.05 * (post_residual as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with quadratic shaping.
    let mut score = pr;

    // Non-linear coupling: post_residual weighted by stream progress.
    // Late in the stream, residual waste is more costly -> amplify.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += 0.8 * progress_weight * (pr * pr) / cap;

    // Reward bins whose post_residual matches the next item (good chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_frac = 1.0 - ((pr - nxt) / cap).abs();
        score -= 3.0 * match_frac.max(0.0) * (pr / cap);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // Penalize bins far from mean residual (fragmentation avoidance), smoothly.
    let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
    score += 2.0 * dev * dev;

    // Slight preference for fewer open bins when stream is early.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral baseline with penalty so it's chosen only
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * progress + 0.5 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers that are "harmonically clean"
    // (small, or matching common item-size classes) are less harmful.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Non-linear penalty on dead space: tiny leftovers are fine, mid-range
    // leftovers (hard to fill) are heavily penalized.
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual <= eighth {
        score -= 12.0; // near-full bin, small dead space
    } else if post_residual <= quarter {
        score -= 4.0;
    } else {
        // Mid-range dead space: penalize super-linearly
        score += (pr / c) * 20.0;
        // Harmonic class check: leftover matching modulo-10 classes is
        // more likely to be filled by a future item.
        let cls = post_residual % 10;
        if cls == 0 {
            score -= 6.0;
        } else if cls <= 5 {
            score -= 2.0;
        } else {
            score += 2.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward; if it cannot fit, mildly penalize (bin likely closed).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / c);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a new bin wastes all existing residuals.
    // Penalize unless existing bins are nearly full / unusable.
    if bin_residual == bin_capacity {
        let base = 30.0;
        let crowding = (open_bins_count as f64).sqrt() * 2.0;
        let usable = (mean_residual / c).max(0.0);
        score = base + crowding - 25.0 * usable;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score -= (bin_residual as f64 / c) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A residual that is too small to hold any plausible future item is pure waste.
    let min_useful = 10.0;
    if (post_residual as f64) < min_useful {
        score += 25.0 + (min_useful - post_residual as f64) * 3.0;
    }

    // Non-linear penalty on tight-but-wasteful fits: residual in (0, 20) is risky.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bin count and mean residual.
        score += 30.0 + pressure * 8.0 + mean_residual * 0.15;
        // If only this new bin can fit the item, opening it is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: reward fitting into bins, more so under open-bin pressure.
        score -= pressure * 2.0;
        // Last-chance bin: strongly favor using the only bin that can fit the item.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item cannot fit anywhere after this placement, penalize.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_residual {
        score += 5.0;
    }

    // Slight early-stream aggression toward filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward near-perfect two-item matches.
    if next_item_size > 0 {
        let combined = item_size as f64 + next_item_size as f64;
        // Perfect two-item fill bonus (combined == capacity)
        if (combined - bin_capacity as f64).abs() < 1e-6 {
            score -= 1000.0;
        }
        // Does the next item fit exactly into post_residual?
        if next_item_size as f64 == post_residual as f64 {
            score -= 500.0;
        } else if (next_item_size as u32) <= post_residual {
            // Next item fits: reward proportionally to how tight the fit is
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 50.0 * tightness;
        } else {
            // Next item cannot use this bin's leftover: penalize dead space
            score += 30.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: reward minimal post_residual strongly
        score -= 200.0;
    }

    // Compare post_residual relative to mean residual of open bins.
    // Leftover below mean = compact usage, reward; above mean = wasteful, penalize.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize creating very small unusable fragments (1..9 dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 800.0;
    }

    // New-bin candidate handling: opening a bin is only attractive early in the
    // stream or when few bins are open; otherwise discourage proliferation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress + 5.0 * open_bins_count as f64;
    }

    // Mild preference for bins with larger residual (waste less capacity overall).
    score -= 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress-based time horizon: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tight-fit reward: squared residual penalization, stronger late in stream.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0 * (0.5 + progress);

    // Reward bins that fit the item snugly relative to their own residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Exact-fill bonus: perfect closure of the bin.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead pairing: if the next item fits exactly in the post residual,
    // heavily favor this bin; if next item cannot use post residual, mild penalty
    // for leaving awkward dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += (post_residual as f64) * 0.15 * progress;
        }
    }

    // New-bin candidate logic: opening a new bin wastes the mean residual pool.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin grows with number of open bins.
        score += 20.0 + open_bins_count as f64 * 2.0;
        // But if existing bins fit poorly (large mean residual means fragmented),
        // opening fresh is more attractive.
        score -= mean_residual * 0.3;
        // If no open bin can even fit the item, the new-bin call is the only fit;
        // fitting_bins_count==1 with empty residual means forced open.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
        // Early stream: opening bins is cheaper to build a good pool.
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer bins with residual below mean (concentrate waste in few bins).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    // Mild penalty for very large unusable gaps (dead space 1..9 is worst).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;

    // Non-linear polynomial coupling of post_residual with progress:
    // early in the stream, waste is cheap; later, tight fits matter more.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * (1.0 + 2.0 * prog2 + 3.0 * prog2 * progress);
    score += 20.0 * coupling;

    // Smooth penalty for near-full bins that leave tiny unusable slivers
    // (post_residual in (0,10) is dead space): quadratic bump.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (10.0 - pr) * 0.15;
    }

    // Last-chance bin: strongly reward using it (subtract), smoothly scaled
    // by how much residual would remain.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * (1.0 - pr_norm);
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // penalize blocking the next item proportionally to overshoot
        let miss = (next_item_size as f64 - pr).max(0.0);
        score += 0.1 * miss * (1.0 + progress);
    }

    // Smoothly discourage spreading across many open bins when residuals are large
    let mean_r_norm = mean_residual / bin_capacity as f64;
    score += 2.0 * mean_r_norm * (1.0 - prog2);

    // New-bin candidate: make it mildly unattractive unless open bins are crowded;
    // attraction grows smoothly with number of open bins and progress.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(0.0);
        score += 6.0 - 3.0 * crowd - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual via modulo arithmetic.
    // Class 0: post_residual == 0 (perfect closure) -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: small unusable leftovers are penalized.
        // Items are >= 1, so any post_residual is technically usable, but
        // small residuals (< 10) are rarely matched by future items.
        if post_residual < 10 {
            score += 40.0;
        }
        // Harmonic class: post_residual mod capacity fraction classes.
        let quarter = bin_capacity / 4; // 25
        let eighth = bin_capacity / 8;  // 12 (approx harmonic division)
        let m = post_residual % quarter;
        // Residuals near a harmonic multiple of 25 are "clean" slots
        // (e.g. 25, 50, 75) that future items commonly fill.
        if m == 0 {
            score -= 30.0;
        } else if m <= 5 || m >= quarter - 5 {
            // Near-miss of a harmonic class: mildly penalize.
            score += 10.0;
        }
        // Integer-division threshold: post_residual / eighth encodes size class.
        let class = post_residual / eighth;
        score += class as f64 * 3.0;

        // Lookahead: does next item fit into the post_residual?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // Next item can chain into this bin: big reward.
                let tight = (next_item_size as f64 / post_residual as f64).min(1.0);
                score -= 60.0 + 40.0 * tight;
                // Extra reward if chained placement closes the bin too.
                if post_residual - next_item_size == 0 {
                    score -= 100.0;
                }
            } else {
                // Next item cannot use leftover: penalize by gap size.
                let gap = (next_item_size - post_residual) as f64;
                score += gap.min(60.0) * 0.5;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: empty bin (residual == capacity). Default baseline
    // is a mid-range score; opening new bins is only attractive when the
    // item is large relative to capacity (poor fit anywhere else) or when
    // the stream is early and there is room to keep bins flexible.
    if bin_residual == bin_capacity {
        score = 60.0;
        // Large items prefer fresh bins.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 80.0 * (frac - 0.7) / 0.3;
        }
        // Early in the stream, keep flexibility: cheaper to open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // Many open bins with low mean residual: discourage new bins.
        if open_bins_count > 0 {
            score += (mean_residual / bin_capacity as f64).max(0.0) * 50.0;
        }
        // If next item is small, a fresh bin keeps room for it.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
    }

    // Tight fits in existing bins: item fills most of the residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 && bin_residual != bin_capacity {
        score -= 50.0 * (fill - 0.9) * 10.0;
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    if open_bins_count > 4 && mean_residual > bin_capacity as f64 * 0.5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space (10..25) is also costly since few item sizes can use it.
    if post_residual >= 10 && post_residual < 25 {
        score += 20.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item does not fit and post residual is dead space, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: neutral baseline, slightly penalized so it is only
    // chosen when all open bins score badly (dead-space heavy).
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
    } else {
        // Prefer bins whose residual is close to the item (tight coupling).
        score += (bin_residual as f64 - item_size as f64) * 0.1;
    }

    // Early in the stream, be slightly more willing to open bins (future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover after that placement
            let post2 = post_residual - next_item_size;
            score += post2 as f64 * 0.5;
            if post2 == 0 {
                score -= 300.0;
            }
        } else {
            // next item cannot fit here: mild penalty for tight residuals that become dead space
            score += (post_residual as f64).min(next_item_size as f64) * 0.3;
        }
    } else {
        // last item: prefer smallest post residual
        score -= 50.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        score = 500.0 + waste * 0.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 200.0;
        }
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Late-stream consolidation: fewer bins favored, discourage spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 && bin_residual < bin_capacity {
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fill_ratio * fill_ratio * (bin_residual as f64);

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize small dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if post residual is just barely too small for next item,
    // penalize slightly (dead space trap).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += (post_residual as f64 - next_item_size as f64).abs().min(15.0) * 0.4;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: only attractive when open bins are fragmented
    // (high mean residual spread) or item is huge relative to typical residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Penalize opening new bins early or when existing bins fit well.
        score += 15.0 + 10.0 * (1.0 - progress);
        // But if item is large and mean residual is small (bins too full),
        // a fresh bin becomes reasonable.
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
        // Penalize more when many bins already open (avoid bin explosion).
        score += open_bins_count as f64 * 0.5;
        // Reward new bin if it would create a perfect pairing with next item.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 18.0;
        }
        let _ = fragmentation;
    } else {
        // Mild reward for keeping bins balanced: prefer bins whose residual
        // is close to the mean (avoid extreme outliers).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing
    // bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && !is_new_bin {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress) + 40.0 * progress * tightness * tightness;

    // Reward near-perfect fits with smooth quartic term
    score -= 60.0 * (tightness * tightness * tightness * tightness) * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 15.0 + 20.0 * progress;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64).ln() * 2.0 + mean_residual * 0.05;

    // New-bin candidate: penalize slightly so good existing fits win
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that is a multiple of the
    // smallest item granularity (assumed ~10 in classic streams, but sizes are
    // 1..=100, so use gcd-style classes of small divisors).
    let pr = post_residual;
    if pr > 0 {
        // Residuals that are "harmonic" (divisible by common small sizes) are
        // more likely to be filled by future items -> reward them.
        let mut harmon = 0.0;
        for d in [1u32, 2, 4, 5, 10, 20, 25, 50] {
            if pr % d == 0 {
                harmon += 3.0;
            }
        }
        score -= harmon;

        // Dead space in the awkward middle band (pr in 11..=49) is hard to fill
        // for items in 10..80; penalize quadratically, scaled by capacity fraction.
        if pr > 10 && pr < 50 {
            score += (50 - pr) as f64 * (50 - pr) as f64 * 0.05;
        }

        // Very small residuals (< 10) are essentially dead: penalize heavily.
        if pr < 10 && pr > 0 {
            score += 60.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward strongly; if it nearly fits, mild reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this bin's leftover: slight penalty proportional
            // to how much space would be stranded.
            score += (pr as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: residual == capacity. Prefer opening a new bin only when
    // the current item would leave a very awkward residual in an existing bin,
    // or when the stream is early (many items left to come).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base preference for new bins early in the stream.
        score += 80.0 * (1.0 - progress);
        // But if the item is large relative to capacity, a fresh bin is natural.
        score += (item_size as f64 / bin_capacity as f64) * 30.0;
        // If many bins are already open and mean residual is high, discourage
        // opening yet another bin (consolidate).
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 50.0;
        }
    }

    // Mild consolidation pressure: prefer bins with below-mean residual
    // (tighter bins) so loose bins stay available for larger future items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Prefer bins where the item occupies a "harmonic" fraction of capacity
    // (e.g., item fills 1/2, 1/4, 3/4 of the bin before placement).
    let frac_num = (item_size * 4) as f64 / bin_capacity as f64;
    if (frac_num - frac_num.round()).abs() < 0.01 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be useful
    // for any realistic future item (items >= 1, but small gaps < 10 are near-worthless).
    if post_residual > 0 {
        let dead = (10u32).saturating_sub(post_residual) as f64;
        score += 6.0 * dead;
    }

    // Bonus for exact fits or leaving a "canonical" large residual.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual >= 40 {
        score -= 4.0;
    }

    // Lookahead coupling: reward residual that can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 2.0; // residual wasted relative to lookahead
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing
    // bins over opening new ones.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    // (i.e., when mean residual is small or stream is early).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(2) as f64);
        score += 8.0 + 10.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);
    }

    // Mild preference for bins with residual close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 5.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Next item fits in the post residual (good chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Dead space: post residual too small for the next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Prefer bins tighter than the average open bin.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize slightly so it is
    // only chosen when existing bins have bad residuals.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Late in the stream, prefer closing out with existing bins.
        if step_index as f64 / total_items.max(1) as f64 > 0.85 {
            score += 15.0;
        }
    }

    // Small waste bonus: quadratic penalty on leftover waste.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more strongly than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize dead space that can never be used again.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual {
            // next item fits this bin but not after this placement — mild penalty
            score += 6.0;
        }
        // Exact pairing reward
        if next_item_size == post_residual {
            score -= 18.0;
        }
    }

    // New-bin candidate handling: prefer opening a new bin when current open bins
    // are already fragmented (low mean residual relative to item size) or when
    // the item would leave a large awkward gap.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a new bin is only chosen when open bins are bad.
        score += 20.0;
        // If mean residual across open bins is small (fragmented), opening a new
        // bin becomes attractive.
        if (mean_residual as u32) < item_size + 5 {
            score -= 22.0;
        }
        // Late in the stream, avoid opening unnecessary bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // Many open bins already: discourage further sprawl.
        score += open_bins_count as f64 * 0.5;
    } else {
        // Reward using bins whose residual is close to item size (best fit flavor).
        let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
        score -= (bin_capacity as f64 - gap) * 0.05;
    }

    // Global pressure: when many bins are open with large mean residual,
    // encourage consolidation into existing bins.
    if !is_new_bin && mean_residual > (item_size as f64) * 1.5 {
        score -= 4.0;
    }

    // Slight time-horizon coupling: early in stream, be more exploratory
    // (favor tight fits even more); late, just pack efficiently.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: normalized post-residual, non-linearly shaped (tight fits favored super-linearly)
    let mut score = (pr / cap).powf(2.0 + 2.0 * progress) * cap;

    // Reward bins whose leftover can host the next item (smooth lookahead coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = next_item_size as f64 / cap;
        score -= (1.0 - chain_fit) * (1.0 + 2.0 * progress) * 10.0;
    } else if next_item_size > 0 {
        // Penalize dead space that cannot chain (quadratic in unusable slack)
        let dead = pr / cap;
        score += dead * dead * (5.0 + 10.0 * progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Scarcity coupling: when few bins fit, reward existing bins smoothly
    let fit_ratio = if open_bins_count > 0 {
        fitting_bins_count as f64 / open_bins_count as f64
    } else { 1.0 };
    score -= (1.0 - fit_ratio) * (1.0 + 3.0 * progress) * 8.0;

    // Mean-residual alignment: prefer bins near the mean (smooth bell penalty)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 6.0;

    // New-bin candidate: smooth penalty growing with progress and open-bin count,
    // relaxed when current bin would leave large dead space
    if bin_residual == bin_capacity {
        let waste = 1.0 - (item_size as f64 / cap);
        score += (30.0 + 40.0 * progress) * (1.0 + (open_bins_count as f64 / 50.0).tanh())
            - waste * waste * 20.0;
    }

    // Late-stream tightness: push harder toward zero residual as stream ends
    score += (pr / cap).powi(4) * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band does it live in
    let item_class = item_size / (bin_capacity / 4); // 0..3 (tiny/small/mid/large)
    let post_class = post_residual / (bin_capacity / 4);

    // Reward tight fits: low post_residual is good, but dead space in
    // awkward classes (1..20, 51..70 style bands) is worse than "clean" ones.
    let awkward = |r: u32| -> f64 {
        let m = r % 25;
        if m > 0 && m < 5 { 1.5 } else if r > 0 && r <= 10 { 2.0 } else { 0.0 }
    };
    score += awkward(post_residual);

    // Penalize leaving a residual that no typical item (1..100) cleanly fills:
    // a residual equal to a "harmonic" size (25/50/75 or multiples of 10) is reusable.
    let reusable = |r: u32| -> f64 {
        if r == 0 { 6.0 }
        else if r % 25 == 0 { 3.0 }
        else if r % 10 == 0 { 2.0 }
        else { 0.0 }
    };
    score -= reusable(post_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: opening a fresh bin is good for large items or when
    // the item would leave a very awkward remainder in existing bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 >= 0.5 * bin_capacity as f64;
        let poor_fit = post_residual > 0 && post_residual <= 10;
        if large_item || poor_fit || open_bins_count == 0 {
            score -= 10.0;
        } else {
            // Prefer filling existing bins mid-stream for small items
            score += 4.0 + 0.02 * (open_bins_count as f64);
        }
    }

    // Lookahead: if next item exactly fills the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size <= 5 {
            score -= 5.0;
        } else if next_item_size > post_residual {
            // next item cannot use this bin's remainder: mildly penalize
            // wasting a large bin on a small item
            if post_residual > bin_capacity / 2 {
                score += 2.0;
            }
        }
    }

    // Late in the stream, consolidate: prefer existing bins more strongly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score += 1.5; // pushes new-bin candidate down relative to open bins
    }

    // Mean-residual coupling: if average residual is high, prefer bins below
    // the mean (compact them) to leave big bins free.
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 0.5;
    }

    // Tie-break by post_residual class granularity
    score += post_class as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit even the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Dead space too small for the lookahead item is also likely waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (post_residual small relative to bin).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Open-bin pressure: penalize bins more when many bins are already open,
    // encouraging consolidation into existing bins.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current item leaves large dead
    // space everywhere or no good fit exists; make empty bin moderately costly.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.1;
        // But if lookahead item is large and this item is small, new bin may
        // preserve big residual pairing -> slight discount.
        if next_item_size >= 50 && item_size <= 30 {
            score -= 25.0;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // what is needed (best-fit flavor with mean anchoring).
    score += ((bin_residual as f64 - item_size as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect match: post_residual equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when next item exactly fills the leftover
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space that next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Relative to mean residual: prefer bins with less residual (tighter bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize very small dead space (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward exact fills
    if post_residual == 0 {
        score -= 30.0;
    }

    // Mildly discourage opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Time horizon: early in stream, prefer spreading (favor new bins for large items);
    // late in stream, consolidate tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Global state: if many open bins with high mean residual, prefer consolidation.
    if mean_residual > item_size as f64 && open_bins_count > 2 {
        score -= 6.0;
    }
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 20.0;
        } else {
            score += 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: residual^2 scaled by capacity
    let r = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * r * r * bin_capacity as f64 * (0.5 + progress);

    // Reward tight fits via cubic term
    let tightness = 1.0 - r;
    score -= 8.0 * tightness * tightness * tightness * item_size as f64;

    // Penalize bins far from mean residual (non-linear divergence)
    let div = post_residual as f64 - mean_residual;
    score += 0.05 * div * div / (1.0 + mean_residual);

    // Last-chance bonus with smooth saturation
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: prefer leaving room for the next item
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 6.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        score += 4.0 + 6.0 * progress;
    }

    // Mild congestion pressure late in stream
    score += 0.3 * (open_bins_count as f64) * progress * progress;

    // New-bin candidate: penalize unless residual is large and item small
    if bin_residual == bin_capacity {
        let waste = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 18.0 * waste * waste;
        if post_residual as f64 > mean_residual {
            score -= 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Perfect fit: absolute reward ---
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // --- Harmonic classes of post_residual (dead-space quality) ---
    // Class A: residual that can host the next item (lookahead-aware)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * (post_residual as f64 - next_item_size as f64).min(30.0);
    } else if next_item_size > 0 {
        // cannot host next item: penalize by how far off it is
        let gap = (next_item_size as f64 - post_residual as f64).min(20.0);
        score += gap * 2.0;
    }

    // Class B: small unusable residue — dead space penalty via modulo classes
    let pr = post_residual;
    if pr < 10 {
        score += 15.0; // tiny fragment, nearly unusable
    } else if pr % 10 == 0 {
        score -= 20.0; // round harmonic class: easily refilled by common sizes
    } else if pr % 5 == 0 {
        score -= 10.0;
    } else {
        // odd residues are harder to fill; penalize by distance to nearest multiple of 5
        let d5 = (pr % 5).min(5 - pr % 5) as f64;
        score += d5 * 3.0;
    }

    // --- Tightness reward: fraction of bin consumed ---
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 40.0;

    // --- Last-chance bin: strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Prefer a fresh bin when no open bin fits well and current bin leaves bad residue
        let poor_fit = post_residual < 10 || (next_item_size > 0 && post_residual < next_item_size);
        if poor_fit {
            score -= 70.0;
        } else {
            score += 120.0; // discourage opening new bins when existing fit is decent
        }
        // early stream: slightly favor consolidation
        if open_bins_count > 0 && (step_index as f64) / (total_items.max(1) as f64) < 0.3 {
            score += 30.0;
        }
    }

    // --- Mean-residual coupling: penalize bins far below mean (fragmenting bins) ---
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // --- Integer-division threshold on residual class ---
    let class = pr / 20; // 0..=5 harmonic bands
    score -= match class {
        0 => 12.0, // residual <=19: good for small items
        1 => 6.0,
        2 => 0.0,
        3 => -4.0,
        _ => -8.0, // large residual: bin still flexible, mild bonus
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (low post_residual).
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // (below the minimum item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post gap,
    // strongly reward this placement; if it wastes the gap, penalize mildly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading items;
    // with few open bins, encourage consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when current bin is a bad fit,
        // penalized when many bins are already open.
        score += 30.0 + 10.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 45.0; // no alternative: opening a bin is fine
        }
    } else {
        // Existing bin: reward using bins, especially when many are open.
        score -= 4.0 * pressure;
        // Last-chance bonus: if this is the only fitting bin, use it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it is a "loose" bin; prefer filling loose bins to keep the pool tight.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap;

    // Late-stream tightening: as the stream progresses, penalize waste more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact/near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0); // perfect chain match gets up to -40
        } else {
            // wasted lookahead space: penalize large unusable leftovers
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize opening a new bin when a reasonable fit exists among open bins
    if bin_residual == bin_capacity && open_bins_count > 0 && post_residual > 0 {
        score += 120.0 + (open_bins_count as f64) * 2.0;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong fit reward: quadratic bonus for tight packing.
    let fit_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalty grows with number of alternatives (prefer the tightest among many).
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(10.0);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use: penalize proportionally.
        score += 0.15 * post_residual as f64;
    }

    // Perfect closure bonus: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when existing bins fit poorly
    // or stream is early (building a diverse pool of bins helps later).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_alternatives = (fitting_bins_count == 0) as i32 as f64
            + (fitting_bins_count == 1 && post_residual > 40) as i32 as f64;
        // Early stream: mild discount to open fresh bins; late: strong penalty.
        score += 55.0 - 60.0 * poor_alternatives - 30.0 * (1.0 - progress);
        // If mean residual is high, existing bins are roomy; opening new is wasteful.
        score += 0.4 * mean_residual;
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 {
        score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Slight time pressure: late in the stream, prefer tighter fits harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;

    // smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_post * norm_post * (1.0 - progress) * 2.0
        + norm_post * progress * progress * 1.5;
    score += coupling;

    // penalize dead space more when few fitting bins remain
    if fitting_bins_count == 1 {
        score -= 3.0 + progress * 2.0;
    } else {
        score += norm_post * (fitting_bins_count as f64).powf(0.5) * 0.5;
    }

    // lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            score -= (next_item_size as f64) / (bin_capacity as f64) * 2.0;
        } else {
            score += (next_item_size as f64) / (bin_capacity as f64) * 1.0;
        }
    }

    // prefer tight fits relative to mean residual state
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // mild pressure toward consolidating bins early
    score += open_bins_count as f64 * 0.01 * (1.0 - progress);

    // new-bin candidate: penalize opening new bins unless residual would be tiny
    if bin_residual == bin_capacity {
        score += 4.0 - 4.0 * progress;
        if post_residual <= 10 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 residue bands
    let post = post_residual;
    let residue = (post % 10) as f64;
    let decile = (post / 10) as f64;

    // Reward tiny post residuals (near-perfect fits), strongest on small residues
    if post > 0 {
        score -= (10.0 - residue) * 0.8;
    } else {
        score -= 20.0; // perfect fill
    }

    // Penalize residuals in "dead zones": residues 1..=5 are hard to fill
    if post > 0 && post <= 5 {
        score += 6.0;
    }
    if post > 0 && residue >= 1.0 && residue <= 5.0 {
        score += 2.0 * (5.0 - residue);
    }

    // Integer-division thresholds: post in [10,20] pairs with small items
    if post >= 10 && post <= 20 && next_item_size > 0 && next_item_size <= post {
        score -= 8.0; // lookahead can land exactly in this class
    }
    if post >= 10 && post <= 20 && (next_item_size == 0 || next_item_size > post) {
        score += 4.0; // dead space likely
    }

    // Lookahead harmony: next item fits leaving a multiple-of-10 residual
    if next_item_size > 0 && next_item_size <= post {
        let after2 = post - next_item_size;
        if after2 % 10 == 0 {
            score -= 6.0;
        }
        if after2 == 0 {
            score -= 10.0;
        }
    }

    // Decile coupling: prefer filling high-decile bins (large residuals) when many bins open
    score += decile * (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive for large items or when no open bin harmonizes
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            // opening new bin wastes the residual landscape of open bins
            score += 12.0 + mean_residual * 0.1;
        }
    }

    // Stream progression: tighten as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Mean residual deviation: prefer bins close to mean (balanced packing)
    score += ((post as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= ~10 units) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        // Small gaps are half-waste: quadratic dead-space penalty.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    // and residuals are still usable.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing residuals are badly
        // fragmented (mean residual low) or many bins already open.
        score += 20.0 + open_bins_count as f64 * 0.5;
        if mean_residual > item_size as f64 * 1.2 {
            score += 15.0; // existing bins still have room; avoid new bin
        }
    } else {
        // Mild reward for spreading load when bin count is low.
        score -= (2.0_f64).min(open_bins_count as f64) * 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slightly penalize leaving a gap
        // that is neither useful nor empty.
        if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Late in the stream, waste matters more (fewer future items to fill gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: next item exactly fills the post residual (perfect 2-step match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - 0.25 * slack;
        if slack == 0.0 {
            score -= 40.0; // exact chain fill
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportional to the gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Penalize tiny dead space that no realistic item (>=1) can use well;
    // small post_residuals are only good if they are near zero.
    if post_residual < 10 {
        score -= 5.0;
    }

    // Compare against mean residual: prefer bins whose residual deviates
    // favorably (tighter than average gets a mild reward).
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size == 0
            || post_residual < next_item_size
            || (fitting_bins_count <= 1 && post_residual > 20);
        if poor_fit {
            score -= 35.0;
        } else {
            score += 50.0; // keep using existing bins when they fit well
        }
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0 is best).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to how well it fills
            let fill_after = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill_after;
        } else {
            // next item won't fit here: slight penalty for wasting residual
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 10.0 * pressure;

    // Bin far below mean residual is underfilled: reward filling it.
    let gap = mean_residual - bin_residual as f64;
    if gap > 0.0 {
        score -= 0.3 * gap;
    } else {
        score += 0.15 * (-gap);
    }

    // Time horizon: early on, allow opening new bins more freely;
    // late in the stream, strongly prefer existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, modulated by progress and pressure.
        let mut new_cost = 20.0 + 40.0 * progress + 15.0 * pressure;
        // If no bin fits tightly elsewhere, opening new bin is fine early.
        if next_item_size > 0 && next_item_size > 50 {
            new_cost -= 10.0; // big next item: fresh capacity valuable
        }
        score += new_cost;
    } else if progress > 0.8 {
        // Endgame: squeeze every residual.
        score -= 12.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Slight preference for bins with larger residual among equals (best-fit already handled,
    // this breaks ties toward more usable space).
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, small residuals are valuable (tight packing); late, we tolerate
    // larger residuals less because fewer opportunities remain to fill them.
    let pr_norm = pr / cap;
    let phase = 0.5 + 0.5 * (progress * std::f64::consts::PI).sin();
    score += 18.0 * pr_norm * pr_norm * phase;
    score -= 12.0 * pr_norm * (1.0 - phase);

    // Reward tight fits (small post residual relative to item) with smooth coupling.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    // Penalize when post_residual cannot accommodate the next item (lookahead),
    // scaled smoothly by how close it is to fitting.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 15.0 * gap * gap;
        // Reward when post_residual still fits the next item.
        let fits_next = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 8.0 * fits_next * (1.0 - fits_next);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smoothly weighted by progress).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild dispersion penalty: bins far from mean residual get pushed down the list.
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate shaping: neutral-ish baseline, penalized when decent fits exist.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals that are too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Harmonic class reward: residual divisible into capacity quarters/eighths
    let quarters = post_residual % (bin_capacity / 4);
    let eighths = post_residual % (bin_capacity / 8);
    if quarters == 0 {
        score -= 12.0; // perfect harmonic class (25,50,75,100)
    } else if eighths == 0 {
        score -= 6.0;  // secondary harmonic class (12,37,62,87)
    } else {
        // penalize off-class residuals proportionally to distance from nearest class
        let dist = ((quarters as f64).min((bin_capacity / 4 - quarters) as f64)) as f64;
        score += 0.5 * dist;
    }

    // Perfect fit is best
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does post_residual harmonically fit next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size.max(1);
        if rem == 0 {
            score -= 10.0; // next item would fill this bin exactly
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin: leftover is likely dead space
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64) / (mean_residual / cap + 1.0);
        score += 20.0 + 10.0 * progress - if mean_residual < item_size as f64 { 15.0 } else { 0.0 } - crowded.min(15.0);
        // a fresh bin is attractive if the item is large and would fragment an open bin
        if item_size > bin_capacity / 2 && post_residual < 20 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.3 * diff;
    } else {
        score += 0.3 * (-diff);
    }

    // Integer-division threshold on item size: large items prefer tight bins
    if item_size / (bin_capacity / 4) >= 3 && post_residual < 25 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (small post_residual) are costly.
    // If post_residual is nonzero but too small for typical items (1..=100), penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residual that cannot fit the lookahead item when it could otherwise chain.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits (small post_residual that is still usable).
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // mild reward for tight-but-usable fits
        score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Open-bins pressure: many open bins -> favor filling existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins have poor fit potential.
    if bin_residual == bin_capacity {
        // base penalty so new bins are opened only when needed
        score += 20.0 + open_bins_count as f64 * 2.0;
        // but if the item leaves a very usable residual in a fresh bin and next item chains well, soften
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins deviating favorably from mean (tighter than average).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Best-fit core: smaller leftover after placement wins by default.
    let mut score = post;

    if post == 0.0 {
        // Perfect closure: this item seals the bin exactly.
        score -= cap * 0.5;
    } else if nxt > 0.0 {
        if post == nxt {
            // Aggressive 2-step match: leftover exactly absorbs the next item,
            // closing this bin with two items. Dominant reward.
            score -= 2.0 * cap;
        } else if post > nxt {
            // Next item also fits into the leftover; reward tightness of the
            // second-step leftover (two-step best-fit).
            let second_left = post - nxt;
            score -= 0.5 * (cap - second_left);
        } else {
            // Dead space: leftover cannot host the lookahead item. Penalize
            // proportionally to the mismatch, harder late in the stream when
            // few items remain that could ever fill the hole.
            let urgency = 1.2 + 0.6 * progress;
            score += urgency * (nxt - post);
        }
    }

    // Mean-residual coupling: favor bins tighter than the open-fleet average
    // (drives nearly-full bins to closure). Amplified when many bins are open
    // (fragmentation pressure).
    if !is_new_bin {
        let dev = (mean_residual - post) / cap;
        let crowd = 0.5 + (open_bins_count.min(20) as f64) / 40.0; // 0.5..=1.0
        score -= cap * 0.06 * crowd * dev;
    }

    // Last-chance bonus: if this is the only open bin that fits, using it
    // avoids opening a new bin — unless the fit is truly awful.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= cap * 0.25;
    }

    // Inertia against opening a fresh bin. Small items poked into an empty
    // bin create large useless holes, so the penalty is higher for them.
    if is_new_bin {
        score += cap * (0.02 + 0.06 * (1.0 - item / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: prefer keeping it pristine unless fit is poor.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when other bins fit, scaled by how "tight" the fit is elsewhere.
        if fitting_bins_count > 0 {
            let tightness = item_size as f64 / bin_capacity as f64;
            score += 40.0 + 60.0 * (1.0 - tightness);
        } else {
            score -= 25.0; // last resort: open a bin
        }
        // Early in the stream, opening bins is cheaper (future items can fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        return score;
    }

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible future item can use.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += 30.0 * (10.0 - gap); // tiny unusable slivers are bad
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 10.0; // next item won't fit here; keep other options open
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Global state coupling: when mean residual is high, prefer bins below mean (balance avoidance of fragmentation).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Time horizon: late in the stream, tighten packing more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * fit_ratio;

    // Slight penalty for accumulating too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits mildly; later, penalize waste super-linearly.
    let poly = norm_post * norm_post * (0.5 + progress) + norm_post * progress * progress;
    score += 12.0 * poly;

    // Reward near-perfect fits smoothly (quadratic dip around zero post-residual).
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bonus: smooth sigmoid-like gate on fitting_bins_count == 1.
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 15.0 * last_chance * (0.5 + 0.5 * progress);

    // Penalize opening a new bin when open bins exist and item fits reasonably.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let fit_elsewhere = (fitting_bins_count > 0) as f64;
        let waste = (post_residual as f64 / cap);
        score += 20.0 * fit_elsewhere * (1.0 - waste) * (0.5 + progress);
    }

    // Lookahead: reward leaving room for the next item, smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let compat = if pr >= n { 1.0 - (pr - n) / cap } else { 0.0 };
        score -= 6.0 * compat * compat;
    } else {
        // Last item: strongly prefer minimal final residual.
        score += 5.0 * norm_post;
    }

    // Mild pressure toward consolidating among many open bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // Deviation from mean residual: prefer bins near the mean (smooth balance).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify leftover space into
    // capacity-fraction buckets. Residuals in the "tiny" classes (< 20% of
    // capacity) are nearly dead space — penalize them super-linearly.
    let frac = post_residual as f64 / cap;
    let class = (frac * 5.0).floor() as i32; // 0..5 harmonic classes
    score += match class {
        0 => 30.0,               // 0..20% : dead space
        1 => 10.0,               // 20..40%
        2 => 0.0,                // 40..60% : useful
        3 => -3.0,               // 60..80%
        _ => -6.0,               // 80..100% : very reusable
    };

    // Integer-division threshold: perfect fill bonus using modulo arithmetic.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual % 10 == 0 {
        // Residual aligned to the classic item-size grid (multiples of 10)
        // is more likely to be exactly filled by future items.
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement chains perfectly — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nfrac = next_item_size as f64 / post_residual as f64;
            // Reward when next item fills most of the leftover (high fill ratio).
            if nfrac > 0.8 { score -= 12.0; }
            else if nfrac > 0.5 { score -= 4.0; }
            else {
                // Next item would strand a large fraction again — mild penalty.
                score += (1.0 - nfrac) * 6.0;
            }
        } else {
            // Next item cannot use this bin's residual at all.
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it over
    // opening a new bin (new bin would be called with residual == capacity).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating small residuals when many bins are already open
    // (fragmentation grows with open bin count).
    if class <= 1 && open_bins_count > 3 {
        score += (open_bins_count as f64).ln() * 4.0;
    }

    // Stream progression: early on, be conservative about wasting space;
    // late in the stream, close bins aggressively (exact fits worth more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 20.0 * progress;
    }

    // Slight tie-break toward tighter fits (smaller post residual already
    // dominates, but add a mild non-linear squashing for separation).
    score += (post_residual as f64).powi(2) / (4.0 * cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (dead space), while exact / near-exact fits
    // are strongly rewarded.
    if post_residual == 0 {
        // Perfect fit: maximal reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable dead space: harsh penalty.
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual <= 20 {
        // Small gap: likely only fits tiny items; mild penalty.
        score += 15.0;
    } else {
        // Usable residual: mild reward proportional to tightness of fit.
        let tightness = (post_residual as f64) / (bin_residual as f64);
        score -= 30.0 * (1.0 - tightness);
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slightly relax dead-space penalty.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // (mean residual small) or this bin is a poor fit.
    if bin_residual == bin_capacity {
        // Pressure from number of open bins: keep the fleet small early,
        // allow new bins when the stream is long and bins are full-ish.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = mean_residual / bin_capacity as f64;
        score += 120.0 - 90.0 * progress - 100.0 * (1.0 - crowd.min(1.0));
        score += 2.0 * open_bins_count as f64;
    }

    // General open-bin pressure: prefer bins that reduce overall clutter
    // (fill bins with larger residuals first when they remain usable).
    if bin_residual != bin_capacity {
        let mean_gap = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * mean_gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Partial reward: next item fits well into the post residual (small leftover after two placements)
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step_left = post_residual - next_item_size;
        score -= 15.0 - (two_step_left as f64).min(15.0);
    }
    // Penalize post residual too small for the next item (dead space blocks lookahead)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits relative to bin capacity
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: prefer bins whose post residual is below average (tightening)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless the item truly needs it
    if bin_residual == bin_capacity {
        score += 12.0;
        // But allow new bin if it would create a perfect lookahead match
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
    }

    // Progression: as stream advances, be more conservative about waste
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to item size is better.
    if item_size > 0 {
        score -= (item_size as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize awkward dead space: small but nonzero post_residual is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize leaving a gap that blocks it.
            score += 3.0;
        }
    }

    // Last chance: this is the only open bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Mean residual coupling: bins with residual far below mean are less attractive
    // (keep large residual bins flexible for big future items).
    score += ((mean_residual - bin_residual as f64) / bin_capacity as f64) * 8.0;

    // Time horizon: late in the stream, be more conservative — prefer tight packing
    // of existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate: give it a neutral-moderate score so it wins only when
    // open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score = 55.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap; // normalized post residual

    // Smooth polynomial coupling: base score from post residual, modulated by progress
    let mut score = pr * (1.0 + 0.6 * progress * (1.0 - fit) * (1.0 - fit));

    // Penalize dead space non-linearly (quartic-ish in fit)
    score += 12.0 * fit * fit * (1.0 - fit) * (1.0 - fit) * (1.0 - progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - fit) * (1.0 - fit) * progress;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * ((mean_residual - pr).abs() / cap);

    // New-bin candidate: penalize opening a new bin unless residual is large
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * progress + 0.3 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residue classes mod 10
    let class = post_residual % 10;

    // Dead-space classes (unusable for typical small items) get penalized
    if class == 1 || class == 2 {
        score += 12.0;
    } else if class == 3 {
        score += 6.0;
    } else if class == 0 {
        // Perfect fill classes are strongly rewarded
        score -= 15.0;
    }

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small leftovers that can host next item are rewarded
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // leftover cannot host next item: penalize by the gap
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Integer-division threshold on post_residual: halves / quarters of capacity
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual > half {
        score -= 10.0; // still roomy bin, good to fill
    } else if post_residual < quarter && post_residual > 0 {
        score += 8.0; // fragmenting a nearly-full bin is wasteful
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if mean_residual < item_size as f64 {
            score -= 25.0;
        } else {
            // discourage opening new bins when reasonable fits exist
            score += 30.0 * (1.0 - pressure);
        }
    }

    // Stream progression: early on, be slightly more willing to spread (open bins);
    // late, prefer packing tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0;
    score += progress * 3.0;

    // Mild tie-break toward bins already below mean residual (balance avoidance)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..10)
    // are pure waste; penalize them heavily with a non-linear term.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        // Moderately unusable gaps still get a penalty.
        score += (20 - post_residual) as f64 * 2.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 25.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        // Post-residual can't host the next item and is dead space anyway.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize placements that leave many bins open with
    // scattered residuals; encourage consolidation.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual deviates from the mean residual in a
    // "fillable" way: filling a below-average-residual bin consolidates space.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when current item leaves a bad gap
    // everywhere else; an empty bin's full residual is naturally high score,
    // but add a mild bias so it loses to genuinely good fits.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, opening bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect two-item fill (post_residual == next_item_size) is gold.
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as u32 >= next_item_size {
            // Next item still fits here: reward tighter matches more.
            score -= (20.0 * (1.0 - diff / bin_capacity as f64)).max(0.0);
        } else {
            // Next item won't fit after this placement: penalize leftover dead space.
            score += 8.0 + 0.15 * (nxt - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are good targets.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if item is huge or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 20.0 * fill - 10.0 * (1.0 - progress);
        if next_item_size > 0 && (bin_capacity as u32 - item_size) == next_item_size {
            score -= 30.0; // new bin completes a perfect pair
        }
    }

    // Slight preference for compact bins during late stream.
    score += 0.1 * (step_index as f64 / total_items.max(1) as f64) * res;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let cap = bin_capacity as f64;
    let fit_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item won't fit here; slightly penalize leaving awkward gaps.
            score += 4.0 * (next_item_size as f64 / cap);
        }
    }

    // New-bin candidate handling: prefer existing bins unless fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin; reduced when existing bins are crowded.
        let mut penalty = 15.0;
        if mean_residual < item_size as f64 * 1.2 {
            penalty -= 10.0; // existing bins are tight, new bin is fine
        }
        if fitting_bins_count == 0 {
            penalty -= 20.0; // no alternative
        }
        if post_residual as f64 > mean_residual + 20.0 {
            penalty += 10.0; // would create a much emptier bin than average
        }
        score += penalty;
    } else {
        // Favor bins with residual close to the item (perfect-ish fits).
        let diff = (bin_residual as f64 - item_size as f64).abs();
        score += diff * 0.15;
    }

    // Global state coupling: many open bins -> prefer consolidating into emptier bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f * (1.0 - progress) * (post_residual as f64 / cap);

    // Mean residual coupling: placing into a bin below mean residual tightens spread.
    score += 0.1 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * norm_pr * norm_pr * (0.5 + p2) * cap * 0.1;
    score -= 20.0 * (1.0 - p3) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Reward tight fits, more so late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness * (0.3 + progress);

    // Penalize dead space that cannot fit a plausible next item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.6 * gap * (0.5 + progress);
        if next_item_size as u32 <= post_residual {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Divergence from mean residual, scaled by open bins pressure
    score += 0.4 * (mean_residual - pr).abs() / (1.0 + open_bins_count as f64);

    // Mild preference to keep few open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- NEW-BIN CANDIDATE ----
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: strong, but discounted for large items
        score = 900.0 - item_size as f64 * 6.0;
        // If no open bin can fit, the new bin is mandatory
        if fitting_bins_count == 0 {
            score -= 1000.0;
        } else {
            // Only open a new bin when the item is large enough to be "worth it"
            // and fits harmonically with the capacity (item divides capacity cleanly)
            if item_size >= 50 && (bin_capacity % item_size == 0 || item_size % 10 == 0) {
                score -= 120.0;
            }
            // Late in the stream, opening fresh bins is riskier
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += progress * 150.0;
        }
        return score;
    }

    // ---- EXISTING BIN PLACEMENT ----

    // Perfect fit: maximal reward
    if post_residual == 0 {
        score -= 250.0;
    }

    // Harmonic classes: post_residual quantization
    let pr = post_residual;
    // Dead-space zone: residuals 1..10 are nearly unusable for items >=10
    if pr >= 1 && pr <= 10 {
        score += 45.0;
    }
    // Modulo-10 harmonic bonus: residuals that are multiples of 10 remain reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 20.0;
    }
    // Fine-grained class penalty via modulo
    score += (pr % 10) as f64 * 0.35;

    // Lookahead (k=2): reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 35.0;
            // Extra coupling: exact next-item fit is a chain of perfect fits
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Penalize wasted potential proportional to shortfall
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Coupling with mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.25;

    // Mild stream-progression pressure to close bins early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 8.0;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item can fit into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize if next item almost fits but not quite (wasted gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer reuse.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        // But allow opening when mean residual is low (bins nearly full anyway).
        score -= mean_residual * 0.3;
    } else {
        // Favor bins with residual below mean (consolidate emptier space usage).
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    // Slight preference to fill older bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / cap;
    score -= 60.0 * (1.0 - tightness).powi(4);

    // Exact-fit bonus: leaving almost nothing wastes no space.
    if post_residual <= 2 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can chain into this bin: reward closeness of the match.
            score -= 45.0 * (1.0 - gap / cap);
            if gap == 0.0 {
                score -= 70.0; // perfect chain: both items fill the bin exactly
            }
        } else {
            // Next item cannot fit here; penalize proportional to the stranded gap.
            score += 0.35 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins below mean residual (tighter than average).
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): discourage unless no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 55.0 + 0.15 * open_bins_count as f64;
        // If the next item chains perfectly into a fresh bin after this one, soften penalty.
        let chain = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            (bin_capacity - item_size - next_item_size) as f64
        } else {
            cap
        };
        score += base_penalty + 0.4 * chain;
    }

    // Mild late-stream pressure: as the stream progresses, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual quadratically, scaled by capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the leftover; penalize dead space more
            score += 25.0 * fit_ratio;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Time horizon: early in the stream, be conservative (favor tight fits);
    // late in the stream, allow using loose space more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * fit_ratio;

    // Global state: many open bins with high mean residual -> encourage consolidating
    // into bins with below-average residual (already fragmented bins).
    if open_bins_count > 1 {
        let rel = bin_residual as f64 - mean_residual;
        score += 0.05 * rel * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        let no_fit_bonus = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Opening a new bin leaves residual = capacity - item_size; compare against
        // the waste it would create vs. what open bins offer.
        score = (bin_capacity - item_size) as f64
            + 30.0 * no_fit_bonus
            - 45.0 * large * large
            + if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 10.0 } else { 0.0 };
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly
    let progress_coupling = progress * (cap - pr) / cap;
    score -= 12.0 * progress_coupling * progress_coupling * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual (smooth quadratic divergence)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * cap * (0.5 + progress);

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: penalize leaving post_residual that cannot fit the next item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        score += 0.35 * gap * (1.0 - progress * 0.5);
        if pr >= next_item_size as f64 {
            score -= 4.0 * (pr - next_item_size as f64) / cap;
        }
    }

    // Mild pressure against accumulating many open bins late in the stream
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // common item sizes (or small dead space) are more reusable.
    let post = post_residual;
    if post == 0 {
        score -= 25.0; // perfect fit is always excellent
    } else if post < 10 {
        score += 30.0; // tiny dead space is unusable for items >= 10
    } else {
        // Reward residuals divisible by small harmonic classes (10, 20, 25, 50)
        if post % 50 == 0 { score -= 18.0; }
        else if post % 25 == 0 { score -= 12.0; }
        else if post % 20 == 0 { score -= 10.0; }
        else if post % 10 == 0 { score -= 7.0; }
        // Penalize residuals in awkward bands (prime-like / odd leftovers)
        if post % 10 != 0 { score += 6.0; }
        if post % 3 == 0 && post % 10 != 0 { score += 2.0; }
    }

    // Integer-division thresholds: how many "typical" items still fit?
    let slots = post / 20; // coarse granularity slot count
    score -= slots as f64 * 3.0;

    // Lookahead coupling: does this bin's post-residual still fit the next item?
    if next_item_size > 0 {
        if post >= next_item_size {
            score -= 8.0;
            // Harmonic bonus if post_residual is an exact multiple of next item
            if next_item_size > 0 && post % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            score += 14.0; // creates dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin when good fits exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // But if the item is large (harmonic class of big items), a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Tight fits are better than loose ones.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post) as f64 * 0.05;

    // Prefer bins with below-mean residual (filling the emptiest usable bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if no realistic future item (>=1) can use it well;
    // gaps below ~10 are almost always wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits strongly (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: penalize creating new bins when many are open,
    // reward consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: accept it only if it beats packing into
        // a fragmented existing bin; scale with progress.
        score += 35.0 + 40.0 * progress;
    } else {
        score -= 12.0 / pressure;
    }

    // Lookahead: if next item fits exactly into the post-residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot fit in post-residual but this bin's placement
    // leaves a tiny gap, that gap is likely dead.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 15.0;
    }

    // Mild preference for bins with below-mean residual (fill the fullest bins).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward an exact match between post_residual
    // and the next item size (bin becomes perfectly full after two placements).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 / (1.0 + diff * diff)) - 30.0;
        // Slight extra reward when post_residual is exactly next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space that neither the next item nor anything
        // typical can use: post_residual smaller than next item and very small.
        if post_residual < next_item_size && post_residual < 10 {
            score += 40.0;
        }
    } else {
        // Last item: strongly reward tightest fit (minimal post_residual).
        score += 50.0;
    }

    // Compare against mean residual: bins already tighter than average are
    // good candidates to keep filling; loose bins penalized mildly.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate: make the empty bin attractive only when the current
    // item is large (would leave a big hole in any open bin) or no good
    // lookahead match exists elsewhere. Base penalty keeps open bins preferred.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // A fresh bin can host a clean two-item pairing.
            score -= 10.0;
        }
    }

    // Mild pressure to close out bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward bins whose post-residual fits the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 14.0 * (1.0 - gap / cap);
        } else {
            // next item cannot follow here; slight penalty proportional to overflow
            let over = (next_item_size - post_residual) as f64;
            score += 6.0 * (over / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 {
            1.0 / (1.0 + fitting_bins_count as f64)
        } else {
            1.0
        };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bin more acceptable early and when mean residual is low.
        score += 40.0 * fit_pressure * (1.0 - 0.5 * progress);
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual is close to item_size (minimize wasted space).
        let waste = (bin_residual - item_size) as f64 / cap;
        score += 12.0 * waste * waste;
        // Prefer bins with residual below mean residual (use up tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Mild time-horizon modulation: later in stream, be greedier about tight fits.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * horizon * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    let poly = x * x * (1.0 - progress) - x * progress * progress;
    score += 40.0 * poly * cap * 0.01;

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 30.0 * progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        let waste = (x - nx).max(0.0);
        score += 25.0 * waste * waste * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate: mild penalty so open bins are preferred unless residual is large
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    let mr = mean_residual / cap;
    score += 10.0 * (x - mr) * (x - mr) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space: quantify "wasted" fraction.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted after placement

    // Penalize residuals that fall into "dead zones" (small, hard-to-fill slivers).
    if post_residual > 0 {
        // Modulo classes on post_residual: residuals near multiples of 10 pair well
        // with common item sizes; odd slivers are less reusable.
        let class = post_residual % 10;
        if class != 0 && class < 5 {
            score += 6.0; // awkward sliver penalty
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0; // perfect two-item pairing
        } else if slack <= 10 {
            score -= 12.0;
        } else {
            score -= (10.0 - slack.min(10) as f64) * 0.5;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use leftover: leftover becomes dead space.
        score += frac * 20.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins generally (best-fit bias beyond raw post_residual).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit (post_residual small) or when bins are few.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its full residual, discounted slightly.
        score = cap * 0.85;
        // If many open bins with large mean residual, opening new bins is cheap.
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 10.0;
        }
        // If this item leaves a tiny residue in a fresh bin (huge item), it's fine.
        if post_residual <= 10 {
            score -= 15.0;
        }
    } else {
        // Existing bins get a mild preference so we don't sprawl unnecessarily.
        score -= 2.0;
        // If placing here leaves a large residual AND next item is large,
        // keep this bin's space for the next item instead.
        if next_item_size > post_residual && next_item_size > 0 {
            score += 8.0;
        }
    }

    // Progress coupling: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 15.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item are pure waste. Penalize them heavily.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: best possible outcome.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver (min item size is 1 in worst case, but tiny gaps
        // rarely match): hard dead-space penalty.
        score += 90.0 - pr * 4.0;
    } else if post_residual <= 20 {
        // Small gap: risky, moderately penalize.
        score += 25.0 - pr * 0.5;
    } else {
        // Usable residual: reward proportionally.
        score -= pr * 0.35;
    }

    // If the next item fits exactly into the resulting residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use this bin's remainder: mild penalty scaled to waste.
        score += (next_item_size - post_residual) as f64 * 0.25;
    } else if next_item_size > 0 {
        score -= 5.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin count pressure: discourage proliferating bins; but the
    // brand-new empty bin candidate should only win when fits are poor.
    if bin_residual == bin_capacity {
        // New bin: baseline plus penalty growing with number of open bins.
        score = bin_capacity as f64 * 0.8 + open_bins_count as f64 * 4.0;
        // Allow new bin when all existing fits leave tiny dead space.
        if fitting_bins_count >= 1 && post_residual < 10 && bin_residual >= bin_capacity {
            score -= 30.0;
        }
    } else {
        // Slight penalty per extra open bin when residual is large
        // (prefer consolidating into tight bins).
        score += open_bins_count as f64 * 0.3;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight — favor using it up.
    let tightness = mean_residual - bin_residual as f64;
    if tightness > 0.0 {
        score -= tightness * 0.4;
    } else {
        score += (-tightness) * 0.15;
    }

    // Late in the stream, prefer closing bins out (avoid leftover gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.0 + progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual large enough to hold next item: good chaining
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize small dead space that nothing (>=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Late in the stream: consolidate, avoid spreading across bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New bin candidate: only attractive when no open bin fits or item is large
    if bin_residual == bin_capacity {
        let base = if fitting_bins_count == 0 { -5.0 } else { 20.0 };
        score += base + 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post-residual can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize.
        score += 8.0 + 0.10 * post_residual as f64;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins that are already much emptier than average (save big gaps).
    let res = bin_residual as f64;
    if res > mean_residual + 1.0 {
        score += 0.20 * (res - mean_residual);
    } else if res < mean_residual - 1.0 {
        score -= 0.10 * (mean_residual - res);
    }

    // Time horizon: late in the stream, prefer consolidating into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: mildly discourage opening new bins when
    // reasonable fits exist, but allow it when item is large relative to gaps.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let avg_fit = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score = 30.0 + 20.0 * pressure - 15.0 * (1.0 - avg_fit);
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
            score -= 10.0; // big item followed by another big one: fresh bin is fine
        }
        if progress > 0.9 {
            score += 15.0; // avoid opening bins near the end
        }
    }

    // Small tie-breaking noise-free deterministic nudge.
    score += 0.001 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic post-residual modulated by progress
    let coupling = norm_pr * norm_pr * (1.0 + progress) * cap;
    score += 0.35 * coupling;

    // Penalize residuals that waste space relative to mean residual
    score += 0.2 * (pr - mean_residual) * (1.0 + progress.sin());

    // Reward tight fits when lookahead matches post residual well
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.15 * gap * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild new-bin penalty that decays with progress
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) * (1.0 + (open_bins_count as f64).ln().max(0.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (capacity fractions).
    let r = post_residual % 10;
    let q = post_residual / 10;

    // Penalize "dead" residuals that no typical item (1..100) will pair well with:
    // small non-zero residues are awkward; multiples of 10 are harmonic-friendly.
    let dead_penalty = match r {
        0 => 0.0,
        1 | 9 => 6.0,
        2 | 8 => 4.0,
        3 | 7 => 2.5,
        _ => 1.2,
    };
    score += dead_penalty * (1.0 + q as f64 * 0.05);

    // Reward tight fits strongly (harmonic closure).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin is a perfect chain candidate.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // Harmonic class of the gap after the lookahead placement.
            let gr = gap % 10;
            score -= 10.0 - (gr as f64) * 0.8;
        } else {
            // Next item won't fit here: mildly penalize leaving large residuals.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: neutral baseline; open only if placements are poor.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64).sqrt() * 3.0;
        // Prefer opening new bins early in the stream when mean residual is high.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0 + mean_residual * 0.15;
    } else {
        // Slight preference for fuller bins (best-fit flavor via mean comparison).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 60.0 * (10.0 - dead) / 10.0; // tiny gaps are worst
        } else if dead < 20.0 {
            score += 25.0 * (20.0 - dead) / 10.0;
        } else if dead > 50.0 {
            score -= 10.0; // large leftover may still host future items
        }
    } else {
        score -= 40.0; // perfect fill is excellent
    }

    // Reward fitting the item into an existing bin (avoid bin proliferation).
    if bin_residual != bin_capacity {
        score -= 15.0 + 3.0 * open_bins_count as f64;
    } else {
        // New-bin candidate: only attractive if no good existing fit exists.
        score += 20.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * next_item_size as f64 / post_residual as f64;
        } else {
            score += 10.0; // next item cannot use this gap: dead space likely
        }
    }

    // Alignment with mean residual: prefer bins whose leftover is near the mean
    // (keeps bin states homogeneous and predictable).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual exactly matches next item size
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();
        // exact 2-step match: strong reward
        if diff < 0.5 {
            score -= 60.0;
        } else if ni <= pr {
            // next item fits in leftover: graded reward proportional to tightness
            score -= 30.0 * (1.0 - diff / 50.0).max(0.0);
        } else {
            // next item won't fit: penalize proportionally to overshoot
            score += 10.0 * (diff / 50.0).min(2.0);
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Relative-to-mean residual coupling: prefer tighter-than-average bins
    let pr = post_residual as f64;
    score += 0.5 * (pr - mean_residual);

    // Dead-space penalty: very small unusable leftovers
    if pr > 0.0 && next_item_size > 0 && (next_item_size as u32) > post_residual && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish, slightly penalized so only chosen
    // when all open bins would create bad fits (their scores raised above).
    if bin_residual == bin_capacity {
        score = 100.0 - 0.3 * mean_residual;
        if next_item_size > 0 && (next_item_size as f64) < bin_capacity as f64 {
            score -= 5.0;
        }
        // late in stream, discourage proliferation of bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for fuller bins overall
    score -= 0.1 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly penalize wasted capacity (dead space), especially small unusable gaps
    if post_residual > 0 {
        let waste = post_residual as f64 / cap;
        score += 6.0 * waste * waste * cap;
        if post_residual < 10 { score += 25.0; } // tiny gap: nearly unusable
    }

    // Reward tight fits (perfect or near-perfect packing)
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= 12.0 * tightness * tightness;
    if post_residual == 0 { score -= 30.0; } // perfect fill

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 15.0;
        } else {
            // penalize blocking the next item badly
            let over = next_item_size as f64 - post_residual as f64;
            score += 0.4 * over;
        }
    }

    // Time horizon: early in stream, be more conservative (prefer new bins to keep flexibility);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // Global state coupling: many open bins with low mean residual -> prefer consolidation
    let open_f = open_bins_count as f64;
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.15 * mean_gap;
    if open_bins_count > 3 && mean_residual < 30.0 {
        score -= 8.0;
    }

    // New empty bin candidate: penalize mildly so it's only chosen when open bins fit poorly,
    // but reduce penalty early (exploration) and when open bins are nearly full.
    if bin_residual == bin_capacity {
        let base = 18.0 - 12.0 * (1.0 - progress);
        let fullness_bonus = 0.5 * (cap - mean_residual).max(0.0) / cap * 10.0;
        score += base.max(0.0) - fullness_bonus;
        if fitting_bins_count == 0 { score -= 40.0; }
    }

    // Slight preference for bins whose residual is close to item size (best-fit core)
    score += 0.1 * ((bin_residual as f64) - (item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // non-linear polynomial coupling of post_residual with progress
    let prn = pr / cap;
    score += prn * prn * (1.0 + progress) * 20.0;
    score -= (1.0 - prn) * (1.0 - prn) * progress * 15.0;
    // reward tight fits more strongly as stream progresses
    let tightness = 1.0 - prn;
    score -= tightness * tightness * tightness * (10.0 + 30.0 * progress);
    // penalize leaving residuals that match the next item poorly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += gap * gap / cap * (0.5 + progress);
        if next_item_size as f64 <= pr {
            score -= 5.0 * (1.0 - prn) * (1.0 + progress);
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }
    // mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.3 * progress;
    // mean residual alignment
    score += (mean_residual - pr).abs() * 0.1;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands. Small post_residuals (tight fits) are good.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division thresholds on post_residual
    let cls: u32 = match post_residual {
        0 => 0,           // perfect fill
        1..=5 => 1,
        6..=15 => 2,
        16..=25 => 3,
        26..=40 => 4,
        41..=60 => 5,
        61..=80 => 6,
        _ => 7,
    };
    // Reward tight fits (subtract for low classes)
    score -= (7 - cls) as f64 * 3.0;

    // Modulo arithmetic: leftover that is a multiple of small common item
    // sizes (10, 20, 25) is reusable dead space -> reward.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 2.0; }
        if post_residual % 25 == 0 { score -= 2.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    } else {
        score -= 15.0; // perfect closure is highly desirable
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next fits but not exactly: penalize by the new dead space class
            let nxt_post = post_residual - next_item_size;
            score -= 5.0;
            if nxt_post % 10 == 0 { score -= 3.0; }
            if nxt_post == 0 { score -= 10.0; }
        } else {
            // next item cannot use the leftover: penalize large leftovers
            score += frac * 8.0;
        }
    } else {
        // last item: prefer exact closure, otherwise minimal leftover
        score += frac * 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: empty bin gets a baseline that keeps it
    // competitive only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: new bin has full residual, but opening bins
        // freely is bad; penalize slightly, scaled by how many bins are open
        // and stream progression.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 2.0 * (open_bins_count as f64).sqrt() + 5.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful
        score += (mean_residual / bin_capacity as f64) * 15.0;
        // But if item is large relative to typical residual, new bin may be fine
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses
    score += 0.05 * (open_bins_count as f64);

    // Prefer placing large items into bins with small residual (best-fit coupling)
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for even the
    // smallest plausible item are pure waste — penalize them heavily.
    let min_useful = 20u32;
    if post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 6.0;
    } else {
        // Mild super-linear decay of residual preference
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 8.0);
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus open-bin pressure
        score += 25.0 + pressure * 3.0;
        // If lookahead item can combine with current item in a fresh bin,
        // opening a new bin is more attractive.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0;
        }
    } else {
        // Reward using already-open bins, scaled by how full the fleet is
        score -= pressure * 0.5;
    }

    // Coupling with mean residual: prefer bins whose residual is close to
    // the mean (balanced packing) unless it's a new bin.
    if bin_residual != bin_capacity {
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += diff * 0.15;
    }

    // Lookahead: if the post residual exactly accommodates the next item,
    // this is a chained fit — big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (small post_residual) with a superlinear penalty on waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize small-but-nonzero dead space (unusable slivers) more than exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Lookahead coupling: if the next item exactly fills the post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits here too: mild reward proportional to how well it nests
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize leaving large residual that likely strands
            let strand = post_residual as f64 / bin_capacity as f64;
            score += 15.0 * strand;
        }
    } else {
        // last item: strongly prefer closing bins
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.25 * (bin_residual as f64 - post_residual as f64);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when existing
    // residuals are large relative to the item (poor fits everywhere) or few bins exist.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual.max(0.0);
        let pressure = avg_waste / bin_capacity as f64; // how wasteful open bins are
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a new bin, discounted when open bins are bad hosts.
        score += 55.0 - 45.0 * pressure - 10.0 * (1.0 - progress);
        // Slight preference for new bins early when the stream is long (more future to exploit).
        score -= 5.0 * (1.0 - progress);
        // If many bins already open, opening more dilutes mean residual utility.
        score += (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // Encourage filling bins whose residual is far below the mean (below-average slack).
        if mean_residual > 0.0 {
            let rel = bin_residual as f64 / mean_residual;
            score += 6.0 * (rel - 1.0).clamp(-1.5, 1.5);
        }
        // Mild reward for reducing number of bins we must keep track of when few fitting bins.
        if fitting_bins_count <= 2 {
            score -= 4.0;
        }
    }

    // Time-horizon modulation: late in the stream, prioritize consolidation (small residuals).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.35 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic in normalized post-residual
    let post_norm = post / cap;
    score += 12.0 * post_norm * post_norm * cap;

    // Reward tight fits more aggressively as stream progresses
    let tightness = 1.0 - post_norm;
    score -= 25.0 * progress * tightness * tightness;

    // Penalize leaving room that exactly fits the next item? No — reward it,
    // since it enables a perfect follow-up packing.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let exact = if (next_item_size as u32) == post_residual as u32 { 1.0 } else { 0.0 };
        score -= 18.0 * exact + 6.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize dead space mildly
        score += 4.0 * post_norm * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - post_norm);
    }

    // New-bin candidate: penalize opening a bin when good fits exist,
    // but allow it late in the stream or when few bins fit the item.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let open_penalty = 20.0 * (1.0 - fit_pressure) * (1.0 - 0.5 * progress);
        score += open_penalty;
        // Late stream: prefer filling existing bins
        score += 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins first)
    score += 3.0 * (mean_residual - post) / cap;

    // Slight preference for bins with larger pre-residual consumed (better utilization)
    score -= 0.05 * (bin_residual as f64 - item_size as f64) / cap * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of the leftover space: bins whose residual is a multiple of
    // common item sizes are more likely to be filled later -> reward them.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit: best possible outcome
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 3 == 0 {
        -2.0
    } else {
        4.0 // awkward leftover
    };
    score += harmonic_bonus;

    // Capacity fraction classes: how full the bin becomes after placement
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    if fill > 0.9 {
        score -= 8.0;
    } else if fill > 0.7 {
        score -= 4.0;
    } else if fill < 0.4 {
        score += 5.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly or well,
    // reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 15.0;
            } else if slack % 10 == 0 {
                score -= 7.0;
            } else if slack < 10 {
                score += 3.0; // tiny unusable sliver next step
            }
        } else {
            score += 2.0; // next item can't use this bin anyway
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 3 {
        score += 1.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate: only attractive when open bins are crowded and
    // residuals are large and unusable.
    if bin_residual == bin_capacity {
        let avg_waste = (mean_residual - post_residual as f64).max(0.0);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score = 45.0 + avg_waste * 0.5 / pressure - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is the only choice
        }
    }

    // Slight preference for tighter bins overall (best-fit flavor)
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    // Dead-space penalty for small unusable remainders
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item (1..100 stream, but small gaps < 12 are statistically wasteful)
    // are heavily penalized — they are effectively dead space.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (12.0 - post_residual as f64);
    }

    // If the leftover cannot fit the lookahead item, the gap is likely dead
    // for the next step too — penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Perfect fit reward: filling the bin exactly is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to the bin's current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: discourage spreading across many open bins when
    // residuals are already small; encourage consolidation.
    let pressure = open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
    score += 0.35 * pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the fit into this bin would
    // leave a very poor, unusable remainder.
    if bin_residual == bin_capacity {
        // neutral baseline for a fresh bin, adjusted by how bad the
        // alternative fit would be.
        score += 15.0;
        if post_residual > 0 && post_residual < 25 {
            score -= 30.0; // fresh bin leaves a large, reusable gap
        }
    }

    // Late in the stream, consolidation matters more (fewer future items
    // to fill partial bins); mildly favor tight existing fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong pull toward tight fits: exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize large leftover space super-linearly (dead space).
        score += (post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 30.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // perfect chain: bin fully consumed by next item
        } else if post_residual >= next_item_size {
            let diff = post_residual - next_item_size;
            // closer match is better; scale relative to capacity
            score -= 150.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item won't fit in the leftover: penalize proportionally
            let miss = next_item_size - post_residual;
            score += 60.0 + miss as f64 * 0.8;
        }
        // If next item fits current residual directly, mild bonus for keeping bin viable.
        if next_item_size <= bin_residual {
            score -= 20.0;
        }
    } else {
        // Last item: just close as tight as possible.
        score -= 200.0;
    }

    // Relative-to-mean coupling: bins with residual well below mean are "denser";
    // prefer filling those further to consolidate.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0 + item_size as f64 * 0.5;
    }

    // New-bin candidate handling: it is recognizable by bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin fits well.
        // Penalize new bins when other fitting bins exist and mean residual is small.
        if fitting_bins_count > 1 {
            score += 500.0;
        } else if fitting_bins_count == 1 {
            // Only the new bin "fits" trivially (it always fits); the real fitting
            // open bins count excludes it, so if any open bin fits, prefer it.
            score += 300.0;
        }
        // Allow new bins late in the stream when open bins are all nearly full.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 {
            score -= 150.0 * progress;
        }
    }

    // Mild consolidation pressure: fewer open bins is better; prefer already-open bins.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small is already good; amplify).
    score *= 1.0 + (post_residual as f64) / (bin_capacity as f64);

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny useless sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits in post_residual (good chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * (next_item_size as f64);
        } else {
            // Penalize wasting space the next item could have used.
            let waste = (post_residual as f64).min((next_item_size - 1) as f64);
            score += 0.10 * waste;
        }
    }

    // Encourage filling bins with large residuals when many bins are open (consolidation).
    if bin_residual > mean_residual + 10.0 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Mild penalty for opening a new bin when open bins could fit (handled via empty-bin call):
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // New bins are more acceptable early and when few bins are open.
        score += 18.0 - 8.0 * progress - (open_bins_count as f64).min(10.0);
        // If no open bin fits, opening is unavoidable: soften penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // If next item is large, a fresh bin may be a good investment.
        if next_item_size >= 50 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Time horizon: late in the stream, avoid spreading across bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog = progress.clamp(0.0, 1.0);

    // Smooth non-linear coupling: post_residual scaled by a progress-dependent factor.
    // Early in the stream, tight fits matter slightly less (bins can still be reused);
    // later, minimize dead space aggressively.
    let tightness_weight = 1.0 + 0.8 * prog * prog; // smooth quadratic ramp
    score *= tightness_weight;

    // Non-linear residual-shape penalty: residual near half-capacity is the most
    // "flexible" leftover; residual near 0 wastes a bin, large residual is fine.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = (pr / cap).clamp(0.0, 1.0);
    let flexibility = 4.0 * x * (1.0 - x); // parabola peaking at x=0.5
    score -= 6.0 * flexibility * (1.0 - 0.5 * prog);

    // Lookahead coupling: if the next item fits the post-residual, reward this bin
    // smoothly (quadratic in the slack mismatch).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let mismatch = (pr - nx) / cap;
            score -= 4.0 * (1.0 - mismatch).max(0.0) * (1.0 - mismatch).max(0.0);
        } else {
            // Next item won't fit: mild penalty proportional to overshoot
            let over = (nx - pr) / cap;
            score += 2.0 * over * over;
        }
    }

    // Last-chance bonus: this is the only bin that fits; strongly prefer it over
    // opening a new bin (smooth saturation to avoid extreme scaling).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: slight extra pressure toward the tightest fit
        let denom = fitting_bins_count as f64;
        score += 1.5 * (1.0 - 1.0 / denom);
    }

    // New-bin candidate handling: empty bin (bin_residual == bin_capacity).
    // Penalize opening a new bin when decent fits exist, but let it win when the
    // item is large relative to all residuals (smooth comparison via mean_residual).
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        score += 20.0 * (1.0 - mean_gap.min(1.0));
        // Late in the stream, opening a fresh bin is slightly cheaper than
        // fragmenting many partially-filled bins.
        score -= 3.0 * prog;
    }

    // Mild penalty for proliferation of open bins (encourages consolidation),
    // smoothly scaled by stream progress.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * prog);

    // Small tie-breaker coupling with mean residual: prefer bins below the mean
    // residual (they are "more filled" than average).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues divisible by common item sizes are reusable
    let pr = post_residual;
    let residue_class = pr % 10;
    // Residuals that are multiples of 10 (or 5) are more likely reusable later
    if residue_class == 0 {
        score -= 12.0;
    } else if residue_class == 5 {
        score -= 6.0;
    } else {
        // penalize awkward residues proportionally
        score += (residue_class as f64) * 0.8;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits: residual is usable
            score -= 20.0 + (next_item_size as f64) * 0.1;
            // harmonic check: does next item leave a nice residue too?
            let npr = pr - next_item_size;
            if npr % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; residual likely dead space
            score += (next_item_size as f64) * 0.05;
        }
    }

    // Integer-division thresholds on post_residual
    let pr_half = pr / 2;
    if pr_half >= 10 && pr_half >= item_size / 2 {
        score -= 5.0; // residual still splits into useful halves
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity means fresh bin
    if bin_residual == bin_capacity {
        // prefer reusing a decently tight existing bin; new bin is a fallback
        score = 100.0 + (post_residual as f64);
        // early in the stream, opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 30.0;
        // if many bins already open and mean residual is large, discourage new bin
        score += (open_bins_count as f64) * 2.0 + mean_residual * 0.3;
        // but if no open bin fits at all (this is only candidate), it must be chosen
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Mild penalty for very loose fits (large waste relative to item)
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 15.0;

    // Slight preference to fill bins more when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post-residuals that are too small for
    // typical future items (1..=100) but nonzero are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty.
            score += 40.0 + (10 - post_residual) as f64 * 3.0;
        } else if next_item_size > 0 && post_residual < next_item_size {
            // Dead space relative to the lookahead item.
            score += 25.0 + (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Usable gap: mild reward scaled by how well it matches lookahead.
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 8.0 + (post_residual - next_item_size).min(30) as f64 * 0.2;
            }
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += bin_pressure * 2.0;
        // But if no open bin fits well, opening may be fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Using an existing bin relieves pressure slightly.
        score -= 2.0 + 0.1 * open_bins_count as f64;
        // Favor bins with below-mean residual (keep a spread of usable gaps).
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect packing of the next item).
    let pr = post_residual as f64;
    let nx = next_item_size as f64;

    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: this bin is ideal.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits too; reward tightness of the two-chain.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item won't fit; penalize leftover dead space more strongly
            // if it is small (unusable sliver).
            let gap = nx - pr;
            if gap <= 10.0 {
                score += 30.0; // tiny unusable sliver
            } else {
                score += 0.15 * gap;
            }
        }
    }

    // Compare against mean residual: prefer bins already below-average residual
    // (dense bins) so loose bins stay available for larger future items.
    score += 0.5 * (pr - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when no decent fit
    // exists; add a penalty that shrinks as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible item can fill.
    let min_item = 1.0;
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to waste.
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64)).abs();
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowding effect: many open bins with high mean residual -> prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score += 0.05 * crowding * (1.0 - progress);

    // New-bin candidate logic: opening a fresh bin is attractive only when the
    // item is large relative to residual and open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score -= 8.0 * big_item + 10.0 * fragmentation;
        // Late in the stream, discourage spawning extra bins.
        score += 20.0 * progress;
    }

    // Small bonus for keeping residual at "harmonic" sizes (multiples of 10).
    if post_residual % 10 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: waste after placement
    let mut score = pr;

    // Smooth non-linear coupling of residual with stream progress:
    // late in the stream, compact placements matter more -> penalize large residuals quadratically
    score += 40.0 * progress * norm_pr * norm_pr * cap;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= 30.0 * (1.0 - norm_pr).powi(3) * fit_norm * cap;

    // Lookahead coupling: if the next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 25.0 * (-gap / 20.0).exp() * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress * 0.5);
    }

    // Penalize bins far below mean residual (fragmentation) with smooth term
    score += 5.0 * ((pr - mean_residual) / cap).powi(2) * cap * (1.0 - progress);

    // Mild pressure to reuse open bins as their count grows
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: smooth penalty scaled by how much of the new bin would go unused
    if bin_residual == bin_capacity {
        score += 10.0 + 50.0 * (1.0 - fit_norm).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Harmonic class: penalize dead space based on capacity fractions.
    // Residuals in (0,10) are nearly unusable; residuals >= 10 can host
    // small items. Use integer division thresholds on post_residual.
    let small_class = post_residual / 10; // 0..=9 harmonic class
    score -= (small_class as f64) * 8.0;

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // reward bins whose leftover can host the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
            // extra bonus if next item fills it perfectly after placement
            if post_residual - next_item_size <= 10 {
                score -= 40.0;
            }
        } else {
            // next item won't fit here; penalize leaving large-but-awkward gaps
            let gap = post_residual;
            if gap >= next_item_size - 5 && gap < next_item_size {
                score += 25.0; // near-miss gap is dead space for the lookahead
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: large penalty so existing bins win
        // whenever they fit reasonably well.
        score += 150.0;
        // Reduce the penalty as the stream progresses and bins accumulate,
        // making consolidation less attractive late.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
        // If many open bins already exist, prefer packing into them.
        score += (open_bins_count as f64) * 2.0;
        // If the item is large relative to capacity, a new bin is more natural.
        if item_size * 2 >= bin_capacity {
            score -= 60.0;
        }
    }

    // Modulo-arithmetic flavor: bins whose residual is a "nice" fraction
    // of capacity (multiples of 25) are easier to fill later; reward them.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Mild tie-breaker toward bins with below-average residual (filler bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A post_residual that cannot fit even the smallest plausible item is wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Penalize gaps that cannot fit the lookahead item (dead space for the near future).
    if next_item_size > 0 && post_residual < next_item_size {
