    // but favor using existing bins over opening new ones when fit is decent.
    score += open_bins_count as f64 * 0.05;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current bin's
    // post-fit residual would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the best existing fit leaves a terrible gap, allow new bin.
        if post_residual < 10 && item_size <= 10 {
            score -= 30.0;
        }
    }

    // Mild progression scaling: later in stream, be slightly more conservative
    // with residual quality.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight superlinearity.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match strongly rewarded.
        score -= 12.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0) * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Penalize leaving post_residual slightly below next item (dead space for lookahead).
        if (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // If post_residual can hold next item exactly-ish, extra bonus relative to mean residual.
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 3.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / mean_residual.max(1.0)).max(0.0);
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are less attractive unless perfect fit.
    let rel = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * rel;

    // Last-chance bin (only fitting bin): strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Late in the stream, consolidate: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses; allow early exploration.
        score += 25.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * progress;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 15.0;
    }

    // Lookahead: reward if the next item fits in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward for chaining: post residual also fits a fraction of next item.
            let chain = (post_residual as f64) / ((next_item_size + item_size) as f64);
            score -= 5.0 * chain.min(1.0);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity && bin_capacity == 100 {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if this bin would be nearly empty of waste for large items, allow it.
        if item_size >= 70 {
            score -= 25.0;
        }
        // Open new bins more readily early in the stream (future items can fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // Discourage hoarding too many open bins late.
        score += (open_bins_count as f64).powf(1.3) * 0.4 * progress;
    }

    // Global residual pressure: if mean residual is high, prefer filling existing bins.
    if mean_residual > (item_size as f64) * 1.5 {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Mild penalty for very fragmented open-bin pool.
    score += 0.05 * open_bins_count as f64;

    // Time-horizon modulation: later in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize large residuals more strongly as stream advances (dead space matters late)
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth bonus
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: bonus if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 15.0 * (1.0 - nxt / cap) * (1.0 - progress * 0.5);
        } else {
            score += 10.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Slight penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean (balance)
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are tight
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which tenth of capacity it occupies
    let item_class = item_size / 10;
    let residual_class = bin_residual / 10;

    // Reward placing items into bins whose residual is in the same harmonic class
    if residual_class == item_class {
        score -= 6.0;
    }

    // Perfect fit reward (post_residual exactly 0 or a tiny harmonic remainder)
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space in unusable harmonic classes (post_residual < smallest item)
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size > 50 {
            score -= 12.0;
        }
        // Open a fresh bin for a new item if next item pairs well (item + next <= capacity)
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    // Lookahead: if next item fits exactly into the post residual, reward strongly
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 3.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // next item would have fit pre-placement but not after: mild penalty
        score += 4.0;
    }

    // Prefer filling bins with large residual when many bins are open (consolidation)
    if open_bins_count > 3 {
        score -= (bin_residual as f64 - mean_residual) * 0.08;
    }

    // Late in the stream, tighten packing: penalize leaving large residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Harmonic modulo bonus: item + post_residual divisible nicely by 10
    if (post_residual % 10) == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 11 {
        score += (11 - post_residual as i32) as f64 * 18.0;
    }
    // Gaps that cannot fit the smallest possible item (1..) are pure waste;
    // gaps below 10 can only be filled by very small items -> strong penalty.
    if post_residual > 0 && post_residual < item_size.min(10) {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 12.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.35;

    // Mean residual coupling: prefer bins that reduce residual dispersion.
    score += ((post_residual as f64) - mean_residual).abs() * 0.4;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item fits in post residual, mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item would NOT fit in post residual, penalize dead space creation.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // New-bin candidate handling: only attractive late in the stream or when
    // no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let mut nb = 55.0;
        if fitting_bins_count == 0 {
            nb -= 60.0; // must open a new bin
        }
        if post_residual > 0 && post_residual < 11 {
            nb += 20.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            nb -= 15.0;
        }
        nb += progress * 5.0;
        score = score.max(nb);
        if fitting_bins_count > 0 {
            // Prefer existing bins unless they are all poor fits.
            score = score.max(45.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match for next item -> strong reward
        if gap == 0.0 {
            score -= 300.0;
        } else if (post_residual as i64) >= (next_item_size as i64) {
            // Next item still fits: mild reward proportional to tightness
            score -= (50.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // Next item would NOT fit: penalize wasted potential
            score += 40.0 + gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        // New bin candidate: baseline penalty unless item is large relative to capacity
        // or open bins are already very full (mean residual low)
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let item_ratio = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 80.0 * item_ratio - 60.0 * mean_fullness;
        // If next item is large, a fresh bin may be valuable
        if next_item_size > 0 {
            let next_ratio = next_item_size as f64 / bin_capacity as f64;
            score -= 50.0 * next_ratio;
        }
    }

    // Early in the stream, allow slightly more freedom to open bins (diversification)
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= 30.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + (5 - post_residual) as f64 * 10.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize creating residuals that no plausible future item can use.
    // Items >= 10, so residual < 10 is dead space unless it is 0.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well next item uses leftover.
            let nxt = next_item_size as f64;
            let pr = post_residual as f64;
            score -= 40.0 * (nxt / pr) * (nxt / pr);
        } else {
            // Next item won't fit here: slight penalty proportional to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 5.0 * (overshoot / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Time horizon: early in stream, be conservative about filling bins poorly;
    // later, prioritize closing out bins (reward using bins with small residual).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= t * 30.0 * tightness;

    // Global state: many open bins with high mean residual -> encourage
    // consolidating into existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.5 * mean_residual.min(100.0) / (open_bins_count.max(1) as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; shrinks late in the stream.
        let open_cost = 40.0 * (1.0 - 0.5 * t);
        // Cheaper to open if current open bins are mostly full (low mean residual).
        let congestion = mean_residual / bin_capacity as f64;
        score += open_cost - 25.0 * congestion;
        // If many bins can fit the item, opening a new one is wasteful.
        score += 10.0 * fitting_bins_count as f64;
    }

    // Mild preference for bins with less residual overall (best-fit flavor),
    // scaled to avoid overwhelming exact-fit signals.
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress smoothly in (0,1).
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: non-linear polynomial shaping of post_residual.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]
    score += 8.0 * x * x - 4.0 * x * x * x; // penalize large dead space smoothly

    // Strongly reward tight fits: post_residual near 0 gets big bonus.
    score -= 20.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Perfect fit bonus with smooth decay.
    score -= 15.0 * (-pr as f64 / 5.0).exp();

    // Last-chance bin: if this is the only fitting bin, reward heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize opening a new bin unless residuals elsewhere are poor.
    if bin_residual == bin_capacity {
        let waste_penalty = 25.0 + 30.0 * progress;
        let mean_term = mean_residual / cap;
        // If mean residual is large, opening new bins is wasteful.
        score += waste_penalty * (0.3 + mean_term);
        // Late in stream, strongly discourage new bins.
        score += 20.0 * progress * progress;
        // But if item is large and mean residual small, allow it.
        score -= 10.0 * (item_size as f64 / cap) * (1.0 - mean_term);
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (-gap / 10.0).exp();
    } else if next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving awkward residual.
        score += 3.0 * x;
    }

    // Slight preference to fill more-loaded bins (fewer open bins overall).
    score += (open_bins_count as f64).ln().max(0.0) * (0.5 * mean_term);

    // Progress-scaled polynomial coupling term.
    score += progress * (x - 0.5) * (x - 0.5) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division bands.
    let pr = post_residual as i64;
    let residue = pr % 10;
    let band = pr / 10; // 0..=10

    // Penalize small-but-nonzero residuals (dead space): residue 1..9 is awkward.
    if residue > 0 && residue <= 4 {
        score += 6.0 - (residue as f64) * 1.2; // residue 1 worst, 4 mild
    } else if residue > 4 && residue < 10 {
        score += (10 - residue) as f64 * 0.8;
    }
    // Reward harmonic "perfect" residuals (multiples of 10, and 0 especially).
    if residue == 0 {
        score -= 8.0;
    }
    if pr == 0 {
        score -= 10.0; // perfect closure
    }

    // Band-based shaping: mid bands (residual 20..60) are reusable; tiny bands are not.
    score += (5 - band).abs() as f64 * 1.5;

    // Lookahead coupling: does next item fit into post_residual harmonically?
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if ni <= pr {
            // Reward when post_residual is a harmonic multiple / near-multiple of next item
            let div = pr / ni.max(1);
            let rem = pr % ni.max(1);
            if rem == 0 {
                score -= 9.0;
            } else {
                score -= (rem as f64) * 0.35;
            }
            if div >= 1 && div <= 2 {
                score -= 3.0; // tight 1-2x reuse is ideal
            }
        } else {
            // Next item won't fit here; penalize leaving large residual that will strand.
            score += (ni - pr) as f64 * 0.25;
        }
    } else {
        // Last item: strongly prefer perfect closure.
        score -= pr as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = mean_residual / bin_capacity as f64;
        // If open bins are mostly full (low mean residual), opening new is fine.
        score += 20.0 - congestion * 25.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // Late in stream, prefer reusing existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild pressure to consolidate: fewer open bins relative to mean residual.
    score += open_bins_count as f64 * 0.15 - mean_residual * 0.05;

    // Item-size harmonic class: large items should target tight fits.
    let item_class = item_size / 20; // 0..4
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * item_class as f64 * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Non-linear penalty: small gaps are much worse than proportional.
        score += 40.0 / dead.sqrt();
        // Anything below the smallest item size (1) is truly dead; with unknown
        // distribution treat gaps < 10 as near-dead extra penalty.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + gap);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item cannot use the leftover: penalize.
        score += 15.0;
    }

    // Open bins pressure: discourage opening new bins when many are open and sparse.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin starts with large residual; only attractive if open bins are crowded.
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 20.0 + 8.0 * pressure;
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Prefer bins tighter than average (good fills).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit
    score -= (item_size as f64) * 0.5;

    // 2-step lookahead: reward if next item fits in the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 1.2;
            // exact match bonus
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // penalize dead space that the next item cannot use
            score += (post_residual as f64) * 0.6;
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance fitting bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's a great fit
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Late in stream: be more conservative, keep residuals usable
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 25.0 * fit_ratio;
    } else if fit_ratio > 0.7 {
        score -= 12.0 * fit_ratio;
    } else if fit_ratio < 0.25 {
        // Penalize wasteful placements into mostly-full bins leaving slivers.
        score += 4.0;
    }

    // Dead-space penalty: small post_residual that can't fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * next_fit;
        } else {
            // Next item won't fit here; slight penalty if it leaves a large awkward gap.
            score += 3.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        score += 15.0; // default discourage opening new bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fit_ratio < 0.5 {
            score -= 10.0; // poor fit elsewhere -> new bin more attractive
        }
        if mean_residual < item_size as f64 * 0.6 {
            score -= 12.0; // open bins mostly too full
        }
        if progress > 0.8 {
            score += 5.0; // late stream: consolidate rather than open
        }
    }

    // Mild consolidation pressure: favor bins below mean residual (relatively emptier).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Time-horizon modulation: early stream, be slightly more willing to fragment.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = norm_pr * (1.0 + 3.0 * t * t) - norm_pr * norm_pr * (2.0 + 4.0 * t);
    score += 20.0 * coupling;

    // Smooth penalty for large wasted residual that grows with progress
    score += 15.0 * norm_pr * norm_pr * (0.5 + t);

    // Reward tight fits smoothly
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (1.0 + t);

    // Last-chance bonus (smooth sigmoid-like weight)
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (0.5 + 0.5 * t);

    // Lookahead: reward bins whose post residual matches next item smoothly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.3 * diff * (1.0 + t);
        score -= 5.0 * (1.0 - (diff / cap).min(1.0)) * t;
    }

    // Mild pressure to prefer existing bins over new ones as stream progresses
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * t + 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins deviating favorably from mean residual
    score += 0.2 * (mean_residual - pr) * (0.5 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by small
    // moduli are more reusable by typical item sizes.
    let pr = post_residual as i64;
    let mut reuse_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { reuse_bonus += 6.0; }
        else if pr % 5 == 0 { reuse_bonus += 3.0; }
        if pr % 4 == 0 { reuse_bonus += 1.5; }
        if pr % 20 == 0 { reuse_bonus += 3.0; }
        // Tiny dead space (<10) is nearly unusable: heavy penalty.
        if pr < 10 { reuse_bonus -= 12.0; }
        // Medium dead space is awkward too.
        else if pr < 20 { reuse_bonus -= 4.0; }
    } else {
        // Perfect fill is ideal.
        reuse_bonus += 15.0;
    }
    score -= reuse_bonus;

    // Lookahead: does the next item fit exactly / well into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nxt = next_item_size as f64;
            let fill_ratio = nxt / post_residual as f64;
            // Reward high fill of the leftover by the next item.
            score -= 8.0 * fill_ratio * fill_ratio;
            if post_residual == next_item_size {
                score -= 10.0; // chain fill: perfect
            }
        } else {
            // Next item won't fit here: penalize large wasted residuals
            // that are still below the next item's size.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // Prefer tighter existing bins when many bins are open (consolidation).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * tightness;

    // Penalize opening a brand-new bin when good fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + progress);
        // New bin only attractive if current residual is small/dead-space-like
        // or item barely fits elsewhere.
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        let bare_fit = if bin_residual - item_size < 5 { 1.0 } else { 0.0 };
        score += 20.0 - 10.0 * dead - 6.0 * bare_fit + 2.0 * pressure.min(10.0);
        // Empty-bin harmonic class: a fresh bin has residual 100 (mod 10 == 0),
        // but that should not earn the reuse bonus; neutralize via the base above.
    }

    // Mild preference to keep mean residual spread balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead space relative to capacity: penalize wasting more than half the residual
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Open bins pressure: discourage opening new bins when many bins are open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item almost fits but not quite, mild penalty for blocking
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Progress-based tuning: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - waste_frac);

    // Prefer bins with below-mean residual (tighter bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Perfect 2-step match: strong reward.
        if post_residual == next_item_size {
            score -= 80.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 40.0;
    }

    // Prefer bins whose residual is small relative to mean residual (good fill).
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Penalize leaving large unusable dead space relative to item scale.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless open bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 10.0;
        }
    }

    // Early in stream: mild preference to consolidate into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 {
        let dead = post_residual as f64;
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.35 };
        score += 8.0 * (1.0 - usable) * (dead / 100.0);
    }

    // Lookahead: bonus if next item fits exactly into post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strong penalty to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only when existing bins would leave bad dead space
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // bias: early stream -> open bins cheaply; late -> reuse
        score += 20.0 * (1.0 - progress) - 25.0 * (1.0 - pressure);
        if item_size > 60 {
            score -= 10.0; // big items go to fresh bins
        }
    }

    // Slight preference for bins below mean residual (balance residuals)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild penalty for accumulating too many open bins when item is small
    if item_size < 30 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic-ish penalty on wasted space, sharpened by stream progress
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Smooth non-linear coupling of post_residual with progress:
    // late in the stream, waste is costlier
    score += 8.0 * norm_post * norm_post * (0.5 + progress);

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            let gap = (nxt - post) / cap;
            score += 4.0 * gap * gap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 6.0 * progress;
    }

    // More fitting bins => less urgency; slight penalty for hogging a flexible bin
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Penalize opening a brand-new bin when open bins could fit (unless it's the only call)
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 5.0 + 3.0 * open.ln() + 10.0 * progress;
        // but if the item leaves a nice small residual in a fresh bin, soften
        score -= 3.0 * (1.0 - norm_post);
    }

    // Mean residual context: bins far from the mean residual get a mild nudge
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity fractions (C/4, C/3, C/2)
    let c4 = bin_capacity / 4;
    let c3 = bin_capacity / 3;
    let c2 = bin_capacity / 2;

    // Dead-space penalty: leftover too small to hold any plausible item (<=10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Leftover that only fits tiny items is semi-wasted
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward hitting harmonic sweet spots exactly: post_residual == C/4, C/3, C/2
    if post_residual == c4 || post_residual == c3 || post_residual == c2 {
        score -= 25.0;
    }
    // Near-harmonic classes via integer division thresholds
    let class = post_residual / c4; // 0..4 harmonic bucket
    score -= (class as f64) * 3.0;

    // Lookahead coupling: does next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item nests perfectly: strong reward, scaled by snugness
            let snug = (post_residual - next_item_size) as f64;
            score -= 20.0 - snug * 0.15;
            // exact modulo harmony: post_residual is a multiple of next size
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize more if residual is small waste
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / cap; // = 1 - item/C
        // good fit (small post_residual) -> allow new bin rarely; otherwise reject
        score += 40.0 + fit_quality * 120.0;
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 25.0;
    }

    // Mild pressure to consolidate: prefer bins tighter than the average residual
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are "dead" and should be penalized hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 60.0;
    }

    // Reward leaving residuals that could fit typical mid-size items.
    if post_residual >= 10 && post_residual <= 50 {
        score -= 8.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (1.0 - progress);
    }

    // Slight tie-break toward bins with tighter current residual.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual matches next item size exactly or closely.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 800.0; // perfect 2-chain: fill this bin with next item too
        } else if post_residual >= next_item_size {
            score -= 300.0 - gap * 1.5; // next item still fits here
        } else {
            score += gap * 2.0; // dead space that next item cannot use
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is below mean
    // (filling tighter-than-average bins first).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate handling: empty bin gets a penalty so we only open
    // a new bin when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 400.0;
        // But if item is huge relative to capacity, opening fresh is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 350.0;
    }

    // Penalize leaving small unusable slivers (1..10) that nothing can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Late in stream: be more conservative, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 30.0;

    // Many open bins: prefer consolidating into existing ones.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: quadratic bonus for small post-residual
    let tight = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 60.0 * tight;

    // Perfect fit gets a strong extra reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * (1.0 - t);
    }

    // Penalty when many bins compete: prefer the one where the item wastes least
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: reward leaving post_residual that can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to the next item
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Global state: when open bins are collectively loose, discourage spreading
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.5 * mean_gap;

    // New-bin candidate handling: penalize opening a new bin, but relax late
    // in the stream or when the item is large (poor fits elsewhere likely).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        new_bin_penalty -= 20.0 * t; // late stream: consolidation matters less
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 8.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 100.0; // no alternative
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild penalty for very small post-residuals that are still nonzero (fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: linear + quadratic in post residual
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer tight fills (penalize residual more); later, be more lenient.
    let tightness = 0.5 + 1.5 * (1.0 - progress) * (1.0 - progress);
    score *= tightness;

    // Cubic interaction: residual^3 scaled by progress to smooth late-stream behavior
    score += 8.0 * norm_pr.powi(3) * cap * (0.5 + progress);

    // Lookahead: reward leaving room for the next item (subtract if next item fits in post_residual)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            // smooth reward: perfect-lookahead fit gets strongest discount
            score -= 15.0 * (gap / cap) * (1.0 - (gap / cap - 0.5).abs().min(1.0));
        } else {
            // penalize near-miss: next item almost fits
            let miss = (-gap) / cap;
            score += 10.0 * (1.0 - miss.min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // Mean residual coupling: if this bin's residual is below the mean, it's a tighter fit -> reward
    let dev = (pr - mean_residual) / cap;
    score -= 6.0 * dev * (1.0 - dev * dev.abs().min(1.0));

    // Slight penalty for many open bins to encourage consolidation
    score += (open_bins_count as f64).sqrt() * 0.8;

    // New-bin candidate: penalize mildly unless residuals are all large
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / cap;
        score = cap * (0.9 - 0.4 * avg_pressure) + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "large" class (still usable for typical items) are penalized less;
    // bins leaving tiny unusable slivers are penalized heavily.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class via integer division: residual / 10 gives decile class 0..10
    let decile = post_residual / 10;
    match decile {
        0 => score += 30.0,            // sliver: dead space
        1 => score += 18.0,            // very tight leftover
        2 | 3 => score += 6.0,         // awkward mid class
        4 | 5 | 6 => score -= 4.0,     // sweet spot: fits small/medium items
        _ => score += 10.0,            // near-empty bin: wasteful placement
    }

    // Modulo-5 coupling: post_residual divisible by 5 aligns with common
    // item sizes, slightly favored.
    if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // how well next item fills the leftover
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 10.0 * fill;
        } else {
            // next item cannot use this residual: penalize generous leftovers
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if pressure < 0.25 && open_bins_count > 0 {
            score -= 8.0 * (0.25 - pressure) * 4.0;
        } else {
            score += 12.0 + 10.0 * progress;
        }
    }

    // Tight fit reward: near-perfect packing.
    if post_residual <= 3 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild preference for filling bins more than the average open bin.
    if bin_residual < bin_capacity {
        score -= (mean_residual - pr) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 {
        let dead = (post_residual as f64) / 20.0;
        score += dead * dead * 12.0;
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and encourage consolidating into existing ones.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize more as open_bins_count grows,
        // and when mean residual across open bins is still healthy.
        score += 25.0 * pressure + mean_residual * 0.4;
    } else {
        score -= 8.0 * pressure;
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.6;

    // Lookahead: if the next item fits the post-residual, reward this placement;
    // otherwise penalize creating a residual that wastes the next item's needs.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Early in the stream, be more willing to open bins (exploration);
    // later, consolidate more aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * progress;
        } else {
            score -= 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the post residual tightly matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits perfectly-ish here: strong reward.
            score -= 60.0 * (1.0 - match_gap / (bin_capacity as f64));
        } else {
            // Next item won't fit: penalize proportionally to the shortfall.
            score += 0.8 * (nxt - post_residual as f64);
        }
        // Extra coupling: if post residual is within a small window of next item, big bonus.
        if match_gap <= 5.0 {
            score -= 25.0;
        }
    }

    // Penalize leaving dead space far below the smallest useful item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are tighter; prefer them slightly.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when it enables a great future fit,
    // otherwise discourage spreading items across many bins.
    if bin_residual == bin_capacity {
        let base = 15.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) <= item_size as f64 {
            score = base - 10.0; // opening fresh bin pairs well with next item
        } else {
            score = base + post_residual as f64 * 0.1;
        }
    }

    // Mild stream-progression pressure: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = fitting_bins_count as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement
    let mut score = post;

    // Reward tight fits strongly (non-linear)
    score -= 30.0 * (1.0 - post / cap).powi(8);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the residual left here serve the next item?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            // residual can host next item: reward proportionally to how snugly
            let snug = 1.0 - (post - nx) / cap;
            score -= 12.0 * snug * snug;
        } else {
            // residual too small for next item: penalize dead space
            score += 6.0 * (post / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Scarcity pressure: when many bins but few can fit, prefer reusing
    if open_bins_count > 0 {
        let scarcity = 1.0 - fit / open_bins_count as f64;
        score -= 8.0 * scarcity;
    }

    // Global state: penalize placements that inflate mean residual divergence
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Time horizon: early on, be frugal (favor reuse); late, tolerate new bins
    let early = (1.0 - t).max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or when nothing fits well
        let poor_fit = fit > 0.0 && (post / cap) > 0.5;
        score -= 15.0 * early;
        if poor_fit && t < 0.5 {
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size as f64 <= cap - item_size as f64 {
            score -= 5.0; // fresh bin has room for the lookahead too
        }
    } else {
        // Reuse reward grows over time (consolidation)
        score -= 10.0 * (1.0 - early) * (bin_residual as f64 / cap);
    }

    // Mild penalty for leaving awkward residual bands (30..50 hard to fill)
    if post_residual >= 30 && post_residual <= 50 {
        score += 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear waste penalty: quadratic coupling of post_residual with progress
    let post_norm = post / cap;
    score += 12.0 * post_norm * post_norm * (0.5 + progress);

    // Perfect-fit reward (smooth, no hard threshold)
    let tight = 1.0 - post_norm;
    score -= 10.0 * tight * tight * tight;

    // Lookahead coupling: penalize residuals that don't help the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            // residual can host next item: mild reward scaled by how snugly next fits
            let snug = 1.0 - (post - nx) / cap;
            score -= 4.0 * snug * snug;
        } else {
            // dead space relative to lookahead
            score += 3.0 * ((nx - post) / cap) * (1.0 + progress);
        }
    }

    // New-bin candidate: penalize opening a bin unless it's genuinely needed
    if bin_residual == bin_capacity {
        score += 20.0 + 8.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count > 0 {
            // strongly discourage ignoring usable open bins
            score += 15.0 * (1.0 - post_norm);
        }
        // late in stream, prefer filling existing bins even more
        score += 10.0 * progress;
    } else {
        // last-chance bonus: if this is the only fitting bin, reward using it
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
        // mild preference for bins below mean residual (balance load)
        score += 0.05 * (post - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "friendly"
    // residue classes (multiples of 10 / 25) are more reusable later.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, always reward heavily
    } else {
        let class = pr % 10;
        if class == 0 {
            score -= 25.0; // decile-friendly residual
        } else if pr % 25 == 0 {
            score -= 18.0;
        } else if class <= 5 {
            score -= 6.0;
        } else {
            score += (10 - class) as f64 * 1.5; // penalize awkward leftovers
        }
        // Dead-space cliff: tiny unusable slivers are worthless
        if pr < 10 {
            score += 20.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            let slack_class = slack % 10;
            score -= 15.0;
            if slack_class == 0 { score -= 8.0; }
            if slack == 0 { score -= 20.0; } // chain of perfect fits
        } else {
            // next item won't fit here; residual becomes a lone fragment
            score += 8.0;
            if pr < next_item_size && pr < 10 { score += 12.0; }
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Tightness reward: filling most of the bin
    let fill = (bin_residual - pr) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Fraction-of-capacity harmonic thresholds on bin_residual
    let quarter = bin_capacity / 4;
    if bin_residual % quarter == 0 && pr > 0 {
        score += 3.0; // slight penalty: leaving a round number may be wasted
    }

    // Stream progression: early on, prefer consolidating into few bins;
    // later, allow opening fresh bins with clean residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive if open bins are crowded or fit is poor
        let crowded = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.05);
        score -= 5.0 + progress * 15.0;
        if mean_residual < 20.0 { score -= 10.0; }
        if item_size > 60 { score -= 10.0; } // big items deserve fresh space
        if crowded > 8.0 { score -= 5.0; }
    } else {
        // Mild penalty for many open bins to discourage sprawl
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Mean-residual coupling: if the fleet average residual is small,
    // conserve remaining space aggressively.
    if (mean_residual - pr as f64).abs() < 5.0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Next item fits with some slack left: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 1.5;
    }

    // Post-residual is dead space (too small for next item and tiny in absolute terms).
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 150.0;
    }

    // Prefer tight fits relative to mean residual: bin more filled than average is good.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when reasonable open bins exist, unless lookahead is perfect.
    if bin_residual == bin_capacity {
        let perfect = next_item_size > 0 && post_residual == next_item_size;
        if perfect {
            score -= 100.0;
        } else {
            score += 80.0 + (open_bins_count as f64).sqrt() * 20.0;
        }
    }

    // Early in stream: be more conservative, keep bins open for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    // Mild pull toward mean residual for balanced packing.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-exact fits strongly (non-linear).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize large post-residual dead space, worse when small absolute leftover.
    if post_residual > 0 {
        let waste = post_residual as f64;
        score += 0.4 * (waste * waste) / bin_capacity as f64;
        // Dead space that no plausible future item can use.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Lookahead coupling: reward bins whose leftover fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer the tightest, penalize casual spread.
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state: encourage filling existing bins when many are open.
    score += 1.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: only attractive late in the stream or when
    // current bins are badly fragmented (high mean residual with low fit).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 45.0;
        score -= 30.0 * progress * fragmentation;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin suits a large follow-up item
        }
        if item_size > 60 {
            score -= 10.0; // big items start fresh bins cheaply
        }
    }

    // Mild time-horizon modulation: early on, be conservative about
    // fragmenting bins (long stream ahead); later, exploit tight fits.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * 0.15 * post_residual as f64;
    score -= t * 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let poly = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += poly * 60.0;

    // Reward tight fits smoothly (low post residual).
    score -= (1.0 - prn) * (1.0 - prn) * 40.0;

    // Penalize dead space relative to mean residual, modulated by progress.
    score += (pr - mean_residual).abs() * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Lookahead: penalize leaving residual that barely fails next item.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) + 20 >= next_item_size {
        score += 25.0 * (1.0 - progress);
    }

    // New-bin candidate: mildly penalize opening a new bin, less so early.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
    }

    // Slight preference for fuller bins as stream progresses.
    score -= (item_size as f64 / bin_capacity as f64) * (10.0 + 20.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common
    // item granularities are more reusable, odd/prime-ish leftovers less so.
    let class_bonus = if post_residual == 0 {
        60.0 // perfect closure
    } else if post_residual % 10 == 0 {
        25.0
    } else if post_residual % 5 == 0 {
        15.0
    } else if post_residual % 2 == 0 {
        5.0
    } else {
        -6.0 // odd residue: likely dead space
    };
    score -= class_bonus;

    // Integer-division thresholds: prefer residuals in "usable bands".
    let band = post_residual / 20; // bands of 20 units
    score -= match band {
        0 => 12.0,           // 0..19: nearly full, good
        1 => 6.0,
        2 => 0.0,
        3 => -4.0,           // 60..79: awkward mid residual
        _ => 2.0,            // large leftover: wasteful placement
    } as f64;

    // Lookahead coupling: reward when next item fits the post-residual,
    // penalize when it almost fits (creating a near-miss trap).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - slack * 0.3;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 14.0; // near-miss: this bin becomes useless for next item
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave
    // a large, awkward residual and there is slack in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = if post_residual > 50 { 1.0 } else { 0.0 };
        score = 100.0 - awkward * 20.0 - progress * 10.0
            + (open_bins_count as f64) * 2.0;
    }

    // Mild pressure toward consolidating into few bins.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items >= 1, but realistically small gaps of < ~10 are near-wasted).
    // Penalize gaps in the "unusable band" super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0 * (20.0 - post_residual as f64);
    }

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // If a future item can exactly fill the remaining gap, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64;
        if (next_item_size as f64 - gap).abs() < 1.0 {
            score -= 35.0;
        } else if (next_item_size as u32) <= post_residual {
            // lookahead fits in the gap: mildly good
            score -= 8.0;
        } else {
            // lookahead cannot use this gap: dead space risk
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new one is cheaper so new bins stay competitive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 3.0;

    // New-bin candidate handling: only attractive when open bins are crowded
    // (high mean residual means little room overall) or nothing fits well.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        score = 40.0 + crowded * 30.0 + pressure * 2.0;
        if post_residual == 0 { score -= 60.0; }
        // late in the stream, prefer consolidating into open bins
        score += progress * 15.0;
    }

    // Tie-break toward bins with less residual overall (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits perfectly in post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // dead space: next item cannot use the leftover
            score += 80.0 + 2.0 * post_residual as f64;
        }
    }

    // Penalize creating tiny unusable slivers (<10)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: avoid wasting it on poor fits; but if it fits well, reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Prefer bins with residual below mean (tighter bins get filled first)
    score += (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 120.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on wasted residual, amplified by item size ratio.
        let waste = post_residual as f64 / bin_capacity as f64;
        let tightness = item_size as f64 / bin_residual as f64;
        score += 40.0 * waste * waste * (1.0 - tightness);
    }

    // Perfect pair with lookahead item: strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // If the next item could also fit after this placement, slight reward.
            let combo = post_residual - next_item_size;
            score -= 20.0 * (1.0 - combo as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a stranded small gap.
            score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize dumping small items into large-residual bins (fragmentation guard).
    if item_size < bin_residual / 3 && bin_residual > bin_capacity / 2 {
        score += 60.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // encourage consolidation into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln().max(1.0);
    if bin_residual < bin_capacity {
        score -= 10.0 * consolidation * (0.5 + progress);
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else {
            // Compare best achievable post-residual in open bins vs fresh bin.
            let best_gap = if post_residual < item_size { 0.0 } else { 1.0 };
            best_gap * (mean_residual / bin_capacity as f64)
        };
        let horizon = 1.0 - progress;
        score = 50.0 + 200.0 * (1.0 - desperation) * horizon - consolidation * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin keeps flexibility for the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;

    // Base: prefer small post_residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, waste tolerance is higher; late, penalize residual harder
    let prog_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 30.0 * norm_pr * norm_pr * (1.0 - progress) * (1.0 - progress);
    score -= 12.0 * norm_pr * prog_coupling * (1.0 - item);

    // Reward tight fits (post_residual near zero) smoothly
    score -= 20.0 * (1.0 - norm_pr).powi(6);

    // Lookahead: bonus if next item fits into the post residual
    if next > 0.0 && next <= pr {
        score -= 15.0 * (1.0 - (pr - next) / cap);
    }
    // Penalize if next item nearly fits but leaves a sliver
    if next > 0.0 && next > pr && next - pr <= 10.0 {
        score += 10.0 * (next - pr);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Contextual pressure: many open bins -> prefer filling existing ones
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= 8.0 * open_pressure * (1.0 - norm_pr);

    // Mean residual alignment: bins close to mean residual are safer targets
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: make empty bins less attractive unless residuals are bad
    if bin_residual == bin_capacity {
        score += 18.0 + 25.0 * (1.0 - open_pressure) - 10.0 * norm_pr.abs().min(1.0);
        // open a new bin early if item is large and mean residual is fragmented
        score -= 15.0 * item * (1.0 - mean_residual / cap).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: quantize into capacity fractions
    let frac = post / cap_f; // 0..1
    let class = (frac * 8.0).floor() as i64; // 0..7 harmonic band

    // Reward tight fits: bins whose post residual lands in low bands
    score -= (7 - class.min(7).max(0)) as f64 * 2.0;

    // Penalize dead space: residuals too small for the smallest item (1)
    // but awkward — use modulo structure: residuals ≡ small values mod 10 are dead zones
    let post_u = post_residual;
    let dead_zone = if post_u > 0 && post_u < 10 { 1.0 } else { 0.0 };
    score += dead_zone * 30.0;

    // Harmonic coupling with next item: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 25.0; // perfect harmonic division
        } else {
            score -= 12.0; // next item fits at all
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize if post residual is a near-miss dead space
        let gap = next_item_size as f64 - post;
        if gap > 0.0 && gap < 20.0 {
            score += gap * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current residuals are fragmented
    if bin_residual == bin_capacity {
        // opening a new bin: baseline cost, reduced when open bins are full-ish
        let pressure = mean_residual / cap_f;
        score = cap_f * 0.6 - pressure * 20.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item benefits from fresh bin
        }
        if fitting_bins_count <= 1 {
            score += 40.0; // don't abandon the last fitting bin
        }
    }

    // Slight preference for bins below mean residual (consolidate fullness)
    score += (mean_residual - post) * 0.3;

    // Stream progression: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - frac) * progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size
    // are permanently wasted. Penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 6.0 * (10 - post_residual) as f64;
    }

    // Perfect or near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // gap too small for next item: likely dead space
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * 1.5 * (0.5 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the mean (balanced packing),
    // unless this bin is much fuller than average (then favor it).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate: only attractive if no open bin fits well
    // (i.e., item barely fits elsewhere or many bins compete poorly).
    if bin_residual == bin_capacity {
        let baseline = item_size as f64 + 10.0 + pressure * 0.5;
        if fitting_bins_count == 0 {
            score = -100.0; // no alternative: must open new bin
        } else if item_size > 60 {
            // Large items: opening fresh is often fine
            score = baseline - 20.0;
        } else {
            score = baseline; // prefer existing bins for small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with quadratic penalty.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: strongly reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 40.0; // perfect chain: this bin is ideal for the next item
        } else if post >= nxt {
            let slack = post - nxt;
            // reward leaving room for next item, decaying with slack
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            // penalize awkward leftover after next item too
            score += 0.03 * (post - nxt).powi(2) / bin_capacity as f64;
        } else {
            // next item won't fit here; penalize small unusable leftovers
            let waste = post;
            if waste < 10.0 {
                score += 25.0; // dead space below minimum item size
            }
            score += 8.0 * (1.0 - waste / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious; prefer using loose bins.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev; // bins with residual > mean get favored (dev negative -> subtract)

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // penalize opening a new bin mildly; stronger if other bins fit
        score += 12.0;
        if fitting_bins_count > 0 {
            score += 10.0 + 3.0 * fitting_bins_count as f64;
        }
        // early in the stream, opening bins is cheaper (more future to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling nearly-full bins completely.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Mild preference to keep number of open bins in check.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to ever be useful for typical items.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post) / 10.0;
    }

    // Lookahead: if the next item fits into the post residual, the leftover is valuable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            // residual can't host next item; mild penalty scaled by how close it is
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread = (mean_residual - post).abs();
        score += 15.0 + 3.0 * openness * (1.0 - progress) + spread * 0.2;
        // If the current bin would leave a very poor fit, allow the new bin to win.
        if fill_ratio < 0.35 && post < 40.0 {
            score -= 35.0;
        }
    }

    // Global state coupling: prefer placing into bins whose residual deviates from mean
    // (reduce variance across open bins, consolidating usable space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Early stream: be slightly more selective (many future items), late stream: pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;

    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + progress);
    score += 40.0 * poly;

    // reward tight fits, more so later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 60.0 * tightness * (0.3 + progress);

    // penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            score -= 5.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // discourage scattering across many bins when residuals are large
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - norm_item);

    // align with mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // new-bin candidate penalty: prefer existing bins unless residual is hopeless
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" fill targets
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Modulo classes: residuals divisible by 8 or 10 are more reusable
    if post_residual % 10 == 0 {
        score -= 30.0;
    } else if post_residual % 8 == 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 8.0;
    }

    // Integer-division thresholds: post_residual in (0,10] vs (10,25] vs larger
    let pr_class = post_residual / 10; // 0..10
    score += pr_class as f64 * 12.0;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // fraction of post_residual consumed by next item
            let frac = next_item_size as f64 / pr.max(1.0);
            score -= 60.0 * frac;
        } else {
            // next item cannot fit here: penalize leaving medium dead space
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score += 400.0 - 200.0 * item_frac;
        // prefer new bin if current bin residual would be tiny dead space anyway
        if post_residual >= 0 && item_frac > 0.7 {
            score -= 250.0;
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * fill;

    // Mean residual coupling: if this bin is far below mean residual, it's a good dump
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 40.0 * dev;

    // Progress: early in stream, be pickier (higher score for loose fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        // Tiny gap: waste. Penalize proportionally to how close to zero.
        score += (dead_threshold - post_residual as f64) * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Mid-range residuals (10..=20) are also poor: few future items fit.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Open-bins pressure: prefer keeping number of open bins low,
    // penalize the new-bin candidate when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + 4.0 * (open_bins_count as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item would be blocked by post residual, penalize small leftovers.
    if next_item_size > post_residual && post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 10.0;
    }

    // Mild pressure to consolidate into already-crowded bins.
    score += 0.05 * (open_bins_count as f64);

    // Slight preference for tighter fits overall (residual tightness coupling).
    score += 0.1 * (post_residual as f64 - mean_residual).max(-20.0).min(20.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-perfect fit bonus (dead space <= 5)
    if post_residual > 0 && post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 800.0;
    }
    // Next item fits into post_residual: moderate reward scaled by tightness
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 2.0;
    }
    // Next item would NOT fit here: mild penalty proportional to wasted lookahead
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits relative to mean residual (bin more packed than average)
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 1.5;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening alternatives
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if no open bin fits tightly, new bin becomes attractive
        if post_residual < (bin_capacity - item_size) {
            score -= 0.0;
        }
        // Late in stream, opening new bins is cheaper than fragmenting
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score -= 30.0;
        }
    }

    // Prefer filling nearly-full bins: reward small bin_residual before placement
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Slight penalty for spreading across many bins with large residuals
    if open_bins_count > 10 && post_residual > 40 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit refinement: reward tight fits nonlinearly
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize opening unless it's genuinely useful
    if bin_residual == bin_capacity {
        score += 25.0;
        // If no open bin fits tightly, opening a fresh bin is fine
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 35.0;
        } else {
            score += slack as f64 * 0.3;
        }
    }
    // If next item is too big for post-residual but would fit a fresh bin, mild penalty
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Time horizon: late in the stream, be more conservative (prefer reusing bins)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 6.0;
    }

    // Penalize leaving residuals that are unusable for typical items (small dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post residual.
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        - 30.0 * norm_pr * norm_pr * norm_pr;

    // Smooth stream-progress coupling: later in the stream, tolerate larger residuals less.
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Penalize residuals that cannot fit a typical next item (non-linear in mean residual gap).
    let gap = mean_residual - pr;
    score += 0.05 * gap * gap / (1.0 + mean_residual);

    // Lookahead: reward leaving space for the next item (smooth quadratic reward).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack = (pr - ns) / cap;
            score -= 20.0 * (1.0 - slack * slack);
        } else {
            let miss = (ns - pr) / cap;
            score += 25.0 * miss * miss;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when fits are poor,
    // with penalty decaying smoothly as the stream progresses.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - 0.5 * progress);
    }

    // Slight penalty for proliferating bins early.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that pair well with
    // common item sizes (multiples of 5, 10, 20) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward post-residuals divisible by small harmonic steps (5, 10, 20).
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    } else {
        // Awkward residual: dead space penalty grows with how far from a
        // multiple of 5 we land.
        let dist = (5 - (post_residual % 5)) as f64;
        score += 2.0 * dist;
    }

    // Perfect fit is king.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let left_after_next = post_residual - next_item_size;
            // Harmonic class of the double-fill remainder.
            if left_after_next % 10 == 0 {
                score -= 10.0;
            } else if left_after_next % 5 == 0 {
                score -= 4.0;
            } else {
                score += (5 - (left_after_next % 5)) as f64;
            }
        } else {
            // Next item won't fit here: penalize slightly less if residual
            // is still a "harmonic" value another future item could use.
            if post_residual % 10 == 0 {
                score += 3.0;
            } else {
                score += 6.0;
            }
        }
    }

    // Integer-division thresholds on post_residual: classify residual size bands.
    let band = post_residual / 20; // 0..5
    score += match band {
        0 => 0.0,          // tiny leftover, fine
        1 => -1.0,         // 20-39: usable
        2 => -2.5,         // 40-59: sweet spot
        3 => -2.0,         // 60-79
        _ => -1.0,         // 80+: nearly empty bin, low value to consume
    };

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // rather than opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // spread across open bins. Penalize the fresh bin proportionally to
    // open bins and mean residual, unless current fit is hopeless.
    if bin_residual == bin_capacity {
        let waste = mean_residual * (open_bins_count as f64).min(6.0);
        score += 15.0 + waste * 0.5;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    } else {
        // Filling an existing bin is generally good; scale by fullness fraction.
        let fullness = 1.0 - (bin_residual as f64) / cap;
        score -= 4.0 * fullness;
    }

    // Tight-fit bonus: item consumes most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 6.0;
    } else if fill_ratio < 0.3 {
        score += 3.0;
    }

    // Coupling: many open bins with high mean residual -> prefer consolidating
    // into existing bins, avoid leaving many partially filled bins.
    if open_bins_count > 3 && mean_residual > 25.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual < 10u32 {
        score += 60.0;
    } else if post_residual < 20u32 {
        score += 25.0;
    } else if post_residual <= 30u32 {
        // Usable small gap only if a small item may follow.
        if next_item_size > post_residual {
            score += 18.0;
        } else {
            score -= 15.0;
        }
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits the post residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + progress * 2.0);

    // Prefer bins whose residual is below the mean (tighter bins) when fitting.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: penalize mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // accommodates the next item (perfect chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item chain fill
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight chain fits, decay quadratically with slack.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // Next item won't fit here: penalize proportionally to leftover waste.
            score += 8.0 * (next_item_size - post_residual) as f64 / item_size.max(1) as f64;
        }
    } else {
        // Last item: strongly prefer minimal post residual.
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += 0.5 * (post_residual as f64 - mean_residual).max(-30.0).min(30.0);

    // Last-chance bin: big reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving tiny unusable slivers (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when no good chain fit exists
    // (i.e. mean residual is small / item is large relative to residuals).
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / bin_capacity as f64)
            * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        score += 10.0 + 30.0 * (1.0 - pressure);
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            // Fresh bin can host a perfect pair: mild discount.
            score -= 12.0;
        }
    }

    // Early stream: be slightly conservative with open-bin usage to build structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale dead space by relative fill.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize very small unusable post residuals (dead space) unless near zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to leftover.
            score += 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Time horizon: later in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> encourage consolidation.
    let mean_gap = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score += 15.0 * mean_gap;

    // Favor bins that are already well filled when many bins are open.
    score -= 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * fill_ratio;

    // New-bin candidate: make it attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        // Baseline moderate score; poor fits elsewhere will beat it.
        score = bin_capacity as f64 * 0.55 - 30.0 * fill_ratio;
        if fitting_bins_count <= 1 {
            score -= 40.0; // no real alternative anyway
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_norm = item_size as f64 / cap;            // 0..1
    let res_norm = post / cap;                        // 0..1
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_res_norm = mean_residual / cap;

    // Base: prefer small post residual (tight fit), non-linearly.
    let mut score = post * (1.0 + 2.0 * res_norm * res_norm);

    // Smooth penalty for leaving awkward mid-range dead space (neither tiny nor large).
    let awkward = 4.0 * res_norm * (1.0 - res_norm); // peaks at 0.5 residual
    score += 12.0 * awkward;

    // Stream-progress coupling: early on, keep flexibility (favor larger residuals slightly);
    // later, tighten aggressively since future demand is diminishing.
    let urgency = progress * progress;
    score -= 8.0 * urgency * fit_norm;                // later: reward big items into tight bins
    score += 6.0 * (1.0 - urgency) * res_norm;        // early: mild penalty on consuming bins

    // Lookahead: reward bins whose post residual can host the next item; penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 10.0 * (1.0 - 4.0 * slack * slack).max(0.0); // best when next item fills exactly
        } else {
            let miss = (nxt - post) / cap;
            score += 6.0 * (1.0 - miss).min(1.0);     // penalize just-barely-unusable residual
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a bin unless existing options are poor.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let pressure = (fitting_bins_count as f64).max(1.0);
        let mean_tight = 1.0 - mean_res_norm; // high when open bins are nearly full
        score += 25.0 + 10.0 * pressure.sqrt() - 20.0 * mean_tight * mean_tight;
        // Late stream: opening fresh bins is less costly than scattering.
        score -= 10.0 * urgency;
    } else {
        // Mild diversity term: many open bins with high mean residual -> prefer filling emptier bins.
        score -= 3.0 * (mean_res_norm - res_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residues modulo 10 as dead-space classes.
    let residue_class = post_residual % 10;
    // Residues near 0 (tight fit) are good; mid-range residues (4..6) are worst dead space.
    let residue_penalty = match residue_class {
        0 => -8.0,
        1 | 9 => -4.0,
        2 | 8 => -1.0,
        3 | 7 => 1.5,
        4 | 6 => 4.0,
        _ => 5.0,
    };
    score += residue_penalty;

    // Integer-division threshold on post_residual: small remainders are "harmonically usable".
    let q = post_residual / 10;
    if q <= 1 {
        score -= 6.0; // post residual <= 19 is nearly dead space anyway, but small is fine
    } else if q <= 4 {
        score += 2.0 * (q as f64 - 1.0);
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * fill;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) % 10;
            score -= 8.0 - 0.5 * slack as f64;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 3.0 * (next_item_size as f64 - post) / cap;
        }
    } else {
        // last item: just minimize waste
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // more competition: mild normalization toward best fit
        score += 0.5 * (fitting_bins_count as f64).min(5.0);
    }

    // New-bin candidate handling: empty bin should only win when current bin fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9;
        // cheaper to open early in stream (many items left to fill it)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 20.0 * (1.0 - progress);
        // if next item is large, a fresh bin is more attractive
        score -= 0.15 * next_item_size as f64;
        // many open bins with mean residual already low: opening new bin is fine
        score -= 2.0 * mean_residual / cap;
    } else {
        // existing bin: slight preference when its residual is far from mean (unusual bin gets used)
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Discourage leaving bins with many open bins and tiny residuals scattered
    if open_bins_count > 6 && post < 10.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0; // leaving a tiny unusable sliver is very bad
    }
    // Perfect fit is extremely rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0; // near-perfect fit still strongly favored
    }

    // Non-linear penalty on large leftover gaps that no typical item can use well:
    // penalize gaps in the awkward mid-range (e.g., 51..70) where few items fit.
    let pr = post_residual as f64;
    if pr > 50.0 && pr < 70.0 {
        score += 10.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins; opening new bins is penalized via the new-bin candidate.
    let bin_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when nothing fits well.
        score += 25.0 + bin_pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a bin.
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 6.0; // blocking the next item is mildly bad
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., tighter bins), encouraging balanced closing of bins.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.5;

    // Slight early-stream aggression: open bins early when stream is young.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled by progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity as f64 - post_residual as f64) * 0.6;

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (bin_capacity as f64 - gap) * 0.35;
        // Perfect 2-step chain: huge reward.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize leaving residual that nothing useful can use later.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Compare against mean residual: penalize bins far from mean (keeps spread tight).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when few bins fit or residual is tiny everywhere.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin can chain with next item
        }
        if fitting_bins_count > 1 {
            score += 25.0; // discourage opening when alternatives exist
        }
        if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Slight preference to fill older/more crowded bin sets as stream progresses.
    score -= progress * (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but exact fits are golden.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward; if this
    // placement would block the next item while another bin could take it, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 55.0;
        }
    }

    // New-bin candidate logic: an empty bin should only win when fits are poor
    // or the stream is early with plenty of future demand.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_pressure = fitting_bins_count as f64;
        // Penalize opening new bins when decent alternatives exist.
        score += 30.0 / fit_pressure.max(1.0);
        // Slightly cheaper to open new bins early in the stream.
        score -= 15.0 * (1.0 - progress);
        // If the item fits this empty bin perfectly, it is a fine new bin.
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Global state coupling: spread load when many bins are open with large mean residual.
    if open_bins_count > 0 {
        let residual_gap = mean_residual - bin_residual as f64;
        score += 0.15 * residual_gap;
    }

    // Mild time-horizon term: late in the stream, prefer consolidating into
    // existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize leftover space, with non-linear (quadratic) shaping.
    let mut score = x * (1.0 + 0.8 * x);

    // Smooth stream-progress coupling: later in the stream, waste matters more.
    let progress_coupling = t * t * x * (1.0 - x) * 4.0;
    score += 1.5 * progress_coupling;

    // Reward tight fits: smooth bump when post_residual is small.
    let tightness = (1.0 - x).powi(3);
    score -= 3.0 * tightness;

    // Lookahead: if next item fits the post-residual, strongly reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0);
        let next_util = nx / (pr + 1.0);
        if pr as u32 >= next_item_size {
            score -= 2.0 * next_util * (1.0 - fits_next / cap);
        } else {
            score += 0.5 * (1.0 - nx / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - x);
    }

    // Penalize fragmentation relative to mean residual of open bins.
    score += 0.3 * (pr - mean_residual) / cap;

    // Mild penalty for proliferating bins.
    score += 0.05 * open_bins_count as f64 * x;

    // New-bin candidate adjustment: opening a new bin is attractive only early
    // in the stream or when this placement would leave very poor residual.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (0.6 + 1.2 * t * (1.0 - tightness)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // chunks (25/20/10) are more reusable by future items.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: ideal
    } else {
        if pr % 25 == 0 { score -= 18.0; }
        else if pr % 20 == 0 { score -= 14.0; }
        else if pr % 10 == 0 { score -= 9.0; }
        if pr % 5 == 0 { score -= 3.0; }
        // Very small dead space (< 10, below min item size) is wasted
        if pr < 10 { score += 25.0; }
        else if pr <= 15 { score += 8.0; }
    }

    // Capacity-fraction coupling: reward leaving room for common fractions
    let frac = pr as f64 / bin_capacity as f64;
    score -= 12.0 * frac; // prefer bins with more remaining space generally

    // Lookahead: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of the two-step leftover
            let left = pr - next_item_size;
            if left == 0 { score -= 30.0; }
            else if left % 10 == 0 { score -= 10.0; }
            else if left < 10 { score += 15.0; }
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 10.0 + 0.15 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }
    // Many fitting bins: mild penalty so we keep diverse residuals
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Stream progression: late in the stream, prefer tight packing / closing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual == bin_capacity) as u32 as f64 * -1.0;
    // Late stream: discourage opening new bins
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
        // unless many bins already open and mean residual is high (fragmentation)
        if mean_residual > 30.0 && open_bins_count > 3 {
            score += 10.0;
        }
    }

    // Tie-break toward bins close to mean residual (balance fragmentation)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Reward using a tight fit relative to bin contents
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln() * 2.0 * (0.5 + progress);

    // Lookahead: if next item fits into post_residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If post_residual is small but nonzero and next item can't use it, penalize more
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate handling: only attractive late in stream or when fits are bad
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if post_residual > 50 { 0.0 } else { 0.0 };
        let _ = bad_fit_penalty;
        // base cost of opening a new bin, reduced when open bins are crowded
        score = bin_capacity as f64 - 30.0
            + (open_bins_count as f64) * 1.5
            - 25.0 * (1.0 - progress);
        // make new bin less attractive than a decent existing fit
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // if next item is large and this item small, new bin may be smart
        if next_item_size > item_size + 20 {
            score -= 15.0;
        }
    }

    // Slight preference for bins below mean residual (balancing)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small post-residual is good; non-linear bonus.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 50.0 * tightness * tightness;

        // 2-step lookahead: if next item fits exactly into post_residual, big reward.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 400.0;
            } else if post_residual >= next_item_size {
                // next item fits, but penalize leftover slack after it too.
                let after = post_residual - next_item_size;
                score -= 100.0 - (after as f64) * 0.5;
            } else {
                // next item cannot use this residual: penalize dead space, worse if residual is small.
                score += (next_item_size - post_residual) as f64 * 0.6;
            }
        }

        // Relative to mean residual: bins with below-average residual (tighter) preferred.
        score += (mean_residual - post_residual as f64) * 0.3;

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 150.0;
        }

        // Prefer reusing bins over opening new ones when many bins open.
        score -= open_bins_count as f64 * 0.5;
    }

    // New-bin candidate: discourage unless current open bins are all poor fits.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { (next_item_size as f64 / bin_capacity as f64) * 20.0 } else { 0.0 };
        score += 80.0 - pressure;
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing else fits: new bin is necessary
        }
    }

    // Mild stream-progression scaling: tighten packing late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: post-residual that is too small to be useful later
    // (smaller than the minimum plausible item) is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into the post-residual,
    // penalize if post-residual is "almost but not quite" fitting the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.25 * (item_size as f64);
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer opening
    // a new bin only when no open bin offers a decent fit (large post_residual waste
    // in the best existing bin) or when the item is large relative to residuals.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins; grows with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 15.0 * progress;

        // If open bins exist but their mean residual barely fits the item,
        // opening fresh space is more attractive.
        if open_bins_count > 0 {
            let slack = mean_residual - item_size as f64;
            if slack < 5.0 {
                score -= 18.0;
            }
        } else {
            score -= 40.0; // no open bins: must open one
        }

        // Large items benefit from a fresh bin early (leave small bins for small items).
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate: prefer bins whose residual deviates below the mean
    // (i.e., more filled bins get priority, keeping emptier bins for future items).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Prefer using bins with more competition for their space.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let r = post_residual as f64 / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Smooth non-linear waste penalty: dead space grows quadratically near-full
    score += 12.0 * r * r * (1.0 - r);

    // Tight-fit reward, strongest mid-stream
    score -= 20.0 * fit_ratio * fit_ratio * (0.5 + 0.5 * progress);

    // Late stream: prefer filling existing bins over opening new ones
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (8.0 + 14.0 * progress * progress);

    // Last-chance bonus: only one bin can fit this item
    if fitting_bins_count == 1 && new_bin < 0.5 {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead: reward leaving space the next item can use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            let slack = (post_residual as f64 - nx) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 4.0 * progress;
        }
    }

    // Penalize bins far from mean residual (fragmentation)
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Mild penalty for many open bins
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: residuals that are multiples
    // of 10 are "usable" slots for typical item sizes; penalize odd residues.
    let post_mod = post_residual % 10;
    score -= if post_mod == 0 { 8.0 } else if post_mod == 5 { 3.0 } else { -(post_mod as f64) * 0.5 };

    // Fraction-of-capacity classes: residual in [1..25] small, (25..50] mid, (50..75] large
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac <= 0.25 {
        score -= 5.0; // near-full bin, good packing
    } else if frac <= 0.5 {
        score -= 1.0;
    } else {
        score += 3.0; // leaving a big hole is bad unless a big item follows
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) % 10;
            score -= 6.0 - slack as f64 * 0.4;
        } else {
            // next item won't fit here; reward compactness more
            score -= 2.0;
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when few bins fit the item
    // and mean residual across open bins is large (fragmentation is high).
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let pressure = (fitting_bins_count as f64).max(1.0);
        score = 100.0 - frag * 30.0 - 10.0 / pressure - (post_residual as f64) * 0.1;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0; // big item coming, fresh bin useful
        }
    }

    // Mild progression term: later in stream, be greedier about filling bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10) are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (post_residual near zero but not dead).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Perfect-fit lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // New-bin candidate: baseline above using an existing bin.
        score += 45.0 + 2.0 * open_bins_count as f64;
        // But if the item fits poorly anywhere else (large dead space), new bin is fine.
        if post_residual as f64 > 0.0 && item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 30.0;
        }
    }

    // Mild coupling with mean residual: prefer bins whose residual is below mean
    // (concentrate filling in emptier bins is bad; fill fuller bins first).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // Late-stream urgency: as stream progresses, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the leftover relative to capacity, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 0.6 * (1.0 - tightness * tightness) * (item_size as f64);

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer chains where the next item also fits snugly.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // Extra reward if the chain nearly exhausts the bin.
            if post_residual == next_item_size {
                score -= 35.0;
            }
        } else {
            // Penalize leaving a fragment too small for the next item (dead space).
            let frag = post_residual as f64;
            score += 0.5 * frag + 10.0;
        }
    }

    // Compare against mean residual: prefer bins with less residual than average
    // (fill the emptiest-fitting bins first keeps many usable bins alive).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Late in the stream: consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when existing bins would leave bad fragments.
    if bin_residual == bin_capacity {
        // Base penalty discourages opening bins unnecessarily.
        score += 30.0;
        // But if the item is large, a fresh bin is fine.
        if item_size >= 70 {
            score -= 25.0;
        }
        // If no open bin leaves a usable remainder for the next item, allow a new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
        // If next item fits current residual but not post-residual, penalize wasting it.
        if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        let poor_options = (item_size as f64 / bin_capacity as f64) > 0.8;
        score += 35.0 * avg_fit; // base cost of opening a bin
        if poor_options {
            score -= 45.0;
        }
        if mean_residual > 0.0 && mean_residual < item_size as f64 * 0.5 && fitting_bins_count > 0 {
            score -= 20.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer fuller bins relative to the fleet average.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit = item_size as f64 / cap;

    // Smooth non-linear coupling: penalize residuals that are hard to fill later,
    // weighted by stream progress (later => less time to recover dead space).
    let deadness = (pr / cap).powi(2) * (pr / cap);
    score += 60.0 * deadness * (0.5 + t);

    // Reward tight fits with a smooth saturating term.
    let tightness = 1.0 - (pr / cap);
    score -= 25.0 * tightness * tightness * (1.0 - t * 0.5);

    // Coupling with mean residual: prefer bins near the mean (balance residuals),
    // using a smooth quadratic interaction with progress.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev * (0.3 + 0.7 * t);

    // Lookahead: bonus if post residual can host next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = (pr - nx).max(0.0) / cap;
        score -= 12.0 * (1.0 - (pr / nx).powf(-1.0).min(1.0)) * (1.0 - room);
        score += 8.0 * room * t;
    }

    // Last-chance bin: smooth urgency term.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - t * 0.3);
    }

    // Mild pressure to consolidate into fewer bins as stream advances.
    score += 0.5 * open_bins_count as f64 * (t * t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual) with a non-linear curve.
    let fit_ratio = post_residual as f64 / cap; // 0..1 fraction of dead space
    score += fit_ratio * fit_ratio * 40.0;

    // Harmonic class of post_residual: dead space below smallest item (1..10) is worthless.
    if post_residual < 10 {
        score -= 25.0; // near-perfect closure
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual <= 30 {
        score += 4.0;
    }

    // Integer-division harmonic classes: post_residual in coarse deciles.
    let decile = post_residual / 10;
    match decile {
        0 => score -= 6.0,
        1 => score -= 2.0,
        2 => score += 0.0,
        3 => score += 3.0,
        4 => score += 5.0,
        _ => {}
    }

    // Lookahead: if next item exactly fills post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Slack after the lookahead placement.
            let next_slack = post_residual - next_item_size;
            score += next_slack as f64 * 0.5;
            if next_slack < 10 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: penalize by the shortfall modulo class.
            let shortfall = next_item_size - post_residual;
            if shortfall <= 15 {
                score += 6.0;
            } else {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if post_residual <= 20 {
            score -= 12.0;
        }
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when all fits are bad.
    if bin_residual == bin_capacity {
        // New bin score = dead space of placing item alone, plus a mild inertia penalty
        // so open bins with decent fits win, but terrible fits (post_residual > 40)
        // lose to the fresh bin.
        score = item_size as f64 + 5.0;
        if post_residual > 40 {
            score -= 20.0; // make new bin attractive vs. awful fits
        }
        if open_bins_count == 0 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 5.0;
        }
    }

    // Mild penalty for scattering across many open bins when mean residual is high.
    if open_bins_count > 4 && mean_residual > 50.0 && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (strict dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item cannot fit in the post-residual, penalize.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    } else if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0; // enables a chain of perfect fits
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate bias: only attractive when it leaves a large,
    // reusable residual (i.e., current item is small relative to capacity).
    if bin_residual == bin_capacity {
        score -= (post_residual as f64) * 0.4 - 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Two-step lookahead: if the next item fits exactly into the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 500.0;
        } else if post >= nxt && post - nxt <= 10.0 {
            score -= 120.0;
        } else if post < nxt && post >= nxt * 0.5 {
            // residual large enough to be split-friendly but not reusable by next item
            score += 40.0;
        } else if post > 0.0 && post < nxt {
            // dead-ish space relative to lookahead
            score += 25.0 * (1.0 - post / 100.0);
        }
    }

    // Compare against mean residual: bins tighter than average are better targets
    // for large items; loose bins should absorb small items.
    let post_f = post_residual as f64;
    let dev = post_f - mean_residual;
    if dev < 0.0 {
        score -= 0.8 * dev.abs();
    } else {
        score += 0.4 * dev;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // unless the stream is early and many bins will be needed anyway.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_f = item_size as f64;
        // A fresh bin is attractive only if the item leaves a very tight fit
        // (residual near a typical small-item size) or few fitting bins exist.
        let tightness = (post_f - 20.0).abs();
        score += 80.0; // base penalty for opening a new bin
        score -= (100.0 - tightness).max(0.0) * 0.5;
        score -= 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // discourage fresh bin if item is small (waste of a full bin)
        score += (80.0 - item_f).max(0.0) * 1.5;
    }

    // Slight preference for tighter bins overall.
    score += 0.3 * (bin_capacity - bin_residual) as f64 * -0.0; // no-op guard
    score += 0.2 * (bin_residual as f64 - post_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits in the post residual (chaining), penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that can fit, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits badly everywhere (large residual elsewhere / few fitting bins).
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // Base penalty for wasting a fresh bin.
        score += 55.0;
        // If many bins fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 30.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
        }
        // If mean residual is large, open bins have plenty of room -> penalize new bin more.
        score += mean_residual * 0.2;
        // Early in the stream, new bins are cheaper (future items may fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 35.0;
        // Large items relative to residual elsewhere favor a fresh bin.
        score -= (item_size as f64) * 0.1;
    } else {
        // Prefer filling more-loaded bins when many bins are open (bin count control).
        let load = (bin_capacity - bin_residual) as f64;
        score -= load * 0.05 * (open_bins_count as f64).ln().max(1.0);
    }

    // Slight preference for bins whose residual is close to the mean (stability).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit = item_size as f64 / cap;
    let nx = next_item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.6 * pr / cap);

    // Dead-space penalty grows non-linearly as post residual approaches unusable sizes
    let dead = (pr / cap).powi(3);
    score += 30.0 * dead;

    // Smooth interaction: progress reduces tolerance for large residuals late in stream
    score += pr * (0.5 + 1.5 * progress * progress);

    // Lookahead coupling: reward leaving room for the next item smoothly
    let room = nx - pr / cap;
    score -= 12.0 * (-8.0 * room * room).exp() * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild preference for consolidating into fewer bins
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: penalize opening a new bin unless residuals are all poor
    if bin_residual == bin_capacity {
        let avg_waste = (mean_residual / cap).powi(2);
        score += 18.0 - 15.0 * avg_waste;
    }

    // Small fit-efficiency reward
    score -= 8.0 * fit * fit;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes
    // Favor post_residuals that align with typical item size classes (divisible by 10/20/25/50).
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr == 0 {
        harmony_bonus -= 60.0; // perfect fit: excellent
    } else {
        if pr % 10 == 0 { harmony_bonus -= 18.0; }
        if pr % 20 == 0 { harmony_bonus -= 10.0; }
        if pr % 25 == 0 { harmony_bonus -= 12.0; }
        if pr % 50 == 0 { harmony_bonus -= 15.0; }
        // integer-division thresholds: small unusable slivers are bad
        if pr < 10 { harmony_bonus += 55.0; }        // dead space below min item size
        else if pr < 20 { harmony_bonus += 15.0; }
        else if pr < 30 { harmony_bonus += 5.0; }
    }
    score += harmony_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack % 10 == 0 { score -= 12.0; }
            if slack < 10 { score += 20.0; }
        }
        // harmonic pairing: item + next_item complement to capacity
        if item_size + next_item_size == bin_capacity && bin_residual == bin_capacity {
            score -= 40.0;
        }
    }

    // New-bin candidate handling: only prefer fresh bin when existing fits are poor
    if bin_residual == bin_capacity {
        // opening a new bin: penalize mildly, more when many bins open or many fit
        score += 30.0 + 3.0 * fitting_bins_count as f64;
        if fitting_bins_count == 0 { score -= 100.0; } // must open anyway
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    } else if fitting_bins_count == 1 {
        // last chance bin: strong reward to use it
        score -= 45.0;
    }

    // Mean residual coupling: prefer bins tighter than the mean (good fill)
    let diff = mean_residual - bin_residual as f64;
    score += 0.35 * diff;

    // Slight preference for fuller bins overall
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    // Modulo-class penalty: post_residual in awkward classes (e.g. 7, 13-like primes mod 100)
    if pr > 0 && pr % 10 != 0 && pr % 25 != 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space (smaller than the minimum item size 10... but
            // items can be 1..100, so scale the "dead zone" with item granularity).
            score += 40.0 * (1.0 - post_residual as f64 / 10.0);
        } else {
            // Larger leftover space is less painful; mild superlinear penalty.
            let r = post_residual as f64;
            score += 0.02 * r * r / (bin_capacity as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to the item size (wasting little of the bin).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += 2.5 * (open_bins_count as f64);

    // Mean residual coupling: bins far below mean residual are less attractive
    // (keep high-residual bins flexible? no — prefer filling low-residual bins
    // so they close out). Penalize bins whose residual is much larger than mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Next item cannot use the gap: extra dead-space penalty.
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists (i.e., item fits poorly anywhere).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, offset by stream progress
        // (late in the stream, opening bins is cheaper since fewer items remain).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 55.0 - 20.0 * progress;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            new_bin_score -= 12.0;
        }
        // If many bins can fit the item, opening a new one is wasteful.
        new_bin_score += 6.0 * (fitting_bins_count as f64);
        score = score.min(score) + 0.0; // keep score intact
        return new_bin_score + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to bin capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: next item seals this bin
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills the remainder
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 35.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // next item does NOT fit here: penalize leaving awkward gaps
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Compare residual against mean residual of open bins: prefer bins with less residual
    // (pack into fullest bins first, best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless the item is huge or no good fit exists
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's only chosen when open bins score badly
        score += 45.0;
        // If the next item is large and this bin would be nearly emptied now, opening is fine
        if next_item_size > 0 && post_residual + next_item_size >= bin_capacity {
            score -= 50.0;
        }
        // Early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for creating very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post-residuals below next item are bad.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * next_item_size as f64;
        } else if post_residual >= next_item_size {
            score -= 0.3 * next_item_size as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the fit
    // into existing bins would be terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 20.0 + 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            penalty = 0.0; // forced: must open new bin
        }
        if fit_ratio < 0.9 {
            penalty += 10.0 * (1.0 - fit_ratio);
        }
        score += penalty;
    }

    // Mild preference for bins with smaller residual than the mean (consolidation).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight preference for using bins that are already open vs. hoarding.
    score -= 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let shape = 1.0 + 0.8 * progress * progress - 0.3 * progress;
    score *= shape;

    // Penalize large dead space quadratically, stronger late in the stream
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward near-perfect fits (small post_residual) with a smooth decay
    score -= 6.0 * (-pr / 8.0).exp() * (1.0 + progress);

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 * (1.0 - (next_item_size as f64 / cap)) * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty when many bins are open and residual is wasted
    score += 0.05 * (open_bins_count as f64) * norm_pr;

    // Keep score bounded below to avoid pathological ties
    if score < 0.0 { score = 0.0; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // residue classes (divisible by common item sizes) are preferred.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { class_bonus += 6.0; }
        if pr % 20 == 0 { class_bonus += 4.0; }
        if pr % 25 == 0 { class_bonus += 3.0; }
        if pr % 5 == 0 { class_bonus += 1.5; }
    } else {
        class_bonus += 12.0; // perfect fill
    }
    score -= class_bonus;

    // Dead-space penalty: tiny unusable leftovers (1..10) are wasteful.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.0;
    }

    // Lookahead coupling: reward when next_item_size fits exactly or nearly
    // into post_residual; penalize when next item cannot use the leftover.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            score -= 8.0 * (1.0 - gap as f64 / bin_capacity as f64);
            if gap < 10 { score += 3.0; } // near-miss creates dead space
        } else {
            score += 2.0; // leftover too small for next item
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    // or mean residual is small; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let pressure = (mean_r / bin_capacity as f64).clamp(0.0, 1.0);
        let crowding = (open_bins_count as f64 / (step_index.max(1) as f64 + 1.0)).clamp(0.0, 1.0);
        let new_bin_bonus = 8.0 * (1.0 - pressure) * (1.0 - 0.5 * crowding);
        score += 4.0 - new_bin_bonus;
        if fitting_bins_count > 0 {
            score += 6.0; // extra penalty when open bins could still fit item
        }
    }

    // Progress-aware tightness: late in the stream, prefer tighter fills more
    // aggressively (less time to amortize partially-filled bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let nxt = next_item_size as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (1..9) are heavily penalized: they can never host
    // another item reliably, so punish proportionally to how "dead" they are.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 3.0;
    }
    // Reward exact and near-exact fits.
    if pr == 0.0 {
        score -= 25.0;
    } else if pr <= 5.0 {
        score -= 10.0;
    }

    // --- Lookahead coupling (k=2) ---
    // If the next item still fits in the resulting residual, this placement
    // keeps the bin alive: reward it.
    if nxt > 0.0 && nxt <= pr {
        score -= 8.0;
    } else if nxt > 0.0 {
        // Residual too small for the lookahead item: likely dead space,
        // mild penalty scaled by how much space is stranded.
        score += (pr / cap) * 6.0;
    }

    // --- Last-chance pressure ---
    // If this is the only open bin that can fit the item, using it avoids
    // opening a new bin: strong reward (but not for the new-bin candidate itself).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // --- Open-bin pressure against opening new bins ---
    if is_new_bin {
        let mut penalty = 12.0
            + open_bins_count as f64 * 1.5
            + progress * 10.0
            + mean_residual * 0.15;
        // Soften if the fresh bin can also host the lookahead item (chaining).
        if nxt > 0.0 && nxt <= pr {
            penalty -= 6.0;
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chain fits (post_residual == next_item_size)
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 0.5 {
            score -= 60.0; // exact 2-step match: fill this bin completely with next item
        } else if post_residual > next_item_size {
            // next item fits too: reward tightness of the chained fit
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item does NOT fit in residual: penalize dead space relative to lookahead
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins whose residual is close to the mean residual (keep bin pool homogeneous)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit, especially early/mid stream
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 30.0 * (1.0 - progress);
    }

    // Small bonus for consolidating into bins with less residual (tighter packing)
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powf(3.0);

    // Penalize dead space that cannot fit the average next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 20.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        } else if post_residual >= next_item_size {
            score -= 8.0; // bin stays useful for the lookahead item
        }
    } else {
        // Last item: prefer exact fill.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish, slightly penalized so we prefer
    // existing bins unless the fit is poor. Empty-bin residual == capacity.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.15 * open_bins_count as f64;
        // But if the current bin would leave a very tight fit anyway, allow new bin.
        if fit_ratio > 0.6 {
            score -= 12.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins (penalize new bins implicitly via fit).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * mean_residual * (1.0 - progress);

    // Slight preference for filling bins with larger residual earlier in stream.
    score += 0.02 * bin_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping over stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Smooth coupling: penalize residual scaled by progress (late waste costs more).
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits via smooth saturation of post_residual.
    score -= 8.0 * (-pr / (item_size.max(1) as f64)).exp();

    // Penalize if this bin can't also fit the next item (smooth lookahead term).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 4.0 * (gap / cap).min(1.0) * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for proliferating bins relative to stream progress.
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    // New-bin candidate: make it attractive only when residuals are poor.
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap).min(1.0);
        score -= 10.0 * avg_tightness * (0.3 + 0.7 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "useful"
    // residue class (multiples of 10, and small leftovers) are favored.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 10 == 0 {
        -12.0
    } else if pr < 10 {
        15.0 // dead space below min item size
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: leftovers divisible by
    // common item sizes are more likely reusable.
    if pr > 0 && pr % 20 == 0 {
        score -= 6.0;
    } else if pr > 0 && pr % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly
    // or nearly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // harmonic class of the slack after the next placement
            score -= if slack % 10 == 0 { 10.0 } else if slack < 10 { 2.0 } else { 5.0 };
        } else {
            score += 8.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or this bin's post placement would be wasteful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score -= 18.0 * congestion + 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Prefer tighter bins overall: penalize bins far above the mean residual
    // (they waste space) mildly, reward below-mean (tight) bins.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Small tie-breaker toward fuller bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100 range)
    // are pure waste; penalize unusable gaps quadratically.
    if post_residual < item_size.min(10).max(1) {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Penalize any residual that is smaller than the next item (lookahead dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward tight fits (low post_residual) super-linearly
    score += (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate
        score += 5.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // but if all open bins would leave big dead space, opening a new bin is fine
        if fitting_bins_count > 0 && (mean_residual - item_size as f64) > 30.0 {
            score -= 15.0;
        }
    } else {
        // mild preference for bins already below mean residual (consolidate emptier space)
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the leftover space exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Leftover can host the next item: mild reward proportional to tightness.
            score -= 50.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize wasted capacity.
            score += 40.0 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize small unusable fragments (dead space below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bin late in the stream when many bins are open and fits are scarce.
        if fitting_bins_count > 1 {
            score += 60.0;
        }
    }

    // Relative to mean residual: prefer bins that become tighter than average.
    score -= 20.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Mild penalty for spreading across many open bins.
    score += 2.0 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small to ever be useful for typical items,
    // but only mildly when it can still hold a small lookahead item.
    if post_residual > 0 {
        let usable = if next_item_size > 0 {
            (post_residual as f64) >= (next_item_size as f64)
        } else {
            true
        };
        if !usable {
            score += 8.0;
        }
        // Dead space penalty grows as post_residual approaches unusable mid-range.
        let dr = post_residual as f64 / bin_capacity as f64;
        if dr > 0.0 && dr < 0.15 {
            score += 6.0 * (0.15 - dr) / 0.15;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 4.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Time horizon: early in the stream, prefer keeping bins flexible (favor
    // balanced residuals); late in the stream, prioritize closing bins tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let horizon = (1.0 - t) * 5.0;
    // Reward residuals close to mean_residual early (flexibility), penalize
    // deviation late.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += horizon * (dev / bin_capacity as f64) * 4.0;
    score -= t * 5.0 * tight;

    // Many open bins: encourage filling existing ones rather than spreading out.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 3.0;

    // New-bin candidate: penalize opening a new bin unless current item is large
    // relative to residual or fits would be poor.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0;
        let big_item = (item_size as f64) > 0.7 * bin_capacity as f64;
        let lookahead_needs_space = next_item_size > 0 && (next_item_size as f64) > mean_residual;
        if !(poor_fit_everywhere || big_item || lookahead_needs_space) {
            score += 20.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pn = pr / cap; // normalized post residual in [0,1]
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks at 1 mid-stream
    score += 3.0 * pn * pn * (1.0 + prog_term) * cap * 0.1;

    // Reward near-perfect fits more strongly as stream advances.
    let tightness = 1.0 - pn;
    score -= tightness * tightness * (2.0 + 4.0 * progress) * 5.0;

    // Lookahead: reward bins whose post_residual matches next item exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
        // Penalize leaving post_residual that no future item can plausibly use.
        if next_item_size as f64 > pr {
            score += 2.0 * pn * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly, but allow it when existing residuals are large.
    if bin_residual == bin_capacity {
        let mean_excess = (mean_residual - (cap - item_size as f64)).max(0.0);
        score += 4.0 + mean_excess * 0.05 - 2.0 * (1.0 - progress);
        // If item fits poorly everywhere (large post_residual relative to capacity),
        // opening a fresh bin becomes more attractive.
        if pn > 0.5 {
            score -= (pn - 0.5) * 8.0;
        }
    }

    // Mild pressure against scattering across many bins.
    score += open_bins_count as f64 * 0.02 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Penalize dead space in coarse harmonic bands (quarters of capacity).
    let band = (post_residual * 4 / bin_capacity) as f64;
    score += band * 6.0;

    // Reward near-perfect fits: post_residual in small modulo classes.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual % 10 == 0 {
        // Residuals that are round numbers are likely reusable by common item sizes.
        score -= 8.0;
    } else if post_residual < 10 {
        // Tiny unusable slivers: heavy penalty.
        score += 25.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - 0.2 * slack.min(30.0);
            // Harmonic bonus when next item exactly divides the residual class.
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 6.0;
            }
        } else {
            score += 7.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).min(1.0);
        score = 55.0 - 35.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits anywhere: open new bin
        }
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
    }

    // Stream phase: early on, be greedy about consolidation; late, prefer tight fits.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - phase) * 3.0 * (1.0 - frac);

    // Mild preference to fill bins when many are open (reduce fragmentation).
    score += 0.15 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (size 1) are pure waste, but gaps below a "useful threshold" are the
    // real killers. Penalize non-linearly when post_residual lands in the
    // dead zone (1..=10) where almost nothing fits later.
    let dead_threshold: f64 = 10.0;
    if post_residual >= 1 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward heavily (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item cannot fit in post_residual but would fit in bin_residual
    // only if we skip this placement, mild penalty for blocking.
    if next_item_size > post_residual && next_item_size > 0 && next_item_size <= bin_capacity {
        score += 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using existing bins as open_bins_count grows.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when current
    // residuals are large and fragmented (mean residual high relative to item).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when existing bins are too full/fragmented.
        score -= 15.0 * (1.0 - fragmentation) - 10.0 * progress;
        // But if a last-chance bin exists, don't steal it.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    // Mild preference for bins whose residual is close to item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect match: this bin will be exactly filled by the next item.
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item still fits after placement; mild reward proportional to slack.
            score -= 8.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use this bin's leftover: penalize dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 + 0.25 * gap;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 10.0;
    }

    // Compare against mean residual: bins with above-average residual are better hosts.
    let dev = mean_residual - bin_residual as f64;
    score += 0.20 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize tiny unusable leftovers (dead space) unless exact-match handled above.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: penalize slightly so we only open when fits are truly bad.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-full fills (post_residual small relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64; // 0 = perfect
    score += 8.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item can fit into post_residual, reward this placement;
    // otherwise penalize leaving a residual that wastes space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // dead space: next item cannot use it
            score += 5.0 + 0.05 * post_residual as f64;
            // extra penalty if the next item would have fit in the pre-placement residual
            if bin_residual >= next_item_size {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual of open bins:
    // placing into a bin with residual below mean leaves larger bins for future items -> reward
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when the item is large
    // or no good fits exist. Penalize the empty bin (bin_residual == bin_capacity) generally,
    // but relax the penalty for large items or early stream.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / 100.0) * 20.0;
        score += 30.0 - large_item_bonus - 10.0 * (1.0 - progress);
        // if many bins already open, discourage adding more
        score += 0.5 * open_bins_count as f64;
    }

    // Encourage filling nearly-full bins more aggressively as stream progresses
    if bin_residual < bin_capacity {
        score -= 10.0 * progress * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let norm_item = item / cap;

    // Base: post residual, with non-linear polynomial coupling to progress
    let mut score = pr;

    // Smooth waste penalty: residual squared, modulated by stream progress
    let waste = norm_pr * norm_pr;
    score += waste * cap * (0.5 + 0.9 * progress);

    // Cubic coupling: late in the stream, very small residuals are dead space
    let dead = norm_pr * norm_pr * norm_pr;
    score += dead * cap * (1.5 * progress - 0.5);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 40.0 * progress);

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += (nx - pr) * (0.4 + 0.6 * progress);
        } else {
            score -= (pr - nx) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // Discourage leaving residual far from mean residual (imbalance penalty)
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += dev * dev * 15.0;

    // New-bin candidate: keep neutral-ish baseline but slightly penalize early,
    // allow late when residuals are fragmented
    if bin_residual == bin_capacity {
        score = cap * (1.0 - 0.4 * progress) + 0.5 * mean_residual * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by 10 are more reusable
    // because item sizes cluster in decades (10..80 in classic streams, and even
    // for unknown streams, round residues pair well with round items).
    let pr = post_residual as i64;
    let harmonic_bonus = match pr % 10 {
        0 => -14.0,
        5 => -7.0,
        1 | 9 => -2.0,
        3 | 7 => -1.0,
        _ => 0.0,
    };
    score += harmonic_bonus as f64;

    // Integer-division thresholds on post_residual: classify residual into
    // usefulness bands. Residual < 10 is dead space (penalize hard);
    // residual in [10, 30] is prime reusable space (reward).
    if post_residual < 10 {
        score += 22.0;
    } else if post_residual <= 30 {
        score -= 9.0;
    } else if post_residual <= 55 {
        score -= 3.0;
    }

    // Lookahead coupling: reward bins whose post_residual can still host the
    // next item exactly or nearly; penalize bins that cannot.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 11.0; // near-perfect two-step packing
            } else if slack % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 6.0; // this bin becomes dead after this placement
        }
    }

    // Tight fit reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 16.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual. Only
    // attractive when existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream
        // when future items are plentiful and may fill fresh space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 34.0 + 26.0 * progress;
        // If the next item is large, a fresh bin is safer.
        if next_item_size >= 60 {
            new_bin_score -= 12.0;
        }
        // If many bins are open and none fit well, fresh bin is fine.
        if fitting_bins_count == 0 {
            new_bin_score -= 10.0;
        }
        // If mean residual is small, existing bins are nearly full anyway.
        new_bin_score += 0.15 * mean_residual;
        score = new_bin_score;
    } else {
        // Prefer bins below mean residual (consolidating fuller bins) mildly.
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Late-stream pressure: close bins tightly as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure loss; anything below the current item's "reuse horizon" is suspect.
    // Penalize unusable gaps super-linearly.
    if post_residual == 0 {
        // Perfect fit — heavily reward closing a bin exactly.
        score -= 60.0;
    } else if post_residual < 10 {
        // Tiny sliver: nearly unusable dead space, punish hard.
        score += 25.0 + (10 - post_residual) as f64 * 2.5;
    } else {
        // Usable leftover: reward proportionally to how well it matches
        // a plausible future item (next_item_size lookahead).
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Extra reward if the next item fits exactly into the leftover.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item cannot reuse this space: mild penalty scaled by gap.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Tightness reward: fraction of the bin's residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Mean-residual coupling: if this bin is far below average fullness,
    // it is a better dumping ground; if above average, penalize slightly.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the dead-space penalty above is extreme).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open bin
    // offers a decent fit. Give the empty bin a moderate baseline cost so that
    // any reasonably tight existing fit beats it.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly equals next item size -> strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post residual -> partial lookahead reward,
    // stronger the tighter the resulting double fit.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit into post residual -> penalize wasted space
    // proportional to how unusable the leftover is relative to mean residual.
    else if next_item_size > 0 {
        let waste = post_residual as f64 / mean_residual.max(1.0);
        score += 15.0 * waste;
    }

    // Penalize leaving tiny dead space that likely nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Deter new-bin opening unless residuals across open bins are already tight.
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        score += 30.0 * (1.0 - avg_tightness);
        // Late in the stream, opening new bins is costlier.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild tie-break: prefer fuller bins (smaller residual) overall.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of fit: fraction of residual consumed by this item
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };

    // Reward tight fits strongly (subtract more for larger fit_ratio)
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving small unusable dead space (dead zone below min item size 1..=10)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward preserving that space
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
    }
    // If next item would NOT fit here anyway, mild penalty for wasting space
    else if next_item_size > post_residual && post_residual > 0 {
        score += 2.0;
    }

    // Global state coupling: if mean residual is high, prefer consolidating into existing bins
    let mean_res_gap = mean_residual - post_residual as f64;
    if mean_res_gap > 0.0 {
        score -= 0.05 * mean_res_gap;
    } else {
        score += 0.05 * (-mean_res_gap);
    }

    // Many open bins -> encourage closing them out (favor bins with small residual)
    if open_bins_count > 4 {
        score += 0.3 * (post_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln();
    }

    // Early stream: be conservative, prefer new bins over fragmenting; late stream: pack tightly
    if progress < 0.2 {
        score += 3.0 * (1.0 - progress / 0.2) * (post_residual as f64 / bin_capacity as f64);
    } else {
        score -= 3.0 * progress * fit_ratio;
    }

    // New-bin candidate handling: empty bin gets baseline score; open a new bin only when
    // fits elsewhere are poor (large post_residual relative to capacity) or few open bins
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins already open or early stream
        let mut new_bin_cost = 18.0;
        new_bin_cost -= 2.0 * (open_bins_count as f64).min(10.0);
        new_bin_cost -= 5.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is natural
        new_bin_cost -= 0.1 * item_size as f64;
        score = new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base cost: wasted residual, shaped non-linearly (dead space grows superlinearly)
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // early on, prefer tight fills (minimize residual strongly); later, tolerate slack
    let progress_poly = 0.5 + 2.0 * progress * progress - 1.0 * progress;
    score *= progress_poly;

    // Interaction: residual vs mean residual of open bins
    let mean_dev = (pr - mean_residual) / cap;
    score += 20.0 * mean_dev * mean_dev * (1.0 + progress);

    // Reward bins that can also host the lookahead item smoothly
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * (1.0 - fit_quality) * (1.0 - fit_quality);
    } else if next_item_size > post_residual {
        score += 3.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // New-bin candidate: penalize opening a bin when good fits exist,
    // but allow it late in the stream or when it enables perfect pairing
    if bin_residual == bin_capacity {
        let mut new_bin_score = 30.0 * (1.0 - progress);
        if next_item_size > 0 {
            let pair_waste = (cap - item_size as f64 - next_item_size as f64).max(0.0) / cap;
            new_bin_score += 40.0 * pair_waste * pair_waste;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0;
        }
        score = new_bin_score.max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual classes mod capacity quarters
    let q = bin_capacity / 4; // 25
    let class = post_residual % q;

    // Penalize residuals that fall in "dead" classes (too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if class == 0 && post_residual > 0 {
        score -= 12.0; // perfectly divisible residual, reusable
    } else {
        score += (class as f64) * 0.35; // mild penalty for off-class residuals
    }

    // Integer-division threshold: how many items of the lookahead size still fit
    if next_item_size > 0 {
        let fits_next = post_residual / next_item_size.max(1);
        if fits_next >= 1 {
            score -= 18.0 + 4.0 * (fits_next as f64).min(4.0);
        } else {
            score += 10.0; // lookahead won't fit here
        }
        // Harmonic pairing: item + next item exactly fills a capacity fraction
        let pair = item_size + next_item_size;
        if pair == bin_capacity {
            score -= 40.0;
        } else if bin_capacity % pair == 0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish base, penalize opening when good fits exist
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 10.0; // fresh bin guarantees lookahead fit
        }
    }

    // Tight-fit reward: residual nearly consumed
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Stream progression: later in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any gap smaller than the minimum item size is wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable dead space
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: fully consume the bin
    }

    // Reward tight fits (small post_residual relative to capacity).
    score += 0.6 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64 - item_size as f64);

    // Penalize bins whose residual is far above the item (loose fit) mildly; tightness already favored.
    if (bin_residual as f64) > mean_residual {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Open-bin pressure: discourage scattering across many bins unless the fit is excellent.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 + progress);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin fits well
    // (i.e., when this call is the empty-bin call) and current bins have large scattered residuals.
    if bin_residual == bin_capacity {
        let waste_pressure = (mean_residual - item_size as f64).max(0.0);
        // Base cost of a fresh bin; cheaper late in the stream when residual fragmentation is high.
        score = 45.0 + waste_pressure * 0.4 - 10.0 * progress;
        if post_residual < 10 {
            score += 40.0; // fresh bin post_residual == capacity, never triggers, kept for safety
        }
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0; // fresh bin can also serve the next item
        }
    } else {
        // Lookahead coupling: prefer bins whose post_residual can still host the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 6.0;
            } else if post_residual > 0 {
                score += 0.3 * (next_item_size as f64 - post_residual as f64);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / item_size.max(1) as f64;
    score -= 30.0 * (-fit_ratio * 4.0).exp();

    // Exact or near-exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly/nicely.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (-next_slack / 15.0).exp();
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use.
        score += 0.5 * post_residual as f64;
    }

    // Penalize large unusable gaps (below minimum item size 1..100, gaps < next item are waste).
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 25.0;
    }

    // Compare residual to mean residual: prefer bins tighter than average.
    score -= 0.8 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong preference to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Mild pressure to keep bin count low: prefer already-open bins.
    if bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fill_ratio * fill_ratio;

    // Penalize leaving tiny unusable slivers (< 10 dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual {
            // post_residual too small for next item: penalize proportional waste.
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        } else {
            // Next item fits but leaves new residual: mild reward scaled by tightness.
            let next_fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 4.0 * next_fill;
        }
    }

    // Last-chance bonus: only fitting bin — prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize spreading across many open bins when residuals are large (encourage consolidation).
    if bin_residual < bin_capacity {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.5 * consolidation / (open_bins_count as f64 + 1.0);
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let horizon = step_index as f64 / (total_items as f64).max(1.0);
        let pressure = if fitting_bins_count == 0 { 10.0 } else { 0.0 };
        // Early stream: opening bins is cheap; late stream: discourage proliferation.
        score = 40.0 + 60.0 * horizon - pressure
            - (mean_residual / bin_capacity as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post residual), with smooth non-linear shaping.
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, tiny residuals become dead space, so penalize quadratically.
    let dead = norm_pr * norm_pr * cap;
    score += dead * (0.25 + 1.75 * progress);

    // Reward near-perfect fits smoothly (cubic decay of residual).
    score -= 12.0 * (1.0 - norm_pr).powi(3);

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let slack = (pr - nx).abs() / cap;
        score -= 18.0 * fits_next * (1.0 - slack * slack);
        // Penalize leaving a gap just slightly larger than the next item (bad fragmentation).
        score += 8.0 * fits_next * (slack * slack);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mean residual context: placing into a bin far below mean residual wastes spread;
    // smooth penalty based on deviation from mean residual.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + progress);

    // New-bin candidate handling: neutral baseline with smooth discouragement early,
    // more openness late when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = cap * (0.9 - 0.5 * progress * crowd);
        // Opening a new bin is attractive if no bin leaves a good fit; approximate via item size.
        score -= 0.3 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are ideal
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    } else if post_residual <= 30 {
        score += 5.0;
    } else {
        score += 15.0;
    }

    // Modulo arithmetic on post_residual: small residues mod 10 are tighter fits
    let rmod = post_residual % 10;
    score -= (10 - rmod) as f64 * 0.8;

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let nxt_mod = next_item_size % 10;
            let post_mod = post_residual % 10;
            if nxt_mod == post_mod || (nxt_mod + post_mod) == 10 {
                score -= 12.0;
            }
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize if this creates dead space
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
        if post_residual == 0 || post_residual >= 90 {
            score -= 25.0; // large item justifies a fresh bin
        }
    }

    // Stream progression: late in stream, be more aggressive about filling bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    // Slight preference for bins below mean residual (balance load)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: post_residual in a "dead zone" (too small
    // for typical future items, i.e. < 10) is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 300.0;
    }

    // Post-residual that cannot fit the lookahead item is risky dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Room for the next item: reward proportionally.
            score -= 60.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead: penalize heavily, scaled by
            // how close the next item is to fitting.
            let miss = (next_item_size - post_residual) as f64;
            score += 40.0 + 4.0 * miss;
        }
    }

    // Tightness reward: fraction of the bin's space consumed by this item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 120.0 * tightness;

    // Waste-avoidance: penalize leaving large residuals when the item is small
    // relative to the bin (squandering a big bin on a small item).
    if item_size < bin_residual / 2 {
        score += 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins rather than spreading out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += 0.8 * pressure;

    // Mean-residual coupling: if this bin is tighter than average, favor it
    // (fills nearly-full bins first, keeps slack bins for future items).
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: discourage unless current bin fits are poor.
    // A fresh bin has full residual and zero post_residual benefit is fake,
    // so penalize it proportionally to how many bins already fit the item.
    if bin_residual == bin_capacity {
        let base = 150.0 + 40.0 * fitting_bins_count as f64;
        // Late in the stream with many open bins, new bins are more acceptable
        // (keeps future flexibility), so soften the penalty.
        score += base * (1.0 - 0.5 * progress);
        // But if the next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted residual space after placement.
    let mut score = post_residual as f64;

    // Reward near-perfect fits (post_residual close to 0).
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the
    // residual left behind, this is a chained perfect fit — big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 40.0;
        } else if post_residual < next_item_size && next_item_size - post_residual <= 5 {
            // Next item nearly fits the leftover: mild penalty for fragmentation.
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // already tight; using them for a good fit is efficient.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.5;
    } else {
        score += (resid_f - mean_residual) * 0.2;
    }

    // Last-chance bin: only open bin that fits the item — strong reward
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 70.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits (already in base),
        // but discourage leaving a bin with awkward mid-range residual.
        if post_residual > 10 && post_residual < item_size.min(30) {
            score += 10.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // late in the stream or when the item is huge relative to residual.
    if bin_residual == bin_capacity {
        let fresh_penalty = 90.0 - 40.0 * progress;
        score += fresh_penalty;
        if item_size >= 80 {
            score -= 30.0; // huge items may justify a fresh bin anyway
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // Pairing potential in a fresh bin: soften the penalty.
            score -= 20.0;
        }
    }

    // Slight preference to fill older bins (implicitly via count coupling):
    // when many bins are open, encourage consolidation.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count.min(20) as f64 - 4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a mild non-linear penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or well, boost this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= (30.0 * (1.0 - leftover as f64 / bin_capacity as f64)).max(0.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: penalize dead space proportionally.
        score += (post_residual as f64 - next_item_size as f64).abs() * 0.15;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state: many open bins with large mean residual -> encourage consolidation.
    if mean_residual > 0.0 {
        let tightness = (post_residual as f64 / mean_residual).min(2.0);
        score -= tightness * 5.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (penalize cramming less);
    // late in stream, prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin gets a moderate baseline score so it
    // wins only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 35.0 + (open_bins_count as f64 * 2.0) * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Fragmentation penalty for large unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are hard to fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) growth
    let mut score = pr + 18.0 * norm_pr * norm_pr * cap;

    // Coupling: residual waste matters more as stream progresses
    let progress_coupling = 1.0 + 2.5 * progress * progress;
    score *= progress_coupling;

    // Smooth interaction between post_residual and mean residual:
    // prefer bins whose post_residual aligns with the mean residual of open bins
    let align = (pr - mean_residual).abs() / cap;
    score += 12.0 * align * align * cap;

    // Reward tight fits: cubic falloff of penalty as post_residual -> 0
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (item_size as f64 / cap);

    // Last-chance bin: strongly favor using it (smooth exponential urgency)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack).powi(2);
        } else {
            // penalize blocking the next item
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for spreading across many bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: make it unattractive unless residuals are all poor
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 40.0 - 30.0 * mean_tightness * mean_tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: residuals that no future item (1..=100) can use well.
    // Harmonic class: post_residual in (0,10) is nearly unusable -> heavy penalty
    // unless it is 0. Residuals that are multiples of 10 are "harmonic" and reusable.
    if post_residual > 0 {
        let mod10 = post_residual % 10;
        if post_residual < 10 {
            score += 60.0 - (post_residual as f64) * 4.0; // tiny dead space penalty
        } else if mod10 == 0 {
            score -= 25.0; // harmonic residual, likely reusable
        } else {
            score += (10 - mod10) as f64 * 1.5; // penalty grows with non-harmonicity
        }
    }

    // Integer-division class of post_residual: prefer residuals in bands that
    // match typical item sizes (multiples of 5 / 10).
    let band = post_residual / 20; // 0..=5
    score -= band as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item still fits after this placement: mild reward
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item won't fit here: penalize more when the gap is tiny
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
        // Harmonic lookahead class: next_item_size multiple of 10 pairs well with
        // harmonic residuals.
        if next_item_size % 10 == 0 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline that beats
    // accepting very poor fits but loses to any reasonable existing-bin fit.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.1;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity - 1) && item_size > bin_capacity / 2 {
            score -= 30.0; // big item + big next item: fresh bin is good
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open the first bin
        }
    }

    // Late in stream: consolidate, avoid spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 + progress) * 0.5;

    // Prefer bins below mean residual (tighter bins) slightly.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // are pure waste; residuals that cannot host typical items are penalized hard.
    let dead_threshold = 10.0_f64; // smallest plausible useful gap
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Penalize residuals that are small enough to be "unusable dead space"
    // but nonzero: nothing else fits, wasting capacity.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 25.0;
    }

    // Reward tight fits (perfect fill strongly favored).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fit_ratio * fit_ratio;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage scattering across many bins when residuals
    // are already fragmented; encourage consolidating into low-residual bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 12.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here: slight penalty if we strand it
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below the mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., this empty bin's score competes via a mild offset).
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
        // Opening a new bin is good if current bins are very fragmented.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fills bin
        } else if next_item_size <= post_residual {
            // next item also fits here: penalize leaving space that could chain badly,
            // but reward partial chaining proportional to fill.
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * chain_fill;
            // penalize leftover after chaining
            let leftover = post_residual as f64 - next_item_size as f64;
            score += 0.35 * leftover;
        } else {
            // next item cannot use the leftover: leftover is dead space
            let dead = post_residual as f64 - next_item_size as f64;
            score += 0.25 * dead.min(next_item_size as f64);
        }
    }

    // Compare post_residual against mean residual: avoid making bin worse than average.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Slight penalty by default so existing bins are preferred when decent.
        score += 8.0;
        // If many bins already open and post_residual (i.e. capacity - item) is large,
        // opening fresh may still be fine; dampen penalty late in stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * progress;
        // If the current item is large, a fresh bin leaves small residual -> good.
        score -= 0.1 * item_size as f64;
        // If next item is huge and wouldn't fit alongside in a shared bin, fresh bin helps.
        if next_item_size > 50 {
            score -= 6.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    if open_bins_count > 4 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize leaving a residual that is small but unusable relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize creating a residual that wastes space for the next item.
            score += 0.05 * (post_residual as f64).min(20.0);
        }
    }

    // New-bin candidate handling: make a fresh bin attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins when existing bins have room; relax as stream progresses.
        let penalty = 40.0 * (1.0 - crowding) * (1.0 - 0.4 * progress);
        score += penalty;
        // Slight penalty to discourage bin proliferation when many bins already open.
        score += 0.3 * open_bins_count as f64;
    } else {
        // Favor bins with residual above average (they are more versatile).
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Mild preference for using more-open bins early (keeps bins consolidated).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: quadratic waste coupling with progress
    let mut score = pr + pr_norm * pr_norm * (40.0 + 60.0 * progress);

    // Favor tight fits: subtract when post_residual is small relative to item
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 25.0 * (1.0 - pr / nx) * (1.0 + progress);
        } else {
            score -= 10.0 * (pr / cap);
        }
    } else {
        // last item: strongly prefer filling a bin exactly
        score -= 50.0 * (1.0 - pr_norm);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Smooth coupling with mean residual: prefer bins near the mean (balance)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // New-bin candidate: make it moderately unattractive unless it enables future packing
    if bin_residual == bin_capacity {
        let future_need = next_item_size as f64 / cap;
        score = 60.0 + 80.0 * progress - 40.0 * future_need * future_need;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions (eighths)
    let item_class = item_size * 8 / bin_capacity; // 0..=6 coarse class
    let post_class = post_residual * 8 / bin_capacity;

    // Reward tight fits: post_residual near zero is best
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if post_residual <= bin_capacity / 16 {
        score -= 60.0; // near-perfect fill
    } else {
        // Penalize dead space that is too small for typical items (unusable sliver)
        if post_residual < 10 {
            score += 40.0; // tiny sliver = wasted space
        }
    }

    // Harmonic pairing: does post_residual exactly match a "useful" residue class?
    // Residues that commonly arise from small/medium items (10..40) are reusable.
    let reusable = post_residual >= 10 && post_residual <= 50;
    if reusable {
        // Reward bins whose leftover matches the next item's needs
        if next_item_size > 0 && next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 300.0; // lookahead exact fit
            } else if slack <= 10 {
                score -= 120.0;
            } else {
                score -= (50.0 * next_item_size as f64) / (post_residual as f64);
            }
        } else if next_item_size > 0 {
            // next item cannot use this leftover: mild penalty, scaled by how close it was
            score += 15.0;
        }
    } else {
        // Large dead space (post_class high) is fine only if bin was mostly empty
        score += 5.0 * post_class as f64;
    }

    // Modulo threshold on post_residual: values in (50, 100) capacity are "half-empty"
    // bins that are attractive targets for medium items; keep them mid-ranked.
    if post_residual > bin_capacity / 2 {
        score += 8.0; // don't dump big items into roomy bins unnecessarily
    }

    // Last-chance logic: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0; // strongly prefer avoiding a new bin
    }

    // New-bin candidate handling: empty bin gets a high baseline so it is only
    // chosen when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Early in the stream, opening bins is cheap and useful
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 150.0 * (1.0 - progress);
        // If next item is huge and current item is small, fresh bin preserves room
        if next_item_size > bin_capacity * 3 / 4 && item_size <= bin_capacity / 4 {
            score -= 80.0;
        }
    }

    // Spread-awareness: prefer filling bins below mean residual (tighter bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Congestion: many open bins -> favor consolidation into existing bins
    if open_bins_count > 8 {
        score += 20.0;
    }

    // Integer-division threshold: item classes 0..1 (tiny items) fill gaps cheaply
    if item_class <= 1 && post_residual >= 10 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be usable
    // later are heavily penalized (dead zone threshold calibrated to ~15).
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits (post_residual in the small but reusable band).
    if post_residual >= 15 && post_residual <= 30 {
        score -= 10.0;
    }

    // Perfect fill is best possible outcome.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tightness reward: fraction of bin filled by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let bin_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open, and when the
        // item fits comfortably in existing bins.
        score += 20.0 * bin_pressure;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // If the next item is large, opening a fresh bin now may be wise.
        if next_item_size > 60 && item_size <= 40 {
            score -= 25.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    } else {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // If the next item would fit better in the leftover space, reward this placement.
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 8.0;
        }
        // Penalize leaving a gap that the lookahead item almost fits but misses.
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 && (next_item_size as f64 - post_residual as f64) <= 10.0 {
            score += 12.0;
        }
        // Mild penalty for placing into bins with already-low residual
        // relative to the mean (keep flexible bins open).
        if (bin_residual as f64) < mean_residual * 0.5 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base: prefer bins whose post_residual matches next item exactly
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step match
        } else if post_residual > next_item_size {
            let slack = pr - look;
            score -= 12.0 / (1.0 + slack / 10.0);
            // penalize leaving residual that no small item can use
            if post_residual < 10 {
                score += 25.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to shortfall
            score += (look - pr) * 0.6;
        }
        // bonus if residual can host either item_size leftover patterns
        if post_residual >= 10 {
            score -= 3.0;
        }
    } else {
        // last item: just minimize waste
        score = post_residual as f64 * 1.5;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin gets strong priority
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual == 0;
        let _ = good_fit_exists;
        score = 100.0 + (fitting_bins_count as f64) * 5.0;
        // allow new bin early in stream or when few bins fit
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score = -50.0;
        } else if fitting_bins_count == 1 && progress > 0.3 {
            score = 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill achieved by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize small post_residual nonlinearly
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        // dead-space penalty grows superlinearly for small residuals
        score += (pr / bin_capacity as f64).powf(2.0) * 40.0;
    }

    // Reward high fill ratio
    score -= fill * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize a bit
            score += 8.0;
        }
    }

    // Time horizon: early on, be more willing to spread (open bins); late, pack tight
    score += t * 10.0 * (post_residual as f64 / bin_capacity as f64);
    score -= (1.0 - t) * 5.0;

    // Global residual pressure: if mean residual is large, prefer filling existing bins
    score += 0.15 * (mean_residual - post_residual as f64);

    // Many open bins: discourage opening yet another one
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else {
            (item_size as f64 / bin_residual as f64).min(1.0)
        };
        // base cost of a fresh bin, discounted by desperation
        score += 55.0 * (1.0 - desperation * 0.9);
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear penalty on residual: quadratic growth of wasted space
    let pr = post_residual as f64;
    score += (pr * pr) / cap;

    // Cubic coupling with stream progress: late in the stream, waste is costlier
    score += progress * (pr * pr * pr) / (cap * cap);

    // Reward tight fits (small post_residual) more strongly than linear
    let tightness = 1.0 - pr / cap;
    score -= item_size as f64 * tightness * tightness * 0.5;

    // Lookahead: if next item fits exactly in the post-residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= (cap - gap) / cap * 3.0;
            // extra reward for perfect chaining
            if gap == 0.0 { score -= 5.0; }
        } else {
            // next item won't fit here: slight penalty proportional to overshoot
            score += (nxt - pr) / cap * 1.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (consolidating larger gaps)
    score += (mean_residual - pr) * 0.3;

    // New-bin candidate handling: brand-new empty bin gets a baseline penalty,
    // softened when few bins fit or late in the stream
    if bin_residual == bin_capacity {
        score += 4.0 + 2.0 * (1.0 - progress);
        if fitting_bins_count == 1 { score += 6.0; }
        if next_item_size > 0 && (next_item_size as f64) >= cap * 0.5 { score -= 2.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let r = post_residual;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // --- Harmonic class floor: residuals below the smallest useful class
    // (width 10 of a capacity-100 bin) are nearly dead space. Demote them by
    // pricing them as if they were the class floor, plus an extra tax, so a
    // residual of 1..9 ranks worse than a clean residual of 10+.
    let class_floor: u32 = 10;
    if r > 0 && r < class_floor {
        score += (class_floor - r) as f64 * 2.0;
    }

    // --- Perfect closure: exact fit closes the bin, the best possible event.
    if r == 0 {
        score -= 900.0 * (1.0 + progress);
    }

    // --- Perfect pair: another copy of this item would exactly close the bin.
    if r == item_size && r > 0 {
        score -= 90.0 * (1.0 + progress);
    }

    // --- Divisibility tiling: if the residual is an exact multiple of the
    // item size, k more copies of this item would tile the bin perfectly.
    if item_size > 0 && r > 0 && r % item_size == 0 {
        score -= 20.0 * (r / item_size) as f64;
    }

    // --- Decile-aligned residuals are more likely reusable by future items.
    if r > 0 && r % 10 == 0 {
        score -= 5.0;
    }

    // --- Lookahead chaining (k=2): shape the residual for the next item.
    if next_item_size > 0 {
        let nr = next_item_size;
        if r == nr {
            // The next item closes this bin exactly: strongest chain signal.
            score -= 300.0 * (1.0 + progress);
        } else if r > nr {
            let diff = r - nr;
            if diff < class_floor {
                // Next item fits and leaves near-dead waste: excellent chain.
                score -= 90.0 * (1.0 - diff as f64 / class_floor as f64);
            } else {
                // Next item still fits here: mild chain preference.
                score -= 15.0;
            }
        } else if r > 0 {
            // Next item cannot use this residual: slight penalty.
            score += 4.0;
        }
    }

    // --- Tightest-bin pull: bins already below the mean residual are closest
    // to closure; favor deepening them so bins actually finish.
    let tight = (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.25 * tight.min(80.0);

    // --- Last-chance bin: if this is the only open bin that fits, using it
    // avoids opening a new bin; reward a reasonable fit here.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // --- New-bin candidate tax: consolidation into existing bins is the
    // default; only open a fresh bin when every existing fit is poor. The tax
    // grows with the number of available alternatives.
    if is_new_bin {
        score += 10.0 + 3.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 20.0;

    // Strict dead-space avoidance: penalize small unusable gaps (1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // If the next item can still fit into the post-residual gap, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.5;
    }
    // If next item almost fits (small shortfall), slight penalty for stranding space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }
    // Many competing bins: mild pressure toward tighter choices.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Open-bin pressure: when many bins are open, discourage spreading to loose fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    // Mean-residual coupling: if this bin's residual is far below the mean, it is
    // nearly full -> reward using it; if far above mean, mild penalty.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.25;

    // New-bin candidate: neutral-ish baseline; only attractive when no open bin
    // gives a decent fit (large item, few fitting bins).
    if bin_residual == bin_capacity {
        score = 45.0 + item_size as f64 * 0.4 - fitting_bins_count as f64 * 12.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, prefer reusing bins more aggressively.
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: near-zero post residual is ideal -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills leftover.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if next_item_size == post_residual {
            // Next item perfectly fills this bin: excellent chaining.
            score -= 55.0;
        } else if next_item_size < post_residual {
            // Next item fits here too; reward proportionally to how tight it is.
            let tightness = 1.0 - (pr - nr) / (bin_capacity as f64);
            score -= 20.0 * tightness;
        } else {
            // Next item cannot use the leftover: dead space risk penalty.
            let waste = (nr - pr) / (bin_capacity as f64);
            score += 25.0 * waste;
        }

        // If next item fits in the residual, also check it fits without wasting
        // the bin's future: penalize leaving residual that no small item will use.
        if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score += 15.0; // tiny unusable sliver
        }
    } else {
        // Last item: strongly prefer zero-waste placement.
        score += 0.5 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (consolidating fuller bins), penalize dumping into emptiest bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual) / bin_capacity as f64;
        score += 30.0 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, reward using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless no open bin fits well.
    // Penalize opening a new bin more as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 25.0 * progress;
        // Exception: if next item is large and current item is large, a fresh
        // bin may be reasonable — soften penalty.
        if next_item_size >= 60 && item_size >= 60 {
            score -= 30.0;
        }
    }

    // Slight preference for fewer open bins (encourage consolidation).
    score += 0.3 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect packing: eliminate dead space aggressively.
    if post_residual == 0 {
        score -= 250.0;
    } else if post_residual < 10 {
        score -= 70.0;
    } else if post_residual < 20 {
        score -= 25.0;
    }

    // Penalize leaving an unusable sliver smaller than the current item.
    if post_residual > 0 && post_residual < item_size {
        score += 18.0;
    }

    // Lookahead coupling (k=2): favor bins whose post-residual matches next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size > post_residual {
            // next item cannot follow here: mild penalty
            score += 12.0;
        } else {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.35;
            if slack > 40.0 {
                score += slack * 0.2;
            }
        }
    } else {
        // Last item: closing bins is maximally valuable.
        score -= 120.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Global-state coupling: prefer bins below mean residual (more filled bins first).
    score += (mean_residual - post_residual as f64) * 0.12;

    // New-bin candidate handling: default to opening only when current fits are poor.
    if bin_residual == bin_capacity {
        score += 85.0 + (open_bins_count as f64).min(40.0) * 0.5;
        if next_item_size > 0 && next_item_size > post_residual {
            score += 15.0;
        }
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Dynamic time horizon: early in stream, be slightly conservative with tight fills;
    // late in stream, push harder for closure.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.08 * t;
    if t > 0.9 {
        score -= 10.0 * (t - 0.9) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early in the stream, tolerate larger leftovers; late, demand tight fits.
    let tightness = pr / cap;
    score += 18.0 * tightness * tightness * (1.0 - progress);

    // Reward near-perfect fits with a smooth saturating term.
    let perfect = (1.0 - tightness).powi(6);
    score -= 12.0 * perfect;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let nx_fit = 1.0 - ((pr - nx) / cap).abs();
            score -= 10.0 * nx_fit * nx_fit;
        } else {
            // post_residual too small for next item: penalize dead space mildly.
            score += 4.0 * (pr / cap);
        }
    }

    // Penalize bins far from mean residual (keep residuals homogeneous),
    // with a smooth quadratic coupling.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: baseline preference grows when many bins are open
    // and stream is early; discourage late in the stream to consolidate.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress - 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by large classes are more reusable.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus -= 60.0; // perfect closure
    } else {
        if pr % 50 == 0 { class_bonus -= 25.0; }
        if pr % 25 == 0 { class_bonus -= 12.0; }
        if pr % 20 == 0 { class_bonus -= 10.0; }
        if pr % 10 == 0 { class_bonus -= 6.0; }
        // large post-residual chunks are valuable
        if pr >= 50 { class_bonus -= 8.0; }
        else if pr >= 30 { class_bonus -= 3.0; }
        else if pr <= 5 { class_bonus += 6.0; } // dead space
    }
    score += class_bonus;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
            if slack == 0.0 { score -= 5.0; }
        } else {
            score += 5.0; // next item can't use this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral baseline, penalize slightly unless open bins are crowded.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 10.0;
        }
    }

    // Tight fit reward relative to fill fraction.
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * fill;

    // Phase of stream: later, consolidate more aggressively.
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * phase * (1.0 - post_residual as f64 / cap);

    // Penalize bins far from mean residual (fragmentation).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward tight fits: smaller post_residual relative to item size is better.
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * 10.0;

    // If this is the only fitting bin, strongly favor using it (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap the next item just barely misses (dead space creation).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    if bin_residual != bin_capacity {
        score += 3.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 40.0 + 10.0 * open_bins_count as f64;
        // But if no open bin fits well (high mean residual waste), allow new bin.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that is likely unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer existing bins generally,
    // but open a new bin when remaining open bins are nearly full on average
    // or when the item would leave a very poor residual.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = mean_residual / bin_capacity as f64;
        // New bin is attractive when open bins are crowded or fit is bad.
        score -= 10.0 * open_pressure + 5.0 * (1.0 - fit_ratio);
        // Slight openness to new bins early in the stream.
        score -= 2.0 * (1.0 - progress);
        // Avoid hoarding many bins.
        score += 0.4 * open_bins_count as f64;
    } else {
        // Mild preference for filling existing bins when many are open.
        score += 0.15 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean (use the emptier ones).
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * norm_pr * norm_pr * (1.0 + 3.0 * p2) * cap * 0.01;
    score -= 8.0 * norm_pr * p3 * cap * 0.01;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize wasted residual relative to mean residual of open bins
    score += 0.05 * (pr - mean_residual) * (1.0 + p2);

    // Last-chance bin: strong reward, growing with progress
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.6 + 0.8 * progress);
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        score += 2.0 * (1.0 - (next_item_size as f64 - pr) / cap);
    }

    // New-bin candidate: penalize mildly early, less late
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Class A: post_residual is tiny -> near-perfect fit, strong reward.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    }

    // Class B: post_residual in the "dead zone" (31..=49) creates space too
    // small for typical medium items but too big to ignore. Penalize.
    if post_residual >= 31 && post_residual <= 49 {
        score += 18.0;
    }

    // Integer-division harmonic classes of post_residual (mod 10 bands).
    let band = post_residual / 10;
    score += match band {
        0 => -12.0,
        1 => -6.0,
        2 => 0.0,
        3 => 10.0,
        4 => 14.0,
        5 => 6.0,
        6 => -2.0,
        7 => -8.0,
        _ => -4.0,
    };

    // Lookahead coupling: if next item fits exactly or well into post_residual,
    // this bin is very valuable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= (30.0 - gap.min(30) as f64) * 0.8;
        } else {
            // Next item does not fit here: slight penalty scaled by overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.15;
        }
    }

    // Last-chance bin: only bin that can fit the item -> avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; overcome when existing fits are bad.
        score += 25.0;
        // Opening a new bin is attractive if the item would leave a bad
        // harmonic class in any existing bin (large post_residual dead zone).
        if post_residual >= 31 && post_residual <= 49 {
            score -= 30.0;
        }
        // If next item is large and would need a fresh bin anyway, pre-opening
        // via this item in a new bin is fine.
        if next_item_size >= 60 && item_size >= 60 {
            score -= 20.0;
        }
        // Early in stream, keep bins open; late, allow opening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 8.0;
    }

    // Mild pressure toward consolidating into bins below mean residual
    // (fills the emptiest bins first, keeping tight bins for tight fits).
    let bin_res_f = bin_residual as f64;
    if bin_res_f > mean_residual {
        score += (bin_res_f - mean_residual) * 0.05;
    } else {
        score -= (mean_residual - bin_res_f) * 0.03;
    }

    // Many open bins: discourage fragmentation, prefer filling existing ones.
    if open_bins_count > 6 {
        score += (open_bins_count as f64 - 6.0) * 0.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=9)
    // are pure waste -> heavy penalty scaling with wasted fraction.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Near-dead zone 10..=19: only usable by smallest items; mild penalty.
    else if post_residual >= 10 && post_residual <= 19 {
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fills (post_residual tiny but not zero).
    if post_residual > 0 && post_residual <= 5 {
        score -= 25.0;
    }
    if post_residual == 0 {
        score -= 80.0; // perfect fit: strong reward
    }

    // Open-bin pressure: discourage scattering across many open bins,
    // but soften late in the stream when closing bins is natural.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).sqrt() * 3.0 * (1.0 - 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no good fit exists (item would leave large dead space everywhere) or
    // the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let dead_elsewhere = mean_residual - item_size as f64;
        let poor_fit = dead_elsewhere > 0.0 && (dead_elsewhere < 10.0 || dead_elsewhere > 40.0);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 25.0; // default: prefer existing bins
        }
        // Big items pack cleanly into fresh bins.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item would fit the post_residual exactly-ish, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 9 {
        score -= 18.0;
    }
    // Penalize leaving a residual the known next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus when item fills the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the NEXT item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward proportional to how snugly the next item will fit.
        let slack_after_next = post_residual - next_item_size;
        score -= 60.0 + slack_after_next as f64 * 0.3;
    } else if next_item_size > 0 {
        // Penalize leaving a residual too small for the next item (dead space risk).
        let gap = next_item_size - post_residual;
        score += gap as f64 * 0.5;
    }

    // Relative residual vs mean: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Mild penalty for opening a new bin when open bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }

    // Early in stream: slightly favor consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post-residual is small.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * (1.0 - tight).powi(2);

    // Exact / near-exact fills get a big bonus.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 45.0;
    } else if post_residual < 10 {
        // Dead space below min item size is unusable.
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty for wasting space now.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Crowding pressure: many open bins -> favor filling existing ones,
    // few open bins -> tolerate spreading.
    let crowd = (open_bins_count as f64) / (1.0 + (step_index as f64).max(1.0) / (total_items as f64).max(1.0) * 10.0);
    score -= crowd.min(20.0);

    // Global residual alignment: prefer bins whose residual is below mean
    // (they are the "smaller" bins, best to fill up).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.25 * dev;

    // New-bin candidate logic: empty bin should only win when nothing else is decent.
    if bin_residual == bin_capacity {
        let base = 55.0;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 40.0 + 3.0 * fitting_bins_count as f64 };
        let horizon = (step_index as f64 / (total_items as f64).max(1.0)) * 15.0;
        score += base + pressure + horizon;
        // If next item is huge and current item is small, opening fresh may be wise.
        if next_item_size >= 70 && item_size <= 30 {
            score -= 50.0;
        }
    }

    // Mild time decay: late in stream, consolidation matters more.
    let t = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Smooth non-linear base: quadratic in normalized post-residual
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr) * cap;

    // Polynomial coupling of post-residual with stream progress
    // Late in the stream, tighter packing (small residual) matters more
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * 1.6;
    score += coupling * cap * 0.9;

    // Reward filling a bin nearly full: subtract smooth term of item usage
    let fill = norm_it * (1.0 - norm_it); // peaks near half-fill
    score -= 12.0 * fill * (0.5 + 0.5 * progress);

    // Perfect fit bonus (smooth exponential-ish via polynomial of residual)
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits exactly in post-residual, reward this placement
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0) * (1.0 - norm_pr);
    }

    // Mild penalty when bin residual deviates from mean residual (balance bins)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate handling: neutral-ish baseline so it wins only when
    // all open bins score poorly
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) + 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (large enough for typical future items) are favored.
    let class = post_residual / 10; // integer division thresholds (0..=9)
    let class_bonus: f64 = match class {
        0 => 0.0,          // near-perfect fit, dead space minimal
        1 => 1.5,          // small awkward leftover
        2 => 2.5,
        3 => 1.0,          // ~30-39 fits many items
        4 => 0.5,
        5 => 0.0,
        6 => 0.5,
        7 => 1.0,
        8 => 1.5,
        _ => 2.0,          // nearly empty bin placed into wastefully
    };
    score += class_bonus;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item also fits in the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for the next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.1;
    }

    // New-bin candidate: only attractive when it beats all open bins clearly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 8.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        // opening a bin is worse if many open bins already have roomy residuals
        if mean_residual > item_size as f64 {
            score += 5.0;
        }
    }

    // Mild tie-break: prefer bins with residual close to mean (keeps spread tight)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals below the smallest plausible item
    // (assume min item ~10, but guard with item_size) are nearly worthless.
    let min_item = 10.0f64;
    if post < min_item && post > 0.0 {
        // Dead space: unusable gap -> heavy penalty proportional to wasted fraction
        score += (min_item - post) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = 1.0 - (post / cap);
    score -= tightness * item_size as f64 * 0.5;

    // Perfect fit bonus
    if post == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open
    // bin offers a decent fit, or when placing here would create dead space.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline moderate score; cheaper when open-bin pressure is high
        // and the current item would leave a large residual anyway.
        score = 20.0 + open_bins_count as f64 * 0.5;
        // If placing the item in an existing bin would create dead space,
        // opening a fresh bin becomes more attractive.
        if post < min_item && post > 0.0 {
            score -= 25.0;
        }
        // Lookahead: if next item is large, a fresh bin is fine.
        if next_item_size as f64 > cap * 0.5 {
            score -= 5.0;
        }
    } else {
        // Open-bin pressure: prefer filling existing bins when many are open.
        score += open_bins_count as f64 * 0.3;

        // Prefer bins whose residual is close to what we consume (avoid fragmenting
        // large residuals with small items when a better-matched bin exists).
        let mismatch = (bin_residual as f64 - item_size as f64) / cap;
        score += mismatch * 10.0;

        // Lookahead synergy: if next item fits the post residual exactly-ish, reward.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 15.0;
        } else if next_item_size > 0 && next_item_size as f64 > post {
            // Next item won't fit here after placement; slight penalty for stranding space
            score += post * 0.2;
        }
    }

    // Mild stream progression: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fill.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too: mild reward proportional to tightness.
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit in the leftover: penalize large dead space.
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.5 * waste;
        }
    }

    // Relative to mean residual: prefer using bins with more residual (large leftovers)
    // when the fit is decent, to consolidate space.
    if post_residual as f64 >= mean_residual {
        score -= 5.0;
    } else {
        score += 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when open bins can fit the item reasonably well,
    // unless the item is huge relative to residual (poor fit everywhere).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline preference for keeping it closed early on.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Open new bin mainly when item is large and no tight fit exists elsewhere.
        score += 30.0 - 25.0 * fit_quality - 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0; // fresh bin can also catch the next item
        }
    }

    // Mild penalty for leaving awkward mid-range residuals (11..30) that few items fit.
    if post_residual >= 11 && post_residual <= 30 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream [0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional tightness of the fit: perfect fill => 0
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * fit_ratio * fit_ratio;

    // Strongly reward exact / near-exact fills
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < next_item_size {
            // leftover too small for next item: mild penalty, worse if tiny dead space
            score += 8.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: any residual is pure waste; prefer tightest bin
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Penalize bins with abnormally small residual relative to mean (hoarding big space)
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 0.5 {
            score += 15.0 * (0.5 - rel);
        }
    }

    // New-bin candidate handling: opening a bin is usually costly
    if bin_residual == bin_capacity {
        let open_cost = 70.0 + 40.0 * (1.0 - progress);
        // But if no open bin fits well (this is one of few fitting options), discount
        if fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // Early in stream with few bins: cheaper to open
        score += open_cost * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        // If item is large, new bin is attractive (avoids fragmentation)
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        // Existing bin: slight bonus to keep bins consolidated
        score -= 5.0;
    }

    // Prefer spreading load when many bins are open (balance residuals)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let fit = item_size as f64;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, larger dead space is penalized super-linearly.
    let pr_norm = pr / cap;
    score += progress * 30.0 * pr_norm * pr_norm * (1.0 + pr_norm);

    // Reward tight fits: small post_residual gets a strong discount.
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let fill = nxt / cap;
            score -= 8.0 * fill * (1.0 - pr_norm);
        } else {
            // If next item is large and this bin would be left nearly empty,
            // slight penalty for wasting the slot.
            score += 2.0 * (nxt / cap) * pr_norm;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins over opening new ones.
    if bin_residual < bin_capacity {
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    } else {
        // New-bin candidate: penalize mildly, more when mean residual is still large.
        score += 6.0 + mean_residual * 0.15;
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    // from the mean (smaller-than-average residual => better consolidation).
    score += 0.08 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residue classes modulo 10 / 20
    let class10 = (post_residual % 10) as f64;
    let class20 = (post_residual % 20) as f64;
    score -= 6.0 * (1.0 - class10 / 10.0);          // reward near-zero residue class
    score -= 3.0 * (1.0 - class20 / 20.0);

    // Integer-division thresholds: usable leftover chunks
    if post_residual >= 80 { score += 8.0; }         // huge dead space penalty
    else if post_residual >= 50 { score += 3.0; }
    else if post_residual >= 30 { score -= 2.0; }
    else if post_residual >= 10 { score -= 4.0; }    // small leftovers often reusable
    else { score -= 5.0; }                            // near-perfect fill

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 7.0;
            // harmonic match: next item fills post residual to a nice class
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 { score -= 5.0; }
            if next_post % 20 == 0 { score -= 3.0; }
        } else {
            score += (next_item_size as f64 - post) * 0.15;
        }
    } else {
        // last item: prefer tightest fill aggressively
        score -= 12.0 * (1.0 - post / cap);
    }

    // Tight fit reward relative to item size
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.9 { score -= 6.0; }
    else if fit_ratio > 0.7 { score -= 2.0; }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when existing bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        // penalize new bin by default; discount when open bins have small residuals
        score = cap * (0.55 + 0.25 * progress) - 18.0 * fragmentation;
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity / 2 {
            score -= 4.0;
        }
    }

    // Mild penalty for spreading across many bins
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: strongly reward completely filling the bin.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Strict dead-space avoidance: if the leftover gap cannot host the next
    // item, it is (at least temporarily) wasted space. Penalize proportionally
    // to how much of the next item the gap fails to absorb.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        // When remaining open-bin slack (mean_residual) is thin, wasted gaps
        // are more costly; when slack is abundant, dead space is more forgivable.
        let tightness = if mean_residual > 0.0 {
            (bin_capacity as f64 / mean_residual).clamp(0.5, 3.0)
        } else {
            1.5
        };
        // Dead space matters more late in the stream (less opportunity to recover).
        score += dead * (0.6 + 0.8 * progress) * tightness;
    }

    // The gap remains usable by the lookahead item: mild reward for keeping
    // the bin flexible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Last-chance pressure: this is the only open bin that can fit the item.
    // Strongly prefer using it over opening a new bin (scaled by item size so
    // large items get an extra nudge into their sole fitting bin).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 12.0 + 0.15 * item_size as f64;
    }

    // New-bin candidate: penalize opening a fresh bin, with pressure growing
    // with the number of already-open bins and with stream progression
    // (late in the stream, consolidation matters more).
    if is_new_bin {
        score += 8.0 + 1.5 * open_bins_count as f64 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 100.0 + (10 - post_residual) as f64 * 5.0;
    } else {
        // Penalize large dead space quadratically.
        score += (post_residual as f64).powi(2) * 0.02;
    }

    // 2-step lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain: next item fills bin exactly.
            if post_residual == next_item_size {
                score -= 300.0;
            } else if slack <= 10.0 {
                score -= 120.0 - slack;
            } else {
                score -= 40.0 / (1.0 + slack * 0.1);
            }
        } else {
            // Next item cannot use leftover; penalize proportional to mismatch.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.3;
        }
    }

    // Compare against mean residual of open bins: bins tighter than average are better targets.
    let residual_diff = post_residual as f64 - mean_residual;
    score += residual_diff * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin loses to decent fits.
        score += 250.0;
        // But if item is large and mean residuals are too small to matter, opening is fine.
        if item_size as f64 > mean_residual {
            score -= 150.0;
        }
        // Late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
    }

    // Mild penalty per open bin to encourage consolidation early on.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness.powi(3);

    // Reward exact fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize small unusable leftovers, scaled by what future items may need.
    if post_residual > 0 {
        let small_waste = (post_residual as f64 / bin_capacity as f64).powf(0.5);
        score += 10.0 * small_waste;
    }

    // Lookahead: bonus if the next item fits in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // penalize blocking the next item slightly
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items as f64;
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 15.0 * crowding * (0.5 + progress);

    // Mean residual coupling: if this bin is above average fullness, prefer it.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 8.0 * dev;

    // New-bin candidate: only attractive when no good fit exists
    // (this bin is empty; make it costly unless residuals are all large).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count <= 1 { 0.0 } else { 1.0 };
        score += 20.0 + 30.0 * desperation;
        // Late in the stream, opening a fresh bin is safer than fragmenting.
        if progress > 0.7 && post_residual >= next_item_size {
            score -= 15.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), smoothed polynomially
    let mut score = pr * (1.0 + 0.35 * norm_pr * (1.0 - norm_pr));

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space hurts more; early, keep flexibility.
    let progress_coupling = 0.5 * norm_pr * norm_pr * (2.0 * progress - 1.0);
    score += progress_coupling * cap;

    // Reward bins whose residual aligns with the next item (lookahead synergy)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let match_bonus = (1.0 - gap / cap).max(0.0);
        score -= 8.0 * match_bonus * match_bonus * (0.5 + progress);
    }

    // Penalize wasteful near-empty residual late in the stream
    score += 3.0 * (norm_pr * norm_pr) * progress;

    // Mean-residual deviation coupling: bins far from mean residual are less predictable
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 2 {
        // many options: be pickier about tightness
        score += 1.5 * (fitting_bins_count as f64).ln() * norm_pr;
    }

    // New-bin candidate: penalize opening a bin unless post_residual would be large
    if bin_residual == bin_capacity {
        score += 6.0 + 12.0 * (1.0 - progress) - 5.0 * (item_size as f64 / cap);
    }

    // Mild preference for consolidating among many open bins
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 act as "dead-space classes".
    let class = post_residual % 10;
    // Penalize awkward residue classes (small unusable slivers).
    let class_penalty: f64 = match class {
        0 => -6.0,          // perfect fill
        1 | 2 | 3 => 5.0,   // unusable slivers
        4 | 5 => 1.0,       // marginal
        6 | 7 | 8 | 9 => 2.5,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division tier of post_residual: how many size-10 "slots" remain.
    let slots = post_residual / 10;
    if slots == 0 {
        score -= 4.0; // fully packed bin is excellent
    } else {
        // reward bins whose leftover can host a plausible future item
        score += slots as f64 * 0.4;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // harmonic gap class: how clean is the fit for the next item
            let gap_class = gap % 10;
            score -= 3.0 - (gap_class as f64) * 0.3;
            // penalize if next item would leave another tiny sliver
            if gap < 10 {
                score += 2.0;
            }
        } else {
            // next item cannot use this residual: leftover is likelier dead
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 0.05 * (post_residual as f64);
    }

    // New-bin candidate: penalize opening a new bin, more so mid-stream
    // and when many bins are already open (prefer consolidating).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 6.0 * progress + 0.3 * open_bins_count as f64;
        // but if mean residual across open bins is tiny, opening fresh is fine
        if mean_residual < 5.0 && open_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Tight-fit bonus: item fills a large fraction of the residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 {
        score -= 3.0 * fill;
    }

    // Mean-residual alignment: prefer bins near the mean residual (balanced packing).
    score += 0.2 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers (<10) are nearly unusable
    // given the minimum item size; penalize them heavily (quadratic ramp).
    let dead = if post_residual > 0 && post_residual < 10 {
        (10 - post_residual) as f64
    } else {
        0.0
    };
    score += 8.0 * dead * dead;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; a new empty bin gets a mild penalty that grows with
    // open_bins_count.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins whose residual is below the
    // mean (i.e., tighter bins), pushing toward compacting the fullest bins.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Lookahead: if the next item exactly matches the post residual, this is
    // a perfect two-item pairing; reward heavily.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 40.0;
    }
    // If next item would fit in the post residual, mild reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Early in the stream, be slightly more willing to open bins to build a
    // good pool of partially filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // 2-step lookahead: exact match of post_residual with next item is a jackpot.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            // Reward chains where the next item also fits well.
            let chain = 1.0 - (leftover as f64) / (bin_capacity as f64);
            score -= 25.0 * chain;
            // Penalize leaving a residual barely larger than next item (awkward gap).
            if leftover < 10 {
                score += 8.0;
            }
        } else {
            // Next item won't fit here; mild penalty scaled by the miss distance.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.35 * miss;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are "fresher";
    // filling them is better than scraping old bins.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.25 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize spreading across many open bins slightly; reward consolidation
    // when few bins remain relative to stream length.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score += 0.6 * (open_bins_count as f64) * (1.0 - progress);
    }

    // New-bin candidate: make it attractive only when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let best_possible = 100u32.saturating_sub(item_size);
        // If any open bin would leave a small residual, discourage new bin.
        let poor_fit_elsewhere = mean_residual < (item_size as f64) * 0.9;
        if poor_fit_elsewhere {
            score -= 15.0 + 0.2 * (best_possible as f64);
        } else {
            score += 25.0;
        }
    }

    // Mild early-stream caution: keep residuals flexible early on.
    score += 6.0 * (1.0 - progress) * (post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that no plausible future item (min size 1, typical small)
    // can use: if post_residual is small but nonzero it's actually good (usable),
    // if it's large it's already captured by base term. Reward "usable" band.
    if post_residual >= 1 && post_residual <= 10 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it, else we open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item exactly fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 15.0 - (slack as f64) * 0.1;
        // next item perfectly fills remainder
        if slack == 0 {
            score -= 20.0;
        }
    }
    // If next item cannot fit in post residual, mild penalty for wasting space.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Baseline: new bin has full residual; make it unattractive unless
        // existing options are bad. Penalize opening when many bins fit well.
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        // Early stream: opening bins is cheaper; late stream: consolidate.
        score -= (1.0 - progress) * 10.0;
        // If mean residual of open bins is large, prefer using them.
        score += (mean_residual - post_residual as f64).max(0.0) * 0.3;
        // Many open bins: discourage opening yet another.
        score += open_bins_count as f64 * 1.5;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor),
    // scaled by global mean residual for adaptivity.
    let tightness = (bin_residual as f64 - item_size as f64);
    score += tightness * 0.05 * (1.0 + mean_residual / bin_capacity as f64);

    // Time horizon: late in the stream, be more conservative (avoid spreading).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: minimize leftover space (best-fit core).
    let mut score = post;

    // Non-linear coupling: normalized waste interacts with stream progress.
    // Later in the stream, tight packing matters more (squared waste penalty grows).
    let waste_norm = post / cap;
    score += waste_norm * waste_norm * cap * (0.5 + progress);

    // Reward bins whose residual is "almost exact" (smooth exponential tightness bonus).
    let tightness = (post / cap).exp() - 1.0; // ~0 for tight fits, grows for loose fits
    score += tightness * cap * 0.25;

    // Lookahead: reward if the next item can fit into the post residual (chaining),
    // penalize proportionally more when the fit is snug (good compaction).
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post - next_item_size as f64) / cap;
        score -= (1.0 + snug) * 3.0;
    } else if next_item_size > 0 {
        // Dead space relative to the known next item: penalize unusable gap.
        score += 2.0 + 0.05 * (post - next_item_size as f64).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Mild diversity pressure: prefer bins below mean residual (keeps residuals balanced).
    score += 0.1 * (post - mean_residual);

    // New-bin candidate (pristine bin): make it unattractive unless nothing fits,
    // since its post_residual is large; add extra penalty scaling with open bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
