pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are unusable — penalize them heavily with a superlinear term.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Soft penalty for large leftover space that invites fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 50 {
        score += 0.05 * (post_residual as f64 - 50.0);
    }

    // Open-bin pressure: discourage spreading across many bins late in the stream.
    score += open_bins_count as f64 * 0.3 * (0.5 + progress);

    // Reward tight fits (small post_residual) proportionally to item size.
    score -= item_size as f64 * 0.1 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are truly poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Fraction of bin wasted after placement.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste_frac * waste_frac;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Small gap means next item leaves little dead space too.
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize residuals slightly above next item size
            // (unusable dead space relative to lookahead).
            let over = (next_item_size - post_residual) as f64;
            if over < 20.0 {
                score += 15.0 * (1.0 - over / 20.0);
            }
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If lookahead item fits perfectly in a fresh bin, soften the penalty.
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 30.0;
        }
        // Late in stream, prefer closing out open bins.
        if step_index as f64 / total_items as f64 > 0.8 {
            score += 50.0;
        }
    }

    // Slight preference to fill fuller bins first.
    score -= 0.2 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little dead space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 35.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // Exact chain fit is gold.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Penalize leaving a residual too small to be useful to the next item.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless it's a terrible fit).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0 + 0.15 * item_size as f64;
    }

    // Penalize opening new bins when existing bins are reasonably filled.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_fill = bin_capacity as f64 - mean_residual;
        let pressure = avg_fill / bin_capacity as f64;
        // Opening new bins is fine early / when bins are full, bad otherwise.
        score += 30.0 * (1.0 - pressure);
        score += 4.0 * open_bins_count as f64;
        // Late in the stream, avoid opening bins unless really needed.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If many bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0);
        }
    } else {
        // Prefer fuller bins among open ones (relative to mean residual).
        score += 0.25 * (bin_residual as f64 - mean_residual);
    }

    // Mild preference for using bins when many are already open.
    if !is_new_bin {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Dead-space penalty: residuals that are unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, with non-linear penalty on small residuals
    let mut score = pr as f64;
    score += 40.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = (norm_pr * norm_pr) * (1.0 - progress * 0.5) + (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    score += 25.0 * coupling;

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 30.0 * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > post_residual {
        score += 5.0;
    }

    // Prefer bins with lower residual relative to mean (fill emptier bins first)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // but allow opening when existing residuals are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = 45.0 + 30.0 * fragmentation * (1.0 - progress) - 25.0 * fragmentation * progress;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large residue classes" are more reusable, so reward them.
    let class = (post_residual / 10) % 10; // coarse harmonic bucket 0..9
    let fine = post_residual % 10;

    // Reward exact fills strongly (dead space zero is ideal).
    if post_residual == 0 {
        score -= 45.0;
    } else {
        // Small post_residual is good, but not if it becomes unusable
        // relative to the next item. Harmonic coupling with lookahead.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // leftover can host the next item: reward proportionally
                score -= 12.0 + (post_residual - next_item_size) as f64 * 0.05;
            } else {
                // leftover too small for next item: penalize dead space
                score += (next_item_size - post_residual) as f64 * 0.25;
            }
            // Harmonic bonus: post_residual and next_item_size share a class
            if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
                score -= 6.0;
            }
        }
    }

    // Integer-division thresholds: residues below the minimum item size (10)
    // are guaranteed dead space — penalize by class.
    if post_residual < 10 {
        score += 30.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Coarse class reward: mid-range classes (30..60 leftover) stay flexible
    score -= match class {
        0 => 4.0,
        1 => 2.0,
        2 => 1.0,
        3 | 4 => 3.0,
        5 | 6 => 2.5,
        7 => 1.5,
        _ => 0.0,
    };

    // Fine-grain harmonic tiebreak within class
    score -= fine as f64 * 0.08;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a bin should only win when no open bin
    // gives a tight fit. Penalize the fresh bin mildly but not fatally.
    if bin_residual == bin_capacity {
        score += 8.0;
        // If many bins already fit the item, new bin is clearly worse.
        if fitting_bins_count > 0 {
            score += 10.0 + fitting_bins_count as f64 * 3.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping looser bins for larger future items.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // Many open bins: encourage closing tight bins to reduce spread.
    if open_bins_count > 4 && post_residual < 20 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals that are too small to be useful later
    // (typical item sizes 1..100; gap < 10 is nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.2;
    }

    // Reward exact / near-exact fits aggressively.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual tightly matched the item (small slack ratio).
    let fit_tightness = item_size as f64 / bin_residual as f64;
    score -= fit_tightness * 20.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (if bin_residual == bin_capacity { 1.0 } else { -0.15 });

    // New-bin candidate: baseline cost of opening a fresh bin, modulated by
    // mean residual of open bins (high mean residual => open bins are roomy,
    // so opening another bin is wasteful).
    if bin_residual == bin_capacity {
        score += 55.0 + mean_residual * 0.8 + open_bins_count as f64 * 3.0;
        // But if the next item is large and no open bin could hold both,
        // a fresh bin becomes attractive.
        if next_item_size > 0 && next_item_size > post_residual.min(bin_residual) && next_item_size > 50 {
            score -= 70.0;
        }
    } else {
        // Prefer bins whose leftover can still host the lookahead item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0;
            } else {
                score += 10.0;
            }
        }
        // Slight preference for bins below mean residual (balancing loads).
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of post_residual with next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Reward when next item also fits in the remaining space (chain-friendly)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
    }
    // Penalize dead space that cannot fit the next item, scaled by how close it came
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }
    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // New-bin candidate: penalize unless it enables a better future chain
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }
    // Prefer bins tighter than the mean residual (best-fit-like behavior)
    score -= 0.3 * (mean_residual - post_residual as f64);
    // Early in the stream, be more willing to consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable gaps (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 4.0;
        }
        // Perfect chain: next item exactly consumes what remains.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate logic: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is attractive when the item is large or fits nowhere well.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * item_frac;
        // Prefer new bins when existing bins are, on average, already tight.
        score += 0.3 * (mean_residual - (bin_capacity as f64 - item_size as f64)).max(0.0);
        // Late in the stream, consolidating into open bins is cheaper.
        score += 10.0 * progress;
        // Many open bins: discourage yet another one.
        score += 1.5 * open_bins_count as f64;
    } else {
        // Prefer reusing bins with smaller residuals (best-fit coupling).
        score -= 0.05 * (bin_capacity - bin_residual) as f64;
    }

    // Global state coupling: when mean residual is high, slightly prefer using the
    // emptier bins to spread load; when low, prefer the tightest bin.
    score += 0.1 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Early stream: penalize tight fits slightly to keep flexibility; late stream: reward them
    score += 20.0 * t * (1.0 - t) * (norm_pr - 0.5).abs() * cap * 0.1;
    score -= 15.0 * t * t * norm_pr;

    // Dead-space penalty: residuals too small to hold typical items
    let unusable = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * 2.0 } else { 0.0 };
    score += unusable;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 4.0;
        }
    }

    // Mean residual interaction: bins far from mean residual get smoothed preference
    score += 0.15 * (pr - mean_residual).abs();

    // Mild preference to fill existing bins when many are open
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: penalize opening a fresh bin unless item is large
    if bin_residual == bin_capacity {
        score += 30.0 - 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity-quarter classes
    let quarter = bin_capacity / 4;
    let r_class = post_residual % quarter;
    // Penalize residuals that fall into "dead zone" classes (small unusable slivers)
    if post_residual > 0 {
        if r_class == 0 {
            score -= 6.0; // perfectly divisible residual, great for future harmonic items
        } else if post_residual < 10 {
            score += 25.0 + (10 - post_residual) as f64; // tiny dead space, essentially wasted
        } else if post_residual < quarter / 2 {
            score += 8.0; // awkward small residual
        }
    }

    // Integer-division threshold coupling: does post_residual fit the lookahead item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // lookahead fits: reward proportional to tightness of that future fit
            let future_fit = (post_residual - next_item_size) as f64;
            score -= 10.0 + 5.0 * (1.0 - future_fit / bin_capacity as f64);
        } else {
            // lookahead cannot use this residual: penalize more if residual is large
            score += 0.5 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    } else {
        // last item: prefer fullest packing, dead space doesn't matter anymore
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tightest fit (post_residual term already does)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual / bin_capacity as f64;
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.35;
        if open_bins_count == 0 {
            score -= 50.0; // must open a bin
        } else if crowded < 0.15 && poor_fit {
            score -= 12.0; // bins nearly full and item is small: fresh bin is fine
        } else if poor_fit && fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 30.0 + 20.0 * (1.0 - progress); // discourage abandoning open space early
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's "loose" space;
    // prefer filling loose bins to consolidate
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Modulo-10 harmonic bonus on exact residual classes (common item-size multiples)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Mild step decay: late in the stream, tighter packing matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: penalize placements into bins when many bins are open,
    // encouraging consolidation into fewer bins.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.3;
        // If next item is large and would fit in fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size >= post_residual && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Lookahead coupling: reward leaving space exactly matching the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 5.0;
    }

    // Stream progression: later in the stream, be slightly more conservative about
    // dead space since fewer items remain to fill gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    // Mean residual coupling: if bin residual is far from mean, adjust.
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: reward tight fits (low post_residual relative to capacity).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 30.0;

    // Aggressive 2-step lookahead: strongly reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 35.0 * (1.0 - gap / (bin_capacity as f64)); // next item fits well here
        } else {
            // next item cannot fit in the residual: penalize proportional to wasted slack
            score += 12.0 * (1.0 - post_residual as f64 / (bin_capacity as f64));
        }
    } else {
        // last item: pure tight-fit reward
        score -= 20.0 * (1.0 - tightness);
    }

    // Compare residual against mean residual across open bins: prefer consolidating
    // space into bins that are already emptier than average (keep tight bins tight).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Penalize creating very small unusable slivers unless next item can use them.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 25.0;
    }

    // Mild penalty for opening a new bin when plenty of open bins exist and fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0; // discourage new bin if some open bin fits
        }
    }

    // Prefer spreading across many bins slightly less when few bins are open.
    if open_bins_count <= 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.15 * next_item_size as f64;
    }
    // Penalize bins whose leftover is just barely below the next item (near-miss waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidation into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: attractive early or when mean residual is small,
    // but discouraged when a decent existing fit exists.
    if bin_residual == bin_capacity {
        let mean_pressure = mean_residual / bin_capacity as f64;
        let new_bin_bonus = 12.0 * (1.0 - progress) + 30.0 * (1.0 - mean_pressure.min(1.0));
        score -= new_bin_bonus;
        // If the item is large and leaves little waste anyway, opening fresh is fine;
        // if it wastes a lot of a fresh bin, discourage it.
        score += 0.5 * post_residual as f64;
    }

    // Slight preference for bins already below the mean residual (balance utilization).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Normalize post-residual and item size
    let pr = post_residual as f64 / bin_capacity as f64;
    let it = item_size as f64 / bin_capacity as f64;
    let nx = next_item_size as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: waste penalty grows quadratically with residual
    // and is modulated by stream progress (late stream => more penalty for waste).
    let waste_curve = pr * pr * (1.0 + progress * (2.0 - pr));
    score += 30.0 * waste_curve;

    // Lookahead synergy: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (pr - nx).abs();
        score -= 12.0 * (1.0 - gap) * (1.0 - progress * 0.5);
    } else if next_item_size > post_residual as f64 as u32 {
        // post-residual too small for next item: penalize dead space smoothly
        score += 8.0 * nx * (0.5 + progress);
    }

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mean-residual coupling: placing into a bin far below mean residual is
    // mildly favored (balances residual distribution), via smooth cubic term.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev * dev * dev;

    // New-bin candidate handling: penalize opening a new bin when decent fits exist,
    // but allow it early in the stream or when remaining items are large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 15.0 * open_pressure * (1.0 - progress * 0.3);
        if next_item_size > 0 && next_item_size >= post_residual as u32 {
            score -= 6.0 * nx;
        }
    }

    // Mild preference for tight fits overall (small post-residual relative to item)
    score -= 5.0 * it * (1.0 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: class 0 (perfect fit) is ideal.
    let class = post_residual % 10;
    score -= (10 - class) as f64 * 1.5; // reward small remainders

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fits (small leftover) get graded bonuses by class.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Dead-space penalty: leftover that no plausible item (1..100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny slivers are wasted but acceptable
    }

    // Harmonic coupling with the next item: if the leftover can host the next item
    // in a near-perfect way, strongly favor this bin (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_left = post_residual - next_item_size;
        score -= 60.0 - (chain_left as f64) * 1.2;
    }

    // Penalize leftovers in "bad" harmonic classes relative to common item sizes.
    let bad_class = (post_residual % 20 == 11) || (post_residual % 20 == 13);
    if bad_class {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + (post_residual as f64).min(50.0);
    }

    // New-bin candidate: opening a fresh bin is only attractive when no existing
    // bin fits decently. Penalize new bins more as stream progresses (fewer
    // chances to fill them) and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 + 200.0 * progress + 10.0 * open_bins_count as f64;
        // But if the item is huge relative to mean residual space, opening may win.
        let mean_res_u = mean_residual as u32;
        if mean_res_u < item_size {
            score -= 90.0;
        }
        // Large items fragment bins; a fresh bin for a big item late in stream is fine.
        if item_size > 70 {
            score -= 40.0 * progress;
        }
    }

    // Mild preference to fill bins below the mean residual (balance avoidance of
    // many half-empty bins): a bin with residual far above mean is a better target.
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score -= (res_f - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: post residual, with a superlinear penalty for small unusable gaps.
    let pr = post_residual as f64;
    score += pr * 0.01;

    // Dead-space penalty: residuals that are small but nonzero are nearly useless
    // (items are >= 1, but tiny gaps rarely fit future items well).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: fraction of residual consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Open bins pressure: discourage spreading items when many bins are open,
    // but allow opening a new bin when current bins would leave bad gaps.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64 * 10.0);
    score += pressure * 0.8;

    // Mean residual coupling: placing into a bin far from mean residual is risky.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // New empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Default cost of opening a new bin.
        score = 100.0 - item_size as f64 * 0.2;
        // If the only alternative is a poor fit (large dead space), make new bin cheaper.
        if fitting_bins_count == 1 && (bin_residual - item_size) > post_residual {
            score -= 30.0;
        }
        if post_residual == 0 {
            // Perfect fit exists elsewhere; never open a new bin.
            score += 200.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) with a mild convexity so
    // large dead spaces are punished super-linearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // ---- 2-step lookahead: reward post_residual matching next_item_size ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        // Perfect chain match: post_residual == next_item_size -> strong reward.
        if diff < 0.5 {
            score -= 25.0;
        } else {
            // Proximity reward: closer match => bigger bonus (Gaussian kernel).
            let sigma = 8.0;
            score -= 18.0 * (-(diff * diff) / (2.0 * sigma * sigma)).exp();
        }
        // If next item can't fit here either way, slight penalty for wasteful fill
        if pr < nxt && pr > 0.0 {
            score += 3.0 * (pr / 100.0);
        }
    } else {
        // Last item: minimize post_residual exactly (no future to plan for).
        score = pr + 0.5 * pr * pr / bin_capacity as f64;
    }

    // ---- Relative-to-mean coupling: bins with residual far below mean are
    // already "cramped"; filling them further is fine, but bins far above mean
    // should absorb items to consolidate space. ----
    let rel = pr - mean_residual;
    score += 0.08 * rel;

    // ---- Last-chance bonus: if this is the ONLY bin that can fit the item,
    // strongly favor it over opening a new bin (unless fit is terrible). ----
    if fitting_bins_count == 1 {
        score -= 30.0;
        // but still avoid ultra-tiny leftovers if new bin would be cleaner
        if pr > 0.0 && pr < 5.0 {
            score += 10.0;
        }
    }

    // ---- New-bin candidate handling: an empty bin has bin_residual == capacity.
    // Prefer reusing an existing bin unless the current item leaves a very
    // fragmented residual or the empty-bin chain is attractive. ----
    if bin_residual == bin_capacity {
        // Empty bin baseline: keep it moderately high so reuse wins normally.
        score = (bin_capacity as f64) * 0.75;
        // If next item is large and current item is small, opening fresh may
        // allow a clean pairing: reward the new-bin option.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let pair = item_size as f64 + nxt;
            if pair >= bin_capacity as f64 {
                score -= 20.0;
            }
            // If item perfectly pairs with the next item in a fresh bin, favor it.
            let gap = (bin_capacity as f64 - pair).abs();
            score -= 15.0 * (-(gap * gap) / (2.0 * 6.0 * 6.0)).exp();
        }
        // Late in the stream, slightly discourage spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * progress;
    }

    // Mild penalty for many open bins already (encourage consolidation).
    score += 0.6 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base, amplify non-linearity.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is extremely desirable
    } else if post_residual <= 5 {
        score -= 25.0 + (5 - post_residual) as f64 * 3.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize leaving dead space that nothing else could plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver for items >= 10... but sizes can be 1..100
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            score -= 20.0; // actually next item fits perfectly here
        }
    }

    // Lookahead coupling: if the next item fits in the post-residual, big reward.
    if next_item_size > 0 {
        let fits_next = (post_residual as u32 >= next_item_size) as i32;
        if fits_next == 1 {
            let tightness = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 15.0 + 20.0 * tightness;
        } else {
            // next item won't fit here; slight penalty proportional to wasted lookahead
            score += 4.0;
        }
        // If next item also fits in current residual along with current item -> chain reward
        if item_size + next_item_size <= bin_residual {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many fitting bins: mild penalty to encourage exploring tighter alternatives.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state: if mean residual is high, bins are loose; prefer consolidating into fuller bins.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fullness * (mean_residual / bin_capacity as f64).clamp(0.0, 2.0);

    // Time horizon: early in stream, be conservative (penalize opening new bins less);
    // late in stream, strongly prefer closing out bins with tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * fullness;

    // New-bin candidate arbitration: only open a new bin when no open bin is a good host.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by state.
        let mut new_bin_cost = 35.0;
        // If many bins already open and mean residual is low, prefer reusing.
        if open_bins_count > 3 && mean_residual < 30.0 {
            new_bin_cost += 20.0;
        }
        // If few bins fit the item, opening new bin is more acceptable.
        if fitting_bins_count == 0 {
            new_bin_cost -= 40.0;
        } else if fitting_bins_count == 1 {
            new_bin_cost -= 10.0;
        }
        // Late in stream, avoid proliferating bins.
        new_bin_cost += 15.0 * progress;
        score += new_bin_cost;
    }

    // Small non-linear coupling on item size: large items deserve careful placement.
    if item_size > 60 {
        score -= 5.0 * fullness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = it / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap; // 0..1
    let t = progress;
    // Smooth interaction: residual wastefulness weighted by progress phase.
    let coupling = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * t;
    score += 12.0 * coupling * cap * 0.01;

    // Reward tight fits (small post_residual) with a smooth polynomial bonus.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 25.0 * tightness * (0.5 + 0.5 * t);

    // Penalize residuals that cannot fit the lookahead item (dead space).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let gap = (ni - pr) / cap;
            score += 18.0 * gap * gap * cap * 0.01;
        } else {
            // Reward bins whose leftover can serve the next item.
            let usable = (pr - ni) / cap;
            score -= 8.0 * usable * (1.0 - usable);
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: keep it unattractive unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score = cap - it as f64;
        score += 20.0 * (1.0 - fit_ratio).powi(2);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        score += 0.05 * open_bins_count as f64 * t;
    }

    // Mild preference toward fuller bins relative to mean residual.
    score -= 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer smallest post_residual (best-fit core), scaled.
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: mod-10 classes capture capacity fractions.
    let pr = post_residual;
    let cls = pr % 10;
    // Dead-space penalty: residuals that are "awkward" (nonzero small classes) get punished.
    if pr > 0 {
        match cls {
            0 => score -= 6.0,              // perfectly divisible residual -> reusable
            1 | 2 | 3 => score += 4.0,      // tiny slivers are dead space
            4 | 5 => score += 1.5,
            6 | 7 | 8 => score += 0.5,
            9 => score -= 1.0,
            _ => {}
        }
    }
    if pr == 0 { score -= 12.0; }           // perfect closure

    // Integer-division threshold: how many "typical" items (size ~20) still fit.
    let fits20 = pr / 20;
    score -= fits20 as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size < pr {
            let nxt_cls = (pr - next_item_size) % 10;
            score -= 2.0 + (10 - nxt_cls) as f64 * 0.3;
        } else {
            score += 2.0; // next item won't fit here; slight penalty
        }
        // Harmonic fraction: next item as fraction of capacity
        let frac = next_item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            // big next item: keep large residuals available
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: empty bin should only win when placement is terrible elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0
            + mean_residual * 0.1
            + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 { score -= 40.0; }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing big item then next big item in fresh bin
        }
    }

    // Stream progression: late in stream, close bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr as f64) * 0.15;

    // Mean residual coupling: penalize creating above-average waste.
    if pr as f64 > mean_residual {
        score += (pr as f64 - mean_residual) * 0.2;
    } else {
        score -= (mean_residual - pr as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gaps are only usable for tiny items; penalize proportionally.
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that the lookahead item can use.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap will be dead for the next item too.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 30.0 + 4.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into existing bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 * progress;
        }
        // If an existing bin takes the item to near-full, never open a new bin.
        if item_size >= bin_capacity - 20 {
            score += 100.0;
        }
    } else {
        // Reward tightening well-filled bins.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
        // Prefer bins with below-mean residual (spread large gaps evenly).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.6;
        // Perfect 2-chain: this item + next item fill bin exactly.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item would fit leaving tiny waste -> strong bonus.
        if next_item_size <= post_residual && post_residual - next_item_size <= 5 {
            score -= 25.0;
        }
        // Next item cannot fit here anyway; mildly penalize large leftovers.
        if next_item_size > post_residual && post_residual > 0 {
            score += post_residual as f64 * 0.3;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 10.0;
    }

    // Penalize bins whose residual deviates far below mean (badly fragmented bins).
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect chain.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 30.0;
        }
    }

    // Early in stream: keep bins flexible (avoid tiny residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && post_residual > 0 {
        score += (1.0 - progress) * 8.0;
    }

    score
}
